INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4f6c6423-fe68-5ba5-a803-351290ef4303', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 1, 10, 'መልአኩም እንዲህ አለኝ፥ “ያየኸው የዚህ ሕልምህ ትርጓሜ እንዲህ ነው።'),
  ('6798dc6f-1102-5a20-a027-d3901c223a84', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 2, 11, 'ከባሕር ሲወጣ ያየኸው ይህ ንስር ለወንድምህ ለዳንኤል በሕልም የታየችው አራተኛዋ መንግሥት ናት።'),
  ('093daf42-4a98-5ac3-acc8-ea8fbedd66a2', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 3, 12, 'ነገር ግን ዛሬ ለአንተ እኔ እንደተረጐምሁልህ ለእርሱ አልተረጐምሁለትም።'),
  ('50ae4a47-21d6-5e68-ae2d-14e034466eb8', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 4, 13, 'እነሆ፥ ዘመን ይመጣል፤ በምድርም ከእርስዋ አስቀድሞ ከነበሩት መንግሥታት ይልቅ የምታስፈራ መንግሥት ትነሣለች።'),
  ('99b751b1-9f34-5c52-a7eb-e12579d5e537', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 5, 14, 'በእርሷም ዐሥራ ሁለት ነገሥታት በተከታታይ ይነግሣሉ።'),
  ('0af41344-9018-5bef-ae45-ed1cc334c6ca', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 6, 15, 'ቀጥሎ የሚነግሠውም በዘመኑ ከዐሥራ ሁለቱ ነገሥታት ፈጽሞ የሚጸና ነው።'),
  ('7f800993-3df2-5128-a0bb-c9c25fae5feb', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 7, 16, 'ያየሃቸው የእኒህ የዐሥራ ሁለቱ ክንፎች ትርጓሜ ይህ ነው።'),
  ('971492e9-5c9d-53a9-af94-155b5c4f095c', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 8, 17, 'ቃልን ሲናገር ያየኸው ይህም ከሥጋው መካከል ነው እንጂ ከራሱ የሚወጣ ሁለተኛው አይደለም።'),
  ('47d593fa-83a0-5b32-a94d-fba665c20750', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 9, 18, 'ትርጓሜውም እንዲህ ነው፤ ከዚያ መንግሥት ወገን መካከል ብዙ ሁከት ይፈጠራል፤ መንግሥትም ለመውደቅ ትንገዳገዳለች፤ ነገር ግን ጸንታ ትኖራለች እንጂ ያንጊዜ አትወድቅም።'),
  ('25dd21d7-f9a2-5727-a5cf-0befd9965a25', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 10, 19, 'ከክንፎቹም ራሶች ሲወጡ ያየኸው ይህ፥'),
  ('86c13dec-99aa-5116-a18f-050505b02104', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 11, 20, 'ትርጓሜው እንደዚህ ነው፤ ስምንቱ ነገሥታት በእርስዋ ይነግሣሉ፤ ዘመናቸውም የከፋ፥ ወራታቸውም ያጠረ ይሆናል፤ ከእነርሱ ሁለቱ ግን በዘመናቸው መካከል ፈጥነው ይጠፋሉ።'),
  ('b157fc6a-b6aa-59cb-a2ca-2dfa73d974a4', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 12, 21, 'ነገር ግን አራቱ መንግሥታት የሚጠፉበት ጊዜ እስኪደርስ ድረስ ይጠበቃሉ፤ ሁለቱም ለብዙ ዘመን ይጠበቃሉ።'),
  ('02ceb986-93a4-533b-ace0-d42bcac78e11', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 13, 22, '“ዝም ብለው ያየሃቸው እነዚህ ሦስቱ ራሶችም፦'),
  ('5439480c-1258-508b-ad6b-302493e5cd8d', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 14, 23, 'ትርጓሜው እንዲህ ነው፤ ልዑል በኋላ ዘመን ሦስት ነገሥታትን ያስነሣል፤ በውስጧም ብዙውን ያድሳሉ፤ ምድርንም ያሠቃዩአታል።'),
  ('83d76cc0-8c15-58ba-ab83-ad4c6a828548', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 15, 24, 'በውስጧ የሚኖሩትንም ከእነርሱ በፊት ከነበሩት ሁሉ ይልቅ እጅግ ያሠቃዩአቸዋል። ስለዚህም የንስሩ ራሶች ተባሉ።'),
  ('25e44ad2-dd4d-51ec-ab80-2e341df98739', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 16, 25, 'እነርሱ የመንግሥት መጀመሪያዎች፥ የመንግሥትም መጨረሻዎች ናቸውና።'),
  ('40868437-2709-59dd-a383-c232721e1ac9', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 17, 26, 'ይህም ሲጠፋ ያየኸው አንዱ ታላቅ ራስ በታላቅ ጻእር ተጨንቆ በመኝታው የሚሞት ከእነርሱ አንዱ ነው።'),
  ('e809ab12-f45b-59a8-a48b-f45b4bff2c59', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 18, 27, 'የቀሩት እነዚያ ሁለቱ ግን በጦር ይሞታሉ።'),
  ('b82381ac-e431-5d22-a725-618d0f295ceb', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 19, 28, 'አንዱ ኋለኛውም በጦር ይሞታል።'),
  ('818a59be-5e0b-55ab-a4c2-8b99dfdd37ab', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 20, 29, '“በቀኝ በኩል ወደ አለው ራሱ የሄዱት እነዚያ ያየሃቸው ሁለት ራሶችም፥'),
  ('d9974e16-7330-5c38-a728-82a542fff514', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 21, 30, 'ትርጓሜው ይህ ነው፤ ልዑል በኋላ ዘመን የጠበቃቸው፥ መጀመሪያው ጥፋት የሚደረግባቸው ናቸው፤ አንተ እንዳየኸውም ብዙ ጸብ ይደረጋል።'),
  ('5871eb20-54b3-5245-a76e-cc694d99e197', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 22, 31, 'ከዱር እያገሣ ሲወጣ ያንም ንስር በሰማኸው ሁሉ ነገር ሲናገረውና በኀጢአቱ ሁሉ ሲዘልፈው ያየኸው ይህ አንበሳም፥'),
  ('030eacce-bda6-50ed-a035-8fdae2bf886d', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 23, 32, 'ልዑል ለኋላ ዘመን የጠበቀው፥ ከዳዊትም ወገን የሚወለደው ነው፤ መጥቶም ኀጢአታቸውን ይነግራቸዋል፤ ስለበደላቸውም ይዘልፋቸዋል፤ በፊታቸውም ፍዳቸውን ይገልጥባቸዋል።'),
  ('719e4c6c-bfc7-50f1-a163-8a26a2f0a795', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 24, 33, 'በሕይወት ሳሉም አስቀድሞ በፍርድ ያቆማቸዋል፤ ከዘለፋቸውም በኋላ ያንጊዜ ያጠፋቸዋል።'),
  ('61029e6e-4766-54d3-a41e-0fa5ba1d7d1d', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 25, 34, 'ትሩፋኑን ግን በቸርነቱ በከበረ አውራጃ ይቤዣቸዋል፤ አስቀድሜም የነገርሁህ የፍርድ ቀን እስኪደርስ ድረስ ደስ ያሰኛቸዋል።'),
  ('ac6038c7-05b3-5733-a477-c661afeb6a90', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 26, 35, 'ያየኸው ሕልምህ ይህ ነው፤ ትርጓሜውም እንደዚህ ነው።'),
  ('4f2ac424-90b9-5e43-add7-ca89a633fb44', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 27, 36, 'ልዑል ይህን ምሥጢር አንተ ብቻ እንድታውቀው አደረገልህ።'),
  ('6d413e6e-33a3-554a-a860-11e41ef6af61', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 28, 37, 'ነገር ግን ይህን ያየኸውን ሁሉ ጻፈው፤ በተሰወረ ቦታም አኑረው።'),
  ('e2d061b9-763e-5bef-a7f8-761db4f177e7', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 29, 38, 'ይህንም ምሥጢር በልቡናቸው ለመጠበቅ እንዲቻላቸው አንተ ለምታውቃቸው ለጠቢባን አስተምራቸው።'),
  ('41ad36e1-aae4-5267-a2ac-90521f1d539e', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', '3b449daf-0409-54fa-a4d6-9c7524e4c2a9', 30, 39, 'አንተ ግን ልዑል ሊያሳይህ የሚወድደውን ታይ ዘንድ ዳግመኛ ሰባት ቀን በዚህ ተቀመጥ።”'),
  ('ec59a704-a00d-5f5a-a316-e48cc5e756ca', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 1, 40, 'ከዚህም በኋላ ከእኔ ተለይቶ ሄደ፤ እኒያ ሰባት ቀኖች እንዳለፉ፥ እኔም ወደ ከተማ እንዳልገባሁ ሰዎች ሁሉ በሰሙ ጊዜ፥ ሕዝቡ ሁሉ ትንሹም ትልቁም ተሰብስበው ወደ እኔ መጡ፤ እንዲህም አሉኝ፦'),
  ('7b61c8c7-ca08-53f9-a896-018fa135bfa7', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 2, 41, '“እኛን ትተኸን በዚህ ምድረ በዳ ትኖር ዘንድ ምን በደልንህ? ምንስ ግፍ ሠራንብህ?'),
  ('1c9a6810-3b86-5506-a27e-5736376e20ae', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 3, 42, 'ከሚለቅሙት ፍሬ ሁሉ እንደ አንድ ፍሬ፥ በጨለማ ቦታ ውስጥም እንደ አለ መብራት፥ ከጥልቅም እንደሚያድን የመርከብ ወደብ ከነቢያት ሁሉ አንድ አንተ ብቻ ቀርተህልናልና።'),
  ('f2616412-6df1-5581-a09b-7ffdd096426f', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 4, 43, 'ወይስ ያገኘችን መከራ አልበቃችንምን?'),
  ('73d5485b-2c46-5e14-ae86-f0376a6826b3', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 5, 44, 'አንተስ የምትለየን ከሆነ ጽዮን በተቃጠለች ጊዜ ብንኖር በተሻለን ነበር፤'),
  ('60d8cfad-86be-51f8-ae1e-516143e7462a', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 6, 45, 'በዚያ ከሞቱት ሰዎች እኛ የምንሻል አይደለንምና።” በታላቅ ድምፅም አለቀሱ።'),
  ('a417f9e7-831f-5858-a6ba-f71fd2bcb7a1', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 7, 46, 'እኔም መለስሁላቸው፤ እንዲህም አልሁአቸው፥ “የያዕቆብ ልጆች እመኑ፤ የእስራኤልም ወገኖች አትዘኑ።'),
  ('ca63fd0b-eb90-5a18-a3da-85b4a814b685', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 8, 47, 'መታሰቢያችን በልዑል ፊት አለና፥ የማይዘነጋን እርሱም ጽኑዕ ነውና።'),
  ('e18fb4c2-a05b-51b4-a275-b1506b00b0b3', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 9, 48, 'እኔስ አልተዋችሁም፤ ከእናንተም አልርቅም፤ ነገር ግን ወደዚህ ቦታ የመጣሁት ስለ ጽዮን ጥፋት እለምን ዘንድ ነው፤ በደስታችን ላይ ስለ መጣብንም መከራ ይቅርታን እለምን ዘንድ ነው።'),
  ('6571142d-96a1-5c2c-ae67-8b8ade38f747', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 10, 49, 'አሁንም ሁላችሁ ወደየቤታችሁ ግቡ፤ እኔም ወደ እናንተ እመጣለሁ።”'),
  ('bc9b65c6-942f-50b9-a091-64a7a82373b9', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 11, 50, 'ከእነዚያም ወራቶች በኋላ ሕዝቡ እንዳዘዝኋቸው ወደ ከተማ ወደየቤታቸው ገቡ።'),
  ('6a9e00f8-da58-5566-ab89-5ab057cabf0c', 'b7affe21-42b5-54a3-af41-ff0fdee1275e', 'b472fef4-39c6-5cc6-ae41-1d5e05697e42', 12, 51, 'እኔ ግን መልአኩ እንዳዘዘኝ በዚያ ቦታ በምድረ በዳው ውስጥ ሰባት ቀን ተቀመጥሁ፤ ከምድረ በዳ ፍሬ ብቻም ተመገብሁ፤ በእነዚያም በሰባቱ ቀኖች ከምድረ በዳው ቅጠል በላሁ።'),
  ('d66e819b-ecec-57b3-a275-af5a68239a0b', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 1, 1, 'ከዚህም ከሰባተኛው ቀን በኋላ በሌሊት ሕልምን አየሁ።'),
  ('034304cc-ae61-5478-a4dd-c487a20e15f6', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 2, 2, 'እነሆ፥ ጽኑ ነፋስ ከባሕር ሲወጣ አየሁ፤ ማዕበሎቹም ሁሉ ታወኩ።'),
  ('560eff7e-e2db-5051-a4ae-544575ff209e', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 3, 3, 'ያም ነፋስ በሰው አምሳል ከባሕሩ ሲወጣ አየሁ፤ ከዚህ በኋላ ያ ሰው ከሰማይ ደመናዎች ጋር ወጣ፤ ፊቱንም መልሶ ባየ ጊዜ፥ ሁሉ በጊዜው ጊዜ ወደ እርሱ ይመጣል።'),
  ('e4b6f855-aa9a-50f9-ab00-9cc95afb6087', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 4, 4, 'ቃሉም በወጣ ጊዜ ከቃሉ የተነሣ ሁሉ ይቀልጣል፤ ቃሉን የሰሙት ሁሉም አደሮ ማር ወደ እሳት በቀረበ ጊዜ እንደሚቀልጥ ይቀልጣሉ።'),
  ('3aa44938-1300-5f1d-a286-aafff1d27d1e', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 5, 5, 'ከዚህ በኋላ ቍጥር የሌላቸው ብዙ ሰዎች ከባሕር የወጣ ይኽን ሰው ይዋጉት ዘንድ ከአራቱ ማዕዘን ሲሰበሰቡ አየሁ።'),
  ('c7c7abfb-80fa-54cb-ac5a-0cbc8c7fea5f', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 6, 6, 'ከዚህ በኋላም ታላቅ ተራራን ሠራ፤ በላዩም ተቀመጠ።'),
  ('3d31b0dd-8908-59fe-a771-9cb46f134dfa', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 7, 7, 'ያ ተራራም የተሠራበትን ላውቅ ወደድሁ፤ ነገር ግን አልቻልሁም።'),
  ('cbf86f61-d136-5893-a0ea-745ea80f2f87', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 8, 8, 'ከዚህም በኋላ ይጣሉት ዘንድ የተሰበሰቡት ሁሉ ፈጽመው ፈሩት። ነገር ግን ይዋጉት ዘንድ ደፈሩ።'),
  ('0795b7ba-59b8-5564-ae60-3f4e2587a07b', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 9, 9, 'ከዚህም በኋላ በከበቡት ጊዜ፥ ወደ እርሱም በመጡ ጊዜ እጁን በእነርሱ ላይ አላነሣም፤ ጦርን ወይም ማናቸውንም የጦር መሣሪያ አላነሣም።'),
  ('6834bb8d-4a3a-5db5-a739-4ae54b2b58a4', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 10, 10, 'ከአፉ የእሳት ማዕበልን፥ ከከንፈሩም የእሳት ነበልባልን፥ ከአንደበቱም የእሳት ፍምን እንደ ጥቅል ነፋስ አወጣ እንጂ፤ ያ የእሳት ማዕበል፥ ያም የእሳት ነበልባል፥ ያም የእሳት ፍም ሁሉ ተቀላቅሎ እንደ ጥቅል ነፋስ ሆነ።'),
  ('a43c2d2d-0a6a-5de4-ac7f-1711e1fdea23', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 11, 11, 'ሊገድሉት በከበቡት በእነዚያ በብዙዎች ላይም ወረደ፤ ከዐመዳቸው ትቢያና ከቃጠሏቸው ጢስ በቀር ከእነርሱ የተረፈ እስከማይኖር ድረስ ሁሉንም አቃጠላቸው። ከዚህም በኋላ ደንግጬ ነቃሁ።'),
  ('2c64f18b-3341-5a08-a2b2-77f66c7bb40e', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 12, 12, 'ከዚህም በኋላ ያን ሰው ከዚሁ ተራራ ሲወርድ አየሁት፤ ለእርሱ የሚስማሙ ብዙዎች ሌሎችንም ወደ እርሱ ጠራ።'),
  ('a99fc750-cc0a-5f1a-a192-c6fa8a61c856', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 13, 13, 'ብዙ ሰዎችም ወደ እርሱ መጡ፤ ከእነርሱም ደስ ያላቸው ነበሩ፤ ከእነርሱም ያዘኑ ነበሩ፤ ከእነርሱም እስረኞች ነበሩ። ከዚህ በኋላ ይህ ሁሉ በደረሰብኝ ጊዜ ደንግጬ ነቃሁ፤ ወደ ልዑልም ጸለይሁ።'),
  ('d4ebc6f1-0bd2-5687-a1b6-c452de311eb2', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 14, 14, 'እንዲህም አልሁ፥ “ቀድሞ አንተ ይህን ጌትነትህን ለባሪያህ አሳየኸው፤ ጸሎቴንም ትሰማ ዘንድ አደረግህልኝ።'),
  ('6c09c38e-3f30-5feb-a72c-37ebae130b29', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 15, 15, 'አሁንም የዚህን የሕልሜን ትርጓሜ ዳግመኛ ንገረኝ።'),
  ('bfafc7d0-fbbc-5adb-accd-9bd2d2b268d2', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 16, 16, 'ነገር ግን እኔስ እንደምጠራጠረው በእነዚያ ወራቶች ለሚኖሩ ሰዎች ወዮላቸው! ይልቁንም ላልነበሩት ወዮላቸው!'),
  ('4b8c171a-d585-581f-ac0d-57572e651a0e', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 17, 17, 'በኋላ ዘመን የሚቈያቸውን ገና ያልደረሰላቸውን ባለማወቅ ያዝናሉና።'),
  ('652d75e5-3e21-56ea-a6a2-1e1aa29defe8', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 18, 18, 'ላሉት ግን ፈጽመው ስላወቁት ነው።'),
  ('d329bd5c-5e95-5977-ade5-3cd8d4d7df10', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 19, 19, 'ስለዚህም ወዮላቸው! በዚህ ሕልም እንዳየሁ ታላቅ ጭንቅንና ብዙ ድካምን ያያሉና።'),
  ('4ffdbc50-13bf-5192-ac95-bd1c97081b19', '3dc51a09-4162-5889-a72d-a85d935daeac', '797e37c4-757d-5a50-a5bf-0818c3531bf4', 20, 20, 'ነገር ግን ይህ ሳይደርስ መከራ መቀበል ይሻላል፤ እንደ ደመናም ከዚህ ዓለም ያልፉ ዘንድ ይሻላል፤ በኋላ ዘመን የምታገኛቸውን አያውቁምና።”'),
  ('f6429b4c-691c-58b1-a734-9edec0cd8958', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 1, 21, 'እርሱም መለሰልኝ እንዲህም አለኝ፥ “የዚህን የሕልምህን ትርጓሜ እነግርሃለሁ፤ ይህን ያልኸኝንም እተረጕምልሃለሁ።'),
  ('db7f4cc7-5917-530a-a36e-e2a5e7eee936', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 2, 22, 'ስለሚቀሩትና ስለሚኖሩት ተናግረሃልና ትርጓሜው እንዲህ ነው።'),
  ('91ed5a17-a2e7-5dc8-ae7c-52f9da349b96', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 3, 23, 'በእነዚያ ወራቶች ያን መከራ የሚያዩት እነዚያ የሚቀሩት ናቸው፤ ያም መከራ የሚያገኛቸውንና በልዑል ዘንድ ሃይማኖትና በጎ ምግባር፥ ጽናትም ያላቸውን እርሱ ራሱ ይጠብቃቸዋል።'),
  ('a0d6f4ad-8de2-5601-a4fe-611ea9ad8a45', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 4, 24, 'ነገር ግን ከሞቱት ይልቅ በሕይወት የቀሩት ፈጽመው ብፁዓን እንደ ሆኑ ዕወቅ።'),
  ('2f958c97-a927-5d4a-ad40-b0f4f232079b', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 5, 25, 'የዚህስ የሕልምህ ትርጓሜው እንደዚህ ነው፤ ከባሕር ሲወጣ ያየኸው ይህ ሰው፥'),
  ('43d3b9e6-2f07-579a-af9f-4515ad70e80c', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 6, 26, 'ዓለሙን ሁሉ በእርሱ ያድን ዘንድ ለኋላ ዘመን ልዑል የጠበቀው ይህ ነው። እርሱም የተረፉትን በሥርዐት ያኖራቸዋል።'),
  ('506328a3-ae63-5dc8-a971-21784ee62f49', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 7, 27, 'እንደ ጥቅል ነፋስ ከአፉ የእሳት ነበልባል፥ የእሳትም ፍሕም ሲወጣ ያየኸው፥'),
  ('9f9f6c5e-d33b-5431-a7aa-86db8de07c46', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 8, 28, 'ጦሩን ወይም የጦር መሣሪያውን ያላነሣ፥ ግን የከበቡትንና ሊገድሉት የመጡትን እነዚያን ብዙዎችን ያጠፋቸው ትርጓሜው እንዲህ ነው።'),
  ('ded7f97d-7f2e-50ac-a454-b5ddfbab7ba0', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 9, 29, 'በምድር የሚኖሩትን ልዑል የሚያድንበት ዘመን ይመጣል።'),
  ('ffa10fd1-acda-5602-ac8d-c0039c208861', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 10, 30, 'ያንጊዜ እርስ በእርሳቸው ይወነጃጀላሉ።'),
  ('3752b7b8-48ab-5c28-a8c7-3e077f8a27b4', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 11, 31, 'ከተማ ከከተማ ጋር፥ ገጠር ከገጠር ጋር፥ ሕዝብ ከሕዝብ ጋር፥ መንግሥታት ከመንግሥታት ጋር ይዋጋሉ።'),
  ('ca081928-f901-5008-a930-37aac0b82e3f', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 12, 32, 'ይህም በተደረገ ጊዜ፥ ቀድሞ ያሳየሁህ ምልክቱም በደረሰ ጊዜ ያንጊዜ ከባሕር ሲወጣ ያየኸው ያ ሰው ይገለጣል።'),
  ('170e0d8a-88f1-556e-ab7e-33e2dd3acab6', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 13, 33, '“አሕዛብም ሁሉ ቃሉን በሰሙ ጊዜ ሀገሮቻቸውና እርስ በርሳቸው የሚጣሉበትን ጠባቸውን ይተዋሉ።'),
  ('4fa6aebc-9167-5606-ad1e-aec6c87b87d5', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 14, 34, 'ቍጥር የሌላቸው ሰዎች እንዳየሃቸው መጥተው ሊገድሉት ወድደው በአንድነት በዝተው ይሰበሰባሉ።'),
  ('602bc30c-4ab0-5f02-a766-36b7a8280f0b', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 15, 35, 'እርሱ ግን በጽዮን ተራራ ራስ ይቆማል።'),
  ('8b7fc821-8f88-510d-afd6-4fdeaf4002dd', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 16, 36, 'ያለ ሰው እጅ የተፈጠረው ተራራ ሲወጣ እንዳየኸው፥ ጽዮን ትመጣለች፤ ተዘጋጅታና ተሠርታም ለሁሉ ትታያለች፤'),
  ('0b67dba4-eabd-5010-a12c-8c1f80eec352', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 17, 37, 'እንደ ዓውሎ ነፋስ የሆኑ አሕዛብን በኀጢአታቸው የሚዘልፋቸው እርሱ ወልድ ነው። የሥራቸውንም ክፋት በፊታቸው ይገልጥባቸዋል። እንደ እሳት ነበልባል የሆኑትም በጽኑዕ የሚሠቃዩበትን ይገልጣል።'),
  ('736f0092-15f6-5edf-a575-9a11509ceeb7', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 18, 38, 'እንደ እሳት ፍም የሆኑትንም ያለ ድካም ከኀጢአታቸው ጋር ያጠፋቸዋል።'),
  ('9aff490a-ebc1-5520-ae23-1ad0a1705e58', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 19, 39, '“ለእርሱ የሚስማሙ ብዙዎች ወደ እርሱ ሲሰበሰቡ ያየኸውም፥'),
  ('9ef722e4-1629-5cad-a0a8-380bfe706895', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 20, 40, 'እኒህ በአሦር ንጉሥ በስልምናሶር ዘመን ካገራቸው የተማረኩ፥ እርሱም በመንግሥቱ የማረካቸው፥ በወንዙ ማዶም ያኖራቸው ዘጠኙ ነገድና የነገድ እኩሌታ ናቸው፤ ተመልሰውም ሌላ ሆኑ።'),
  ('343bfd41-9545-52dc-a854-a870d4dee41d', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 21, 41, 'የወገናቸውን ነገድ ይተዉ ዘንድ፥ የሰው ወገን ወደማይኖርበት ሀገርም ይሄዱ ዘንድ እነርሱ ራሳቸው ይህችን ምክር አወጧት።'),
  ('86437881-81d4-5c30-a8bd-bca0e32cc2aa', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 22, 42, 'በሀገራቸው ያልጠበቁትን ሕግ ይጠብቁ ዘንድ፥'),
  ('0da15408-1207-5ff7-a8d3-245d519a04ca', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 23, 43, 'መግቢያው ጠባብ ወደ ሆነ ወደ ኤፍራጥስም ገቡ።'),
  ('7033fd36-b48d-5e86-a306-05d2fd40392f', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 24, 44, 'ያንጊዜም ልዑል ተአምር አደረገላቸው፤ የወንዙንም ምንጭ እስኪያልፉ ድረስ አቆመላቸው።'),
  ('1bc98486-1942-589b-a018-293ceaab3f76', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 25, 45, 'ሀገሩ ግን ዓመት ከመንፈቅ ያስሄዳል፤ የሀገሩም ስም አዛፍ ይባላል።'),
  ('91f9b2e4-16b8-5071-a6f8-e7a6c05ce2c0', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 26, 46, '“እስከ ኋለኛውም ዘመን ድረስ በዚህ ኖሩ፤ ከዚህም በኋላ ዳግመኛ ይመለሱ ዘንድ ባላቸው ጊዜ፦'),
  ('ce717f23-075a-5259-aaf4-c71c1e64c889', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 27, 47, 'መሻገር ይችሉ ዘንድ የወንዙን ምንጭ ልዑል ዳግመኛ ያቆምላቸዋል።'),
  ('0084a8cd-65fa-5829-af08-883628812ccb', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 28, 48, 'ስለዚህም ስለ አየኸው ነገር ከሕዝቡ አብዛኛዎቹን ይወስዷቸዋል። እነርሱም በከበረው ቦታዬ ይገኛሉ።'),
  ('dc94e1b7-69ca-5bb7-a2bc-7d924798a319', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 29, 49, 'በእርሱ ላይ የተሰበሰቡ እነዚያን ብዙዎችንም ባጠፋቸው ጊዜ ያንጊዜ የቀሩትን ሕዝብ ያጸናቸዋል።'),
  ('973b7be3-4894-5135-ad30-c48da299630e', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 30, 50, 'ያንጊዜም ብዙ ምልክቱን ያሳያቸዋል።”'),
  ('a1fdeadc-cc5c-5c92-a360-e27db341d35b', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 31, 51, 'እኔም እንዲህ አልሁት፥ “አቤቱ ጌታዬ፥ ይህንም ንገረኝ፤ ከባሕር መካከል ሰው ሲወጣ እኔ ያየሁት ስለ ምንድን ነው?”'),
  ('7a131022-6a74-52a8-ac62-f8ca70caead6', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 32, 52, 'እንዲህም አለኝ፦ በባሕሩ ጥልቀት ውስጥ ያለውን ማንም ማወቅ እንደማይችል እንደዚሁም በምድር ካሉት ወልድን ማወቅ የሚችል ማንም የለም፤ ሰዓቱና ቀኑ በደረሰ ጊዜ ነው እንጂ፤ ከእርሱም ጋር ያሉት አያውቁትም።'),
  ('6b5851df-8186-5069-aba4-e420dec98815', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 33, 53, 'ያየኸው የሕልምህ ትርጓሜው ይህ ነው፤ ስለዚህም ለአንተ ብቻ አሳየሁህ።'),
  ('ff5090dd-aaba-58dc-ab25-e131f67fd1b2', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 34, 54, 'ግዳጅህን ትተህ የእኔን ግዳጅ ተከትለሃልና ሕጌንም ፈልገሃልና።'),
  ('2eb489f0-0fc7-5abc-aa2e-1d3ddd4789f4', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 35, 55, 'ሕይወትህንም ለዕውቀት አዘጋጅተሃልና፤ ጥበብንም እናት አድርገሃታልና።'),
  ('cc92fbad-714f-5d88-a104-20e98cc3a575', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 36, 56, 'ስለዚህም ይህን ገለጥሁልህ፤ ዋጋህ በልዑል ዘንድ አለና፥ እንግዲህስ ወዲህ ከጥቂት ቀን በኋላ ና፤ የምነግርህ ሌላ ነገር አለና፥ ድንቅንም እተረጕምልሃለሁና።”'),
  ('74d2ea67-5ecf-5f9a-a867-788373f659e5', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 37, 57, 'በየጊዜው ስለሚያደርገው ስለ ድንቅ ሥራውም እግዚአብሔርን አመሰግነውና አከብረው ዘንድ ወደ ምድረ በዳ አልፌ ሄድሁ።'),
  ('7b30664a-8756-55d6-a832-aeb5513fb3c7', '3dc51a09-4162-5889-a72d-a85d935daeac', 'af4b7d74-7d4c-5621-a09c-d30d8d668726', 38, 58, 'ዘመኖቹን ያዘጋጃቸዋልና፥ ይህንም በየዓመቱ ያደርጋልና። በዚያም ሦስት ቀን ተቀመጥሁ።'),
  ('ed982b68-0c7d-5103-a577-9cfdf0e2af33', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 1, 1, 'በሦስተኛውም ቀን በዛፍ ሥር ተቀምጬ ሳለሁ፦'),
  ('6bef661e-28e6-5b36-af26-3bd2c98433d6', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 2, 2, 'ከዚያች ዛፍ ፊት ለፊት ቃል መጣ፤ “ዕዝራ! ዕዝራ!” ብሎ ጠራኝ፤ እኔም፥ “እነሆኝ ጌታ ሆይ፥” አልሁ፤ ተነሥቼም ቆምሁ፤'),
  ('4678373e-bc25-502e-a3b0-a4479e1d6d9d', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 3, 3, 'እርሱም እንዲህ አለኝ፥ “ለሙሴ ፈጽሜ ታየሁት፤ ወገኖችም ለግብፅ በተገዙ ጊዜ ጳጦስ በሚባል እንጨት ሥር ተናገርሁት።'),
  ('0eac4761-5227-5ee1-aaca-c85a9c12e835', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 4, 4, 'ላክሁትም፤ ወገኖችንም ከግብፅ አወጣኋቸው፤ ሙሴንም ወደ ደብረ ሲና ወሰድሁት፤ ብዙ ቀንም በእኔ ዘንድ አኖርሁት።'),
  ('bc5369d8-822b-5e9e-a7fe-4ff12119e261', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 5, 5, 'ብዙ ድንቅን ነገርሁት፤ የዘመናትንም ምሥጢር አሳየሁት፤ ኋለኛውንም ዘመን ነገርሁት።'),
  ('336b1c7f-463e-5c61-a4be-c1fc5fa6d9f3', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 6, 6, 'ይህን ነገር ተናገር፤ ይህንም ነገር ሰውር ብዬ አዘዝሁት።'),
  ('84c3b058-2324-570a-a672-24f1465a5b15', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 7, 7, 'አሁንም ለአንተ እልሃለሁ፦'),
  ('281820fe-b553-5ac1-a6b4-250d55e0bf93', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 8, 8, 'የነገርሁህን ያን ነገር ታውቅ ዘንድ፥ ያየኸው ሕልምህንም፥ የሰማኸውን ትርጓሜውንም በልቡናህ ጠብቀው።'),
  ('15212989-13aa-5f41-aea4-46c9996eb87e', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 9, 9, 'ከሰው ለይተው ይወስዱሃልና፥ ከዚህም በኋላ ዓለም እስኪያልፍ ድረስ እንዳንተ ያሉት ባሉበት ቦታ ከልጆች ጋር ትኖራለህ።'),
  ('c07ddb5d-cf81-599d-ad7f-577f808f0656', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 10, 10, 'የዓለም የጐልማሳነቱ ወራት አልፏልና፥ ዘመኑም አርጅትዋልና።'),
  ('e462b3e2-7640-5491-aea2-bc1f5240eb2c', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 11, 11, 'ዓለም ለዐሥር ክፍል ተከፍሏልና እስከ ዐሥርም ድረስ ደርሷልና።'),
  ('629544be-5151-52cc-ae2d-6c203d856585', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 12, 12, 'የዐሥረኛው እኩሌታ ቀርትዋልና።'),
  ('ad5168bb-3836-599c-aa1b-4f12148153b2', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 13, 13, 'አሁን ግን ቤትህን አዘጋጅ፤ አዘንተኞቻቸውንም ደስ አሰኛቸው፤ ዐዋቆቻቸውንም ልብ አስደርጋቸው፤ እንግዲህ የምታልፍ ሕይወትንም ተዋት።'),
  ('8b84fa2a-8207-5aa4-afeb-aa46c3ab45e5', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 14, 14, 'መዋቲ አሳብን እንግዲህ ተወው፤ የሰው ሸክምንም ከላይህ ጣል፤ የሚሞት አሳብንም ተው፤ የማይሞተውንም ልበስ፤ እንግዲህም ወዲህ ከዚህ ዓለም ትሸጋገር ዘንድ አፍጥን።'),
  ('03e6e8ba-b463-543b-a451-90f6c8f3683f', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 15, 15, 'ይች ያየሃት ክፋት ዛሬ ደርሳለችና፤ እንግዲህ ወዲህ ከእርሷ የምትከፋ ዳግመኛ ትደረጋለችና።'),
  ('bc4bb7ed-1ed6-58bd-a358-d85a7bf013a8', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 16, 16, 'ዓለም እያረጀና እየደከመ በሚሄድ መጠን እንዲሁ በውስጡ የሚኖሩ ክፋታቸው ትበዛለችና።'),
  ('15ced22e-b760-517e-aa44-15b4d6f2c051', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 17, 17, 'እውነት ትጠፋለችና፥ አሰትም ትጸናለችና። ይህ ያየኸውም ንስር ይደርስ ዘንድ ይቸኵላልና።”'),
  ('5bd53388-bbf0-565e-a07d-f74acff4bf78', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 18, 18, 'እኔም መለስሁለት፤ እንዲህም አልሁት፥ “እንግዲህስ ወዲህ በፊትህ እናገራለሁ።'),
  ('61b886ff-0b7d-5246-a24f-9e62737aed1b', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 19, 19, 'አቤቱ፥ እኔ እሄዳለሁና፥ እንደ አዘዝኸኝም ዛሬ ያሉትን ሕዝብ አስተምራቸዋለሁና። እንግዲህ ወዲህ ዳግመኛ የሚወለዱትን ማን ያስተምራቸዋል?'),
  ('05fb0e43-ef99-5586-ad62-0ddf8e8079df', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 20, 20, 'ዓለም በጨለማ ውስጥ አለና፤ በውስጡ ለሚኖሩትም ብርሃን የላቸውም።'),
  ('25f8fc8a-a54f-5e91-abe2-83fe818e0716', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 21, 21, 'ኦሪትህ ተቃጥላለችና፥ የሠራኸውን፥ ትሠራውም ዘንድ ያለህን የሚያውቀው የለምና።'),
  ('7145573d-17ad-598f-a32c-b1d6facbe3ab', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 22, 22, 'በፊትህስ ባለሟልነትን ካገኘሁ፥ ቅዱስ መንፈስህን ላክልኝ፤ እኔም ሰው የሕይወት መንገድን ማግኘት ይችል ዘንድ፥ ሊኖሩ የሚወድዱ ሰዎችም ይድኑ ዘንድ ከጥንት ጀምሮ በዓለም የሆነውን ሁሉና በኦሪትህ ውስጥ ተጽፎ ያለውን እጽፋለሁ።”'),
  ('154f9a16-48fc-5ccd-a376-1472f91db30a', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 23, 23, 'እርሱም መለሰልኝ፤ እንዲህም አለኝ፥ “ሄደህ ወገኖችህን ሰብስባቸው፤ እስከ አርባ ቀንም ድረስ እንዳይፈልጉህ ንገራቸው።'),
  ('711451fe-09c4-5ccc-a29e-86ed0157c278', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 24, 24, 'አንተ ግን ብዙ ብራና አዘጋጅ፥ ከአንተም ጋራ ሶርያን፥ ደርብያን፥ ሰላምያን፥ ኢቀናንንና አሳሄልን እኒህን አምስቱን ሰዎች ውሰዳቸው። እነርሱ በመጻፍ ጠቢባን ናቸውና።'),
  ('831e437e-65f8-54a9-a8e2-764494948576', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 25, 25, 'ወደዚህ ና፤ በልቡናህም የጥበብ መብራትን አበራለሁ፤ ትጽፍም ዘንድ ያለህን ሁሉ እስክትጨርስ ድረስ እንግዲህ አትጠፋም።'),
  ('10f0f0ad-6de2-5d12-a7f6-1c7c074878cc', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 26, 26, 'በጨረስህ ጊዜ ግልጥ የምታደርገው አለ፤ የምትሠውረውም አለ፤ ለዐዋቂዎችም፥ ለጠቢባንም ትሰጣቸዋለህ፤ ነገ በዚህ ሰዓት ትጽፍ ዘንድ ትጀምራለህ።”'),
  ('7e70a43a-1dc1-58c1-a06c-73783671814f', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 27, 27, 'እንደ አዘዘኝም ሄጄ ሕዝቡን ሁሉ ሰበሰብሁ።'),
  ('0fe720a9-1418-50ab-a51a-07c2d6b0edcc', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 28, 28, 'እንዲህም አልኋቸው፥ “እስራኤል፥ ይህን ነገር ስሙ።'),
  ('533908ec-7e71-594c-a070-fd94a19daed2', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 29, 29, 'አባቶቻችሁ ቀድሞ በግብጽ ምድር ኖሩ፤ ከዚያም ተቤዣቸው።'),
  ('27f55657-af31-590c-a001-1daa6ae26aef', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 30, 30, 'የሕይወት ሕግንም ተቀበሉ፤ ግን አልጠበቁም፤ ከእነርሱም በኋላ ያላችሁት እናንተ ካዳችሁት።'),
  ('d91cd5e0-5aeb-5d30-a662-1c108f63cf05', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 31, 31, 'ምድረ ርስትን ሰጠን፤ የጽዮንንም ምድር አወረሰን፤ እናንተም፥ አባቶቻችሁም ካዳችሁት፤ እርሱንም መበደል አልተዋችሁም፤ የአዘዛችሁ የልዑል መንገድን አልጠበቃችሁም።'),
  ('91a9ae90-d7d9-5b2c-a74e-947b0383a056', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 32, 32, 'እርሱ እውነት ፈራጅ ነውና በጊዜው የሰጣችሁን ቀማችሁ።'),
  ('51a5e0b7-a31f-5d20-add3-01c5edab46c5', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 33, 33, 'አሁንም እናንተ በዚህ አላችሁ፤ ወንድሞቻችሁ ግን ከእናንተ ተለይተው በውስጥ ናቸው።'),
  ('b9a7ae86-8758-535a-a56a-79ed0182be64', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 34, 34, 'ልቡናችሁን ያስገዛችሁት፥ ሕሊናችሁንም የገሠጻችሁት እንደ ሆነ፥ ሕይወታችሁንም የጠበቃችሁት እንደ ሆነ አትሞቱም።'),
  ('6bc9798a-9fce-5c98-a28d-1497f3c2b2fd', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 35, 35, 'ከሞት በኋላ ፍርድ ይመጣልና፥ እኛንም በሕይወት አያኖረንምና፥ ያንጊዜም የጻድቃን ስማቸው ይገለጣል፤ የኃጥኣንም ሥራቸው ይገለጣል።'),
  ('1ca62838-20ec-5930-a0ac-de359ce86e65', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 36, 36, 'ከእናንተ ወደ እኔ የሚመጣ አይኑር፤ እስከ አርባ ቀንም ድረስ አትፈልጉኝ።”'),
  ('b713b392-26e7-5088-abf1-6cb25a1c5785', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 37, 37, 'እንዳዘዘኝም እነዚያን አምስቱን ሰዎች ይዤ ወደ ምድረ በዳው ሄድን፤ በዚያም ተቀመጥን።'),
  ('235525ee-5d5e-5c01-a0b8-be432e3b968f', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 38, 38, 'በማግሥቱም ቃል መጣ፥ “ዕዝራ! ዕዝራ!” ብሎ ጠርቶ እንዲህ አለኝ፥ “አፍህን ክፈት እኔም የማጠጣህን ጠጣ።”'),
  ('12bb4539-8d89-5ba8-aa4d-abf970823d5c', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 39, 39, 'አፌንም በከፈትሁ ጊዜ ውኃ የተመላ፥ መልኩ እሳት የሚመስል መጠጥን አጠጣኝ።'),
  ('1ab85ce3-7451-54bc-aa40-43c09c707d43', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 40, 40, 'ተቀብዬም ጠጣሁት፤ ልቡናዬም ፈጽሞ ዕውቀትን ተናገረ፤ ዕውቀትም በልቡናዬ በዛ፤ ነፍሴም ትጠብቀዋለች፤ ታስበዋለችም።'),
  ('a96f3d5c-ee1a-590e-a68f-3454bae7a25a', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 41, 41, 'አፌም ተከፈተ፤ ከዚያም ወዲያ ዝም አላለም።'),
  ('5da7f122-a81d-5aec-ae0d-ed4f63aabfe3', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 42, 42, 'ልዑልም ለእነዚያ ለአምስቱ ሰዎች ጥበብን ሰጣቸው፤ የማያውቁትንም ምልክት የሆነውን ይህን ሁሉ በማከታተል ጻፉ፤ በዚያም አርባ ቀን ተቀመጡ፤ እነርሱም ቀን ቀን ይጽፉ ነበር፤ ማታ ማታም እህል ይመገቡ ነበር፤'),
  ('658f4b7f-5c6d-5387-a725-cdb8b79a1ff1', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 43, 43, 'እኔ ግን ቀን እናገራለሁ፤ ሌሊትም ዝም አልልም።'),
  ('a6991cc0-281f-5661-ac02-931c377191ef', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 44, 44, 'በእነዚያ በአርባ ቀኖችም ሃያ አራት መጻሕፍት ተጻፉ።'),
  ('b9c0d554-63e7-5966-a5af-ea3d804bf30b', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 45, 45, 'ከዚህም በኋላ እነዚያ አርባ ቀኖች በተፈጸሙ ጊዜ ልዑል ተናገረኝ፤ እንዲህም አለኝ፥ “አስቀድሞ የጻፋችሁትን ያን ግልጥ አድርገው፤ የሚገባውም የማይገባውም ሁሉ ያንብበው።'),
  ('db3e6870-dadb-5da4-a955-d77cac856abc', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 46, 46, 'ይህን ግን ለጠቢባን ሕዝብ ትሰጣቸው ዘንድ ጠብቅ።'),
  ('1e81b252-2d13-51e1-afa7-f11ed626cfc2', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 47, 47, 'በእነዚህ ውስጥ የማስተዋል መብራት፥ የጥበብ ምንጭ፥ የዕውቀትም ፈሳሽ አለና።”'),
  ('818e8104-d93c-52ef-a58e-a3afb2f50952', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 48, 48, 'እንዲሁም አደረግሁ፤ በአራተኛው ዓመት፥ ከዓመታቱ ሱባዔያት በአምስተኛው ሱባዔ፥ ከፍጥረተ ዓለም በኋላ በአምስት ሺህ ዓመታት፥ ጨረቃ ሠርቅ ባደረገች በዐሥረኛው ቀን በሦስተኛው ወር፥ በዘጠና አንድ ቀናት።'),
  ('4828bedc-b0b1-501d-a42a-4fbc381276c9', 'e7c145f6-a52c-5343-a1c1-a5556ae38d66', '0648f795-d5fd-5b40-a103-4a5d78e394c0', 49, 49, 'ያንጊዜ ይህን ሁሉ ከጻፈ በኋላ ዕዝራን ይዘው እንደ እርሱ ያሉ ሰዎች ወዳሉበት ሀገር ወሰዱት፤ እርሱም እስከ ዘለዓለም ድረስ የልዑል የጥበቡ ጸሓፊ ተባለ።'),
  ('2f93bccb-8f0c-549d-a105-f2a08c07ae10', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 1, 1, 'ኢዮስያስ ለፈጣሪው የፋሲካውን በግ ወደ ኢየሩሳሌም አመጣ፤ በመጀመሪያው ወርም በዐሥራ አራተኛው ቀን የፋሲካውን በግ ሠዋ።'),
  ('3b71f6ad-4a8e-57ce-a0b8-499a85e9fa18', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 2, 2, 'ካህናቱንም የአገልግሎት ልብሳቸውን አልብሶ አቆማቸው፤ በእግዚአብሔርም ቤተ መቅደስ በየሰሞናቸው ሠራቸው።'),
  ('21297446-dd1e-5db6-a091-ab45be593f49', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 3, 3, 'ሌዋውያንንም አላቸው፥ “ለእስራኤል ካህናት ተገዙ፤ የንጉሡ የዳዊት ልጅ ሰሎሞን በሠራው ቤተ መቅደስም በእግዚአብሔር ታቦት ቅድስና ሥርዐት አክብሯቸው።'),
  ('ca385016-3f7f-5c7f-a241-599281d51aa5', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 4, 4, 'ታቦቱንም በጫንቃችሁ መሸከም አይገባችሁም። አሁንም ፈጣሪያችን እግዚአብሔርን አምልኩት፤ የእስራኤልንም ሕዝብ አገልግሉ።'),
  ('e005d3ef-47ec-5656-a3ae-49af034e4f44', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 5, 5, 'እንደ እስራኤል ንጉሥ እንደ ዳዊት መጽሐፍና እንደ ልጁ ሰሎሞንም ገናናነት በየሀገራችሁና በየነገዳችሁ ተዘጋጁ፤ ሌዋውያንም በወንድሞቻችሁ በእስራኤል ልጆች ፊት በቤተ መቅደስ በየቦታችሁና በየሀገራችሁ ግዛት በየሹመታችሁ ቁሙ።'),
  ('8fab541d-53f0-5c2f-ab61-acf6084fc451', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 6, 6, 'የፋሲካውንም በግ ሠዉ፤ ለወንድሞቻችሁም መሥዋዕቱን አዘጋጁ፤ ለሙሴ በተሰጠው በእግዚአብሔርም ሕግ ፋሲካን አድርጉ።”'),
  ('dcb25ac5-292e-5df1-a2eb-57a9c5abb045', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 7, 7, 'ኢዮስያስም በዚያ ለነበሩ ሰዎች ሠላሳ ሺህ ፍየሎችንና በጎችን፥ ሦስት ሺህ በሬዎችንም ሰጣቸው፤ እንደዚሁም ለሕዝቡ፥ ለካህናቱና ለሌዋውያኑም ከንጉሥ ቤት አዝዞ ሰጠ።'),
  ('38c851ae-2308-524c-a7ea-87c647a3c647', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 8, 8, 'የቤተ መቅደሱም ሹሞች ኬልቅያስ፥ ዘካርያስና ሲሉያስ ለካህናቱ ለፋሲካ በዓል ሁለት ሺህ ስድስት መቶ በጎችንና ሦስት መቶ በሬዎችን ሰጧቸው።'),
  ('eb82bf4b-971d-5d14-a1f7-6a5b6d093d78', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 9, 9, 'መሳፍንቱም ኢኮንያስና ሳሚያስ፥ ወንድሙ ናትናኤልና ሲብያስ፥ ኪያሎስና ኢዮራም ለሌዋውያን ለፋሲካቸው ሺህ በጎችንና ሰባት መቶ በሬዎችን ሰጧቸው።'),
  ('ee02c5c0-9ef5-5573-acf0-8c3c2c08db09', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 10, 10, 'ካህናቱና ሌዋውያኑም እንደ ሕጉ እንዲሁ መልካም አደረጉ፤ ቂጣውንም በየነገዳቸው ተመገቡ።'),
  ('55975038-8f60-59c1-a92f-b23366584b08', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 11, 11, 'በሙሴ መጽሐፍም እንደ ተጻፈ በሕዝቡ ፊት በየአባቶቻቸው ሹመት መሥዋዕቱን ለእግዚአብሔር አቀረቡ።'),
  ('1fbb2939-ffdd-56d2-a2cf-19f73b1b064b', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 12, 12, 'በነጋውም እንደዚሁ እንደ ሥርዐታቸው የፋሲካውን በግ በእሳት ሠዉ፤ መሥዋዕቶችንም በጋንና በብረት ምጣድ አበሰሉ።'),
  ('00379252-0567-52c0-a8c9-b954ef577ff7', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 13, 13, 'ለሕዝቡም ሁሉ በጎ መዓዛ ያለውን መሥዋዕት ሠሩላቸው፤ ከዚህም በኋላ ለራሳቸውና ለወንድሞቻቸው ለአሮን ልጆች ካህናት አዘጋጁላቸው።'),
  ('49238c71-c9a9-5fed-aa30-bc9a6b858ad6', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 14, 14, 'ካህናቱ ግን ቀኑ እስኪመሽ ድረስ የሰባውን መሥዕዋት ሠዉ፤ ሌዋውያኑም ለራሳቸውና ለወንድሞቻቸው ለአሮን ልጆች ሠዉ።'),
  ('4c26c515-b276-56d8-a9d9-fa4dc0c534fe', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 15, 15, 'መዘምራኑ የአሳፍ ልጆችም ዳዊት በሠራው ሥርዐት በሹመታቸው ነበሩ፤ ከንጉሡ የተሾሙ አሳፍና ዘካርያስ፥ ዐዲኑስም ነበሩ።'),
  ('78a9460c-8899-5d37-aad6-a1b5c27f7317', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 16, 16, 'የበሩ ሁሉ ጠባቂዎችም ነበሩ፤ ከሰሞኑም የሚያጓድል አልነበረም፤ ወንድሞቻቸው ሌዋውያን ያዘጋጁላቸው ነበርና።'),
  ('2f75e905-f2fa-58b9-a214-8fa17545a082', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 17, 17, 'ያንጊዜም የእግዚአብሔርን መሥዋዕት አቅርበው ጨረሱ።'),
  ('de0245fe-e177-591e-a38e-76ba76e7e466', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 18, 18, 'ንጉሡ ኢዮስያስ እንዳዘዘም ፋሲካቸውን አደረጉ፤ ወደ እግዚአብሔርም መሠዊያ መሥዋዕታቸውን አቀረቡ።'),
  ('c2217fce-dd56-5196-a7c6-6f4de5a786b9', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 19, 19, 'በእነዚያም ወራቶች የነበሩ የእስራኤል ልጆች ፋሲካንና የቂጣውን በዓል ለሰባት ቀን አደረጉ።'),
  ('d99a7d6a-0f88-5b3c-abce-55f20cb06f76', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 20, 20, 'ከነቢዩ ከሳሙኤልም ዘመን ወዲህ በእስራኤል ዘንድ እንደ እርሱ ያለ በዓል አልተደረገም።'),
  ('cc138f21-77ca-5703-a2c4-590f3e2a83fb', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 21, 21, 'የእስራኤልም ነገሥታት ሁሉ ኢዮስያስ እንዳደረገው ፋሲካን አላደረጉም፤ ሌዋውያንና ካህናት፥ አይሁድና ወደ ኢየሩሳሌም መጥተው በዚያ የነበሩ እስራኤልም ሁሉ አላደረጉም።'),
  ('253fa7f3-3f88-50b6-a9b9-ef73a3d4f88b', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '348cdf78-0ca9-5d16-a49a-a096395c003a', 22, 22, 'ኢዮስያስ በነገሠ በዐሥራ ስምንተኛው ዓመት ይህን ፋሲካ አደረገ።'),
  ('317d561e-be02-5bd1-a381-087c153dc0bd', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 1, 23, 'የኢዮስያስም ሥራው እግዚአብሔርን መፍራት በተመላበት ልቡና በፈጣሪው ፊት የቀና ነበር።'),
  ('6b88871f-b68e-5117-adc4-3203ea4b2f99', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 2, 24, 'በቀድሞው ዘመን ከአሕዛብና ከመንግሥታት ሁሉ እግዚአብሔርን ፈጽመው ስለ በደሉትና ስለ አሳዘኑት ሰዎች እንደ ተጻፈ እግዚአብሔር በእስራኤል ላይ ቃሉን አጸና።'),
  ('b405a2a6-341d-52a4-a870-ff037211389c', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 3, 25, 'ከዚህም ከኢዮስያስ ሥራ ሁሉ በኋላ፦ የግብፅ ንጉሥ ፈርዖን በኤፍራጥስ ወንዝ በከርከሚስ ሠራዊቱን ይዞ ዘመተ፤ ኢዮስያስም ወጥቶ ተቀበለው።'),
  ('7b3eef9a-077f-5baf-ad28-c127cfd9878f', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 4, 26, 'የግብፅ ንጉሥም፥ “የይሁዳ ንጉሥ ሆይ፥ እኔ ካንተ ጋራ ምን አለኝ?” ብሎ ላከበት።'),
  ('9750b6b3-1db1-564a-abe4-0b7e249549b8', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 5, 27, '“ከጌታ ከእግዚአብሔር ዘንድ በአንተ ላይ የተላክሁ አይደለም፥ እኔ የምወጋ ኤፍራጥስን ነውና፥ አሁንም እግዚአብሔር ከእኔ ጋር ነው፤ እግዚአብሔር በእኔ ዘንድ አለ፤ እርሱም ይረዳኛል፤ ገለል በል፤ ከእግዚአብሔርም ጋር አትከራከር” አለው።'),
  ('ebe1133a-e906-54df-ad38-e6c747a69964', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 6, 28, 'ኢዮስያስም በሠረገላዎቹ ሆኖ ገለል አልልም አለ፤ ይዋጋም ዘንድ ጀመረ፤ ከእግዚአብሔርም አፍ በነቢዩ በኤርምያስ የተነገረውን ቃል መስማት እንቢ አለ።'),
  ('b9c2834d-d4fd-56ae-a5f7-74d91fc77b58', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 7, 29, 'ነገር ግን መጊዶስ በሚባል ምድረ በዳ ይዋጋቸው ዘንድ ጸና፤ አለቆችም ወደ ንጉሡ ወደ ኢዮስያስ ወረዱ።'),
  ('9a53f2cb-f353-523b-ae73-1dc53b903e6a', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 8, 30, 'ንጉሡም ብላቴኖቹን አላቸው፥ “እጅግ ደክሜአለሁና ከሰልፉ ውስጥ አውጡኝ፥” ብላቴኖቹም ወዲያውኑ ከሰልፉ ውስጥ አወጡት።'),
  ('de2e73f7-e203-5049-a2ba-17c4138f4840', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 9, 31, 'በሌላ ሰረገላውም ተቀምጦ ወደ ኢየሩሳሌም ገባ፤ በዚያም ሞተ፤ በአባቱ መቃብርም ተቀበረ።'),
  ('4f194739-ef7a-538b-a9f2-88160419ec97', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 10, 32, 'በይሁዳም ሁሉ ለኢዮስያስ አለቀሱለት፤ ኤርምያስም ለኢዮስያስ አለቀሰለት፤ እስከዚች ቀን ድረስም ወንዶች ሁሉ ከሴቶች ጋር አለቀሱለት፤ ለዘለዓለምም እንዲሁ ያደርጉ ዘንድ ለእስራኤል ወገኖች ሥርዐት ሆኖ ተሰጠ።'),
  ('b89a0d2a-ddb3-5a83-a9fc-5109effb298b', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '911f4a0b-a116-586d-a6c1-4397ea210c8c', 11, 33, 'ይህም በይሁዳ ነገሥታት ታሪክ መጽሐፍ ተጻፈ፤ ኢዮስያስም የሠራው ሥራ ሁሉ፥ ክብሩም፥ የእግዚአብሔርንም ሕግ ማወቁ፥ በፊትም፥ በኋላም የሠራው ሥራ ሁሉ በእስራኤልና በይሁዳ ነገሥታት ታሪክ መጽሐፍ ተጽፏል።'),
  ('e56092a4-87a8-5d39-ad81-9feedac44780', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 1, 34, 'ሕዝቡም የኢዮስያስን ልጅ ኢዮአክስን ወስደው በተወለደ በሃያ ሦስት ዓመት ዕድሜው በአባቱ በኢዮስያስ ፋንታ አነገሡት።'),
  ('5fc6f376-ca89-5dec-a728-c342d0e929ba', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 2, 35, 'ለእስራኤልም በኢየሩሳሌም ሦስት ወር ነገሠ፤ የግብፅ ንጉሥም በኢየሩሳሌም ከመንግሥት አወረደው።'),
  ('06860563-a2be-5ae5-a381-1fb2460bc2c4', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 3, 36, 'ሕዝቡንም ሁለት መቶ መክሊት ብርና አንድ መክሊት ወርቅ አስገበራቸው።'),
  ('b54e8e75-b176-52cb-a6b0-c4c95284b2fd', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 4, 37, 'የግብፅ ንጉሥም ወንድሙን ኢዮአቄምን የይሁዳ ንጉሥ አድርጎ በኢየሩሳሌም አነገሠው።'),
  ('e5070dbe-bf1b-586c-a119-cf88897130fd', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 5, 38, 'ኢዮአቄምም መሳፍንቱን አሰራቸው፤ ወንድሙ ዛርዮንንም ይዞ ወደ ግብፅ አገባው።'),
  ('60a48919-1185-5c76-af97-bbc5fa1cca71', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 6, 39, 'ኢዮአቄምም በይሁዳ በኢየሩሳሌም በነገሠ ጊዜ ዕድሜው ሃያ አምስት ዓመት ሆኖት ነበር፤ በእግዚአብሔርም ፊት ክፉ አደረገ።'),
  ('fd8ca3d3-fea3-5ab8-a451-e8f7f697c7ec', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 7, 40, 'ከዚህም በኋላ የባቢሎን ንጉሥ ናቡከደነፆር ወደ እርሱ ዘመተ፤ በብረት ሰንሰለትም አስሮ ወደ ባቢሎን ሰደደው።'),
  ('5cdd943b-f678-5f19-a35f-5d3cad72e824', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 8, 41, 'ናቡከደነፆርም የእግዚአብሔርን ንዋየ ቅድሳት ወስዶ ወደ ባቢሎን አገባው፤ በጣዖቱም ቤት አኖረው።'),
  ('c98b9449-c748-50ee-a132-46005c8047cf', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 9, 42, 'ይህም በይሁዳ ነገሥታት ታሪክ መጽሐፍ ተጽፎአል።'),
  ('12355476-1150-5ef8-a4f3-5f03d2863273', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 10, 43, 'ከዚህም በኋላ ልጁ ኢኮንያስ ነገሠ፤ ዕድሜውም ዐሥራ ስምንት ዓመት ነበረ።'),
  ('fd0b0959-353e-51bc-a0fa-1b1d9025a781', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 11, 44, 'ሦስት ወር ከዐሥር ቀን በኢየሩሳሌም ነገሠ፤ እርሱም በእግዚአብሔር ፊት ክፉ አደረገ።'),
  ('a1fe3578-a0ee-5722-aaf0-79c21c2f1781', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 12, 45, 'ከዓመትም በኋላ ናቡከደነፆር ከእግዚአብሔር ንዋየ ቅድሳት ጋር ልኮ ወደ ባቢሎን አገባው።'),
  ('20992d13-77b9-55ec-a3d6-7f33e035583b', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 13, 46, 'ሴዴቅያስንም በተወለደ በሃያ አንድ ዓመቱ በኢየሩሳሌምና በይሁዳ አነገሠው፤ ዐሥራ አንድ ዓመትም ነገሠ።'),
  ('b9528a1c-b265-5d95-a952-a88b2657f0e1', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 14, 47, 'በእግዚአብሔርም ፊት ክፉ አደረገ፤ በነቢዩ በኤርምያስ አፍ ከተነገረው ከእግዚአብሔርም ቃል የተነሣ አልፈራም።'),
  ('acad52f5-554a-5872-a910-41d7d64b117f', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 15, 48, 'ንጉሡ ናቡከደነፆርም በእግዚአብሔር ስም አማለው፤ እርሱ ግን ከዳው፤ አንገቱንም አደነደነ፤ ልቡናውንም አስታበየ፤ የእስራኤል ፈጣሪ የእግዚአብሔርንም ሕግ ተላለፈ።'),
  ('adaf9698-7c68-5455-ad5b-a0aa2620be79', '2f4f757c-5083-55c0-ac61-53718ca54c4d', '1770d133-c579-5b30-a5f1-2ac31de7d2dd', 16, 49, 'የሕዝቡና የካህናቱ መሪዎችም ብዙ ተላለፉ፤ ከአሕዛብም ርኵሰት ይልቅ እጅግ በደሉ፤ በኢየሩሳሌምም የተቀደሰችውን የእግዚአብሔርን መቅደስ አሳደፉ።'),
  ('4427292a-c3b1-5aad-af9c-fb822cdbeb48', '2f4f757c-5083-55c0-ac61-53718ca54c4d', 'fdae62ff-e68d-5810-a0b2-ea21dcb84e44', 1, 50, 'የአባቶቻቸው አምላክ እግዚአብሔርም ይገሥጻቸውና ይመልሳቸው ዘንድ መልእክተኛውን ላከ፤ ለእነርሱና ለመቅደሳቸው ይራራልና።'),
  ('fa27f224-b51e-5806-a604-cdfa4e6a508d', '2f4f757c-5083-55c0-ac61-53718ca54c4d', 'fdae62ff-e68d-5810-a0b2-ea21dcb84e44', 2, 51, 'እነርሱ ግን በመልእክተኞቹ ዘበቱባቸው፤ እግዚአብሔርም በተናገራቸው ጊዜ በሕዝቡ እስኪቈጣ ድረስ በነቢያት ይስቁባቸው ነበር።'),
  ('90faf350-a6f6-5e0b-aca8-7d1b2f4a3f1d', '2f4f757c-5083-55c0-ac61-53718ca54c4d', 'fdae62ff-e68d-5810-a0b2-ea21dcb84e44', 3, 52, 'ጣዖቱን እጥፍ አድርገው ያመልኩ ነበርና የከላውዴዎን ክፍል የአሦር ነገሥታትም ይዘምቱባቸው ዘንድ አዘዘ።'),
  ('2c3cb5b4-a080-5b2a-ad5d-584c11e6f562', '2f4f757c-5083-55c0-ac61-53718ca54c4d', 'fdae62ff-e68d-5810-a0b2-ea21dcb84e44', 4, 53, 'መጥተውም በቤተ መቅደሱ አደባባይ ጐልማሶቻቸውን በሰይፍ ገደሉ፤ ለጐልማሳውም፥ ለቆንጆዋም፥ ለትልቁም፥ ለትንሹም ቢሆን አልራሩም፤ ሁሉንም በእጃቸው አሳልፎ ሰጣቸው።'),
  ('16b8fc76-24d7-5055-ae5b-65e442e04edd', '2f4f757c-5083-55c0-ac61-53718ca54c4d', 'fdae62ff-e68d-5810-a0b2-ea21dcb84e44', 5, 54, 'የእግዚአብሔርንም ንዋየ ቅድሳት ትልቁንም ትንሹንም ሁሉ፥ የእግዚአብሔርንም ታቦት፥ የንጉሡንም ቤት ዕቃ ሁሉ ዘርፈው ወደ ባቢሎን ወሰዱ።'),
  ('dcca6651-84ba-58a3-a242-595771377c6f', '2f4f757c-5083-55c0-ac61-53718ca54c4d', 'fdae62ff-e68d-5810-a0b2-ea21dcb84e44', 6, 55, 'የእግዚአብሔርንም ቤት አቃጠሉ፤ የኢየሩሳሌምንም ቅጽሯን አፈረሱ፤ ግንቧንም በእሳት አቃጠሉ።'),
  ('fd9554d9-c2a4-5c2c-a280-4d419dc2fa1b', '2f4f757c-5083-55c0-ac61-53718ca54c4d', 'fdae62ff-e68d-5810-a0b2-ea21dcb84e44', 7, 56, 'ያማረውንም ዕቃዋን ሁሉ አጠፉ፤ ከጦር የቀሩትንም ማርከው ወደ ባቢሎን ወሰዱአቸው።'),
  ('86403711-9640-52a9-ad0c-eaccbb0fee91', '2f4f757c-5083-55c0-ac61-53718ca54c4d', 'fdae62ff-e68d-5810-a0b2-ea21dcb84e44', 8, 57, 'በነቢዩ በኤርምያስ አፍ የተነገረው የእግዚአብሔር ቃል ይደርስ ዘንድ፥ ፋርሳውያን መግዛት እስከ ጀመሩበት ድረስ ለእርሱና ለልጆቹ አገልጋዮች ሆኑ።'),
  ('8565c6ab-b984-5aeb-a9db-b3a8bc1913f7', '2f4f757c-5083-55c0-ac61-53718ca54c4d', 'fdae62ff-e68d-5810-a0b2-ea21dcb84e44', 9, 58, 'ምድርም በማረፍዋ ደስ ይላታል፤ በተፈታችበትም ዘመን ሁሉ ሰብዓው ዘመን እስኪፈጸም ድረስ ታርፋለች።'),
  ('ddd1a007-2e94-5107-ad77-1824b7944962', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 1, 1, 'በፋርስ ንጉሥ በቂሮስ መንግሥት በመጀመሪያዪቱ ዓመት እግዚአብሔር በነቢዩ በኤርምያስ አፍ የተናገረው ቃል ደረሰ።'),
  ('71256af2-c12d-5158-ab6b-1d4814bc5dd7', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 2, 2, 'እግዚአብሔርም የፋርስን ንጉሥ የቂሮስን መንፈስ አነሣሣ፤ በመንግሥቱም ሁሉ ዐዋጅ ነገረ፤ እንዲህም ብሎ ጻፈ።'),
  ('81c70bc6-9822-5f94-a42c-c89fdfea5e2b', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 3, 3, 'የፋርስ ንጉሥ ቂሮስ እንዲህ ይላል፥ “የእስራኤል አምላክ ልዑል እግዚአብሔር እኔን ለዘለዓለም አነገሠኝ።'),
  ('384749e6-3896-52d1-a0c5-cedc6d53bb23', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 4, 4, 'በይሁዳ ባለችው በኢየሩሳሌም ቤተ መቅደስን እሠራለት ዘንድ አዘዘኝ፤'),
  ('fdcde178-031d-5f09-a2d7-50ef12b30695', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 5, 5, 'ስለዚህ ከእናንተ ውስጥ ከሕዝቡ ወገን የሆነ ቢኖር እግዚአብሔር ከእርሱ ጋር ይሁን፤ በይሁዳ ወደ አለች ወደ ኢየሩሳሌም ይውጣ፤ ለእስራኤል ጌታ ለእግዚአብሔር በኢየሩሳሌም ቤተ መቅደስን ይሥራ።'),
  ('37a64143-a83e-58d7-ac99-736eaa44598a', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 6, 6, 'በያገራችሁ ያላችሁ ሁሉ በየአውራጃችሁ ወርቁንና ብሩን ርዱ።'),
  ('043b9df5-aaaa-5abb-a34b-9364d5b17553', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 7, 7, 'እናንተም ለእግዚአብሔር ቤተ መቅደስ ፈረሱንና ከብቱን ስእለት ካለው ሁሉ ጋር ጨምሩ።'),
  ('a0481026-076e-5f67-a7cf-c945851b7785', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 8, 8, '“የይሁዳና የብንያም ሀገሮች መሳፍንትም በየነገዳቸው፥ ሕዝቡም፥ ካህናቱም፥ ሌዋውያኑም፥ እግዚአብሔርም ልቡናውን ያነሣሣለት ሁሉ ይውጣ፤ በኢየሩሳሌም ያለውንም የእግዚአብሔርን ቤተ መቅደስ ይሥራ።'),
  ('c844487f-6cdb-59fd-a36a-c551a528ff71', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 9, 9, 'ባውራጃቸው ያሉም በወርቅና በብር፥ በፈረስና በከብት ሁሉ፥ ስእለት ያለባቸውም፥ ልቡናውም የወደደ ሁሉ ይርዷቸው።”'),
  ('110a62a8-d3d9-5c2c-af35-e6a20915f285', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 10, 10, 'ንጉሥ ቂሮስም ናቡከደነፆር ከኢየሩሳሌም ወስዶ በጣዖቶቹ ቤት ያኖረውን የእግዚአብሔርን ንዋየ ቅድሳት አወጣ።'),
  ('27696342-cd1a-5d86-a2dd-33fa491edb92', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 11, 11, 'የፋርስ ንጉሥ ቂሮስም ንዋየ ቅዱሳቱን ባወጣ ጊዜ ለጠባቂው ለሚትረዳጡ ሰጠው፥'),
  ('9dba676c-71a3-57da-a652-9880ba855c81', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 12, 12, 'ለይሁዳ የተሾመው ሰልምናስም ከእርሱ ተቀበለ፤'),
  ('abde16c8-33c3-5ee9-a246-d644dbfe7e07', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 13, 13, 'ቍጥሩም እንዲህ ነው፦ የወርቁ ወጭት አንድ ሺህ፥ የብሩም ወጭት አንድ ሺህ ነው። የብር ሳህኖች ሃያ ዘጠኝ፥ የወርቅ ጽዋዎችም ሠላሳ፥ የብርም ጽዋዎች ሁለት ሺህ አራት መቶ ዐሥር፥ ሌሎች ዕቃዎች ግን አንድ ሺህ ነበሩ።'),
  ('78ca8c0d-ae2e-555c-adfa-706639becaff', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 14, 14, 'የተመለሰውም የወርቁና የብሩ ዕቃ ሁሉ ተዳምሮ አምስት ሺህ አራት መቶ ስድሳ ዘጠኝ ነበር።'),
  ('14f93b8e-0142-5d16-a75e-abdc9020359c', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '7227e20b-1e9d-5c39-a8b8-ec23550c060a', 15, 15, 'ስልምናሶርም ከምርኮኞቹ ጋር ከባቢሎን ወስዶ ወደ ኢየሩሳሌም አገባው።'),
  ('d5551393-7e87-5b7c-a9da-414785176363', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 1, 16, 'ከእነርሱም ውስጥ የፋርስ ንጉሥ አርጤክስስ በይሁዳና በኢየሩሳሌም አውራጃዎች ያስቈጠራቸው አሉ፤ ቤልሞስና ሚጥራዳጢ፥ ጠቢልዮስና ራቲሞስ፥ ቤሔልጤሞስና ጸሓፊው ሲሳዮስ፥ ከነዚህም በታች ያሉ በሰማርያ የሚኖሩ ሁሉ፥ በሌላም ሀገር ያሉ ሁሉ እንዲህ ብለው መልእክት ጻፉ።'),
  ('06152fc9-0071-56a3-ae00-1944e3f0c908', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 2, 17, '“ለጌታችን ለንጉሡ ለአርጤክስስ፦ ከብላቴኖችህ፥ ከታሪክ ጸሓፊህ ከራቲሞስና ከጸሓፊው ከሰሜልዮስ ከእነርሱ በታች ከተሾሙት ሁሉና በቄሌ-ሶርያና በፊኒቄ ከሚኖሩ ሁሉ፦'),
  ('c6b2e9ad-12e2-5036-a08d-68a03b95a05f', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 3, 18, 'አሁንም ጌታችን ንጉሥ ሆይ፥ ይህን ዕወቅ፤ ከእናንተ ወደ እኛ የመጡ አይሁድ ወደ ኢየሩሳሌም ሄደው፥ ክፉና ከዳተኛ ከተማን ይገነባሉ፤ የገበያ ቦታዎችዋንና ቅፅሮችዋን፥ ቤተ መቅደስዋንም ያድሳሉ።'),
  ('acd0209a-4043-50fe-a283-4eff5b774dc3', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 4, 19, 'ያችም ከተማ ከተሠራች፥ ቅፅሯም ካለቀ፥ ከዚያ በኋላ ግብር አይገብሩም፤ ዳግመኛም መንግሥታችንን ይቀማሉ።'),
  ('f3957fb7-3317-581e-a25f-4a4ab7ed1694', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 5, 20, 'ቤተ መቅደስንም አሳምረው ይሠራሉ። አሁንም ስለዚህ ቸል አትበል።'),
  ('8be6cacc-1811-5cb4-afe6-7d20cb6348be', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 6, 21, 'በአባቶቻችሁ የታሪክ መጽሐፍ ይፈልጉ ዘንድ ወደ ንጉሡ ወደ ቂሮስ ላክ።'),
  ('a54b4f3f-e6b7-5d9d-a5e9-016695b44c04', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 7, 22, 'ያች ከተማ ነገሥታቱን የምትከዳና ከተሞችን እንደምታውክ፥ ስለዚህ የተጻፈ ታገኛለህ።'),
  ('4225c994-aaca-5a81-ac47-89a044027136', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 8, 23, 'አይሁድም ከጥንት ጀምሮ ከዳተኞች እንደ ሆኑ ተጽፎ ታገኛለህ፤ ስለዚህም ያች ከተማ ጠፍታ ነበር።'),
  ('14e31779-c6e3-514b-a366-8207e1b0f7a4', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 9, 24, 'አሁንም ጌታችን ንጉሥ ሆይ፥ እንነግርሃለን፤ ያች ከተማ ከተሠራች፥ ቅጽሮችዋም ከተፈጸሙ በኋላ ወደ ቄሌ-ሶርያና ወደ ፊንቄ አያሳልፏችሁም።”'),
  ('cb2437e0-899f-5a70-a697-03cb2e4f8219', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 10, 25, 'ከዚህ በኋላ ንጉሡ ለጻፈለት ለታሪክ ጸሓፊው ለራቲሞስና ለቤሔልማቴም፥ ለጸሓፊው ለሳሚልዮስም በሰማርያና በፊኒቂስ ለሚኖሩ፥ ከእነርሱ በታች ላሉ፥ ለቀሩትም እንደ ጻፉለት እንዲህ የምትል ደብዳቤን ጻፈላቸው።'),
  ('75f3daf9-a679-581c-a2e7-857479446648', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 11, 26, '“እኔም የላካችሁልኝን ደብዳቤ አንብቤ ይፈልጉ ዘንድ አዘዝሁ፤ ያቺም ከተማ ከጥንት ጀምሮ ነገሥታቱን የምትከዳ እንደ ሆነች አገኘሁ።'),
  ('e5e3d956-d351-5ae0-a7a3-4d3a309fc4af', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 12, 27, 'ሰዎችም ከዳተኞች እንደ ነበሩ፥ ሥራቸውም ጦርነት እንደ ነበረ፥ የኢየሩሳሌምም ነገሥታት ጠንካሮችና ክፉዎች እንደ ነበሩ፥ ቄሌ-ሶርያንና ፊኒቄን እንደ ገዙና እንደገበሩላቸው አገኘሁ።'),
  ('7f8ed139-9637-51db-a08a-93634f09c016', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 13, 28, 'አሁንም እነዚያን ሰዎች ያቺን ከተማ መሥራትን እንዲከለክሏቸው፥'),
  ('49d185ce-7215-50d2-a423-b58831fe7c05', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 14, 29, 'ነገሥታትም ይደክሙ ዘንድ ክፋትን እንዳታበዛ በውስጧ ምንም የሚሠራ እንዳይኖር እነሆ አዘዝሁ።”'),
  ('e168a181-d305-56df-a143-92b8237d5e29', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 15, 30, 'ከዚህ በኋላ ራቲሞስና ጸሓፊው ስልምዮስ፥ ከእነዚህም በታች ያሉት ንጉሡ አርጤክስስ የጻፋትን ያችን መልእክት ባነበቧት ጊዜ ከብዙ ሰዎች ጋር በብዙ ችኮላ ወደ ኢየሩሳሌም ፈረሶቻቸውን አስነሡ፤ የሚሠሩትንም ይከለክሉ ጀመሩ።'),
  ('5eb76e38-896b-5691-a782-b8323276515d', 'a0913c93-b6b5-5882-a70d-2349e9c83c52', '37c1c229-2ad1-535e-a767-5702bcb948cb', 16, 31, 'የኢየሩሳሌም ቤተ መቅደስ ሥራም እስከ ፋርስ ንጉሥ ዳርዮስ ሁለተኛዪቱ ዘመነ መንግሥት ድረስ ቆመ።'),
  ('b34348e9-9387-50e0-ade9-bb7bd44d37c4', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 1, 1, 'ንጉሡ ዳርዮስም በመንግሥቱ ላሉ ሁሉ ለቤተ ሰዎቹ፥ ለሜዶንና ለፋርስ መኳንንት ሁሉ፥'),
  ('4caa55e4-5e7d-5c31-a6a0-f56382087d29', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 2, 2, 'ለመሳፍንቱ ሁሉ፥ በሥሩ ለሚገኙ ከሕንድ እስከ ኢትዮጵያ ባሉ መቶ ሃያ ሰባት ግዛቶች ላሉ አዛዦችና ሹሞች ሁሉ ታላቅ በዓል አደረገ።'),
  ('b15c972f-560d-58d7-aca1-3384475c1c4d', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 3, 3, 'በልተውና ጠጥተውም ጠገቡ፤ ከዚህም በኋላ ወደ ቤታቸው ገቡ፤ ንጉሡ ዳርዮስም ወደ እልፍኙ ገብቶ ተኛ።'),
  ('1a9cd8be-4a74-5cb7-a100-566af7c68417', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 4, 4, 'ንጉሡንም የሚጠብቁት ሦስት ጐልማሶች ራስ ጠባቂዎች ነበሩ። እርስ በርሳቸውም እንዲህ ተባባሉ፦'),
  ('530ac79b-5384-5242-af26-d525a3b5bec9', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 5, 5, '“ሁላችን የሚያስጐመጅና የሚወደድ አንዳንድ ቃል አሻሽለን እንናገር ዘንድ ኑ፤ ነገሩ በጥበብ ከባልንጀራው ለተሻለለት ንጉሡ ዳርዮስ ብዙ ስጦታ ይስጠው፤ የአሸናፊነቱንም ዋጋ ይስጠው።'),
  ('4a09fdd3-43ce-5745-aa26-74d9b1b2f1a9', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 6, 6, 'ነጭ ሐርም ያልብሰው፤ በወርቅ ጽዋም ይጠጣ፤ በወርቅ አልጋም ይተኛ፤ በወርቅ ሰረገላም ላይ ይቀመጥ፤ ከተልባ እግርም የተሠራ መጠምጠሚያ በራሱ ላይ ያድርግ፤ በአንገቱም ላይ ዝርግፍ ወርቅ ይሰር።'),
  ('bb5ade75-5599-518b-a121-0747c1e3e1b3', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 7, 7, 'ስለ ጥበቡም ከንጉሡ ቀጥሎ ይቀመጥ፤ የንጉሡም ዘመድ ይሁን።”'),
  ('283fa50c-daf6-51b5-a591-27bfe1f34edc', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 8, 8, 'ከዚህም በኋላ ሁሉም የየራሳቸውን ቃል ጻፉ፤ አትመውም ከንጉሡ ከዳርዮስ መከዳ በታች አኖሩት።'),
  ('b328fb66-c85e-5d06-a8d0-9b35c61a8b6b', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 9, 9, 'እንዲህም አሉ፥ “ንጉሡ ከዕንቅልፉ በነቃ ጊዜ ይህቺን ደብዳቤ እንሰጠዋለን፤ ንጉሡና ሦስቱ የፋርስ ሹሞቹም በቃሉ ለተወደደውና ብልህ ለሆነው ይፍረዱለት።”'),
  ('e0cf2975-c9ac-5319-aa3d-8a99a99f5448', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 10, 10, 'አንደኛው “ወይን ያሸንፋል” ብሎ ጻፈ።'),
  ('153bb61d-d645-5df4-a25b-85da40078db8', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 11, 11, 'ሁለተኛውም “ንጉሥ ያሸንፋል” ብሎ ጻፈ።'),
  ('043f70c7-3800-595d-ad3a-a5b02b80ce76', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 12, 12, 'ሦስተኛውም “ሴቶች ያሸንፋሉ፤ ከሁሉም ይልቅ እውነት ታሸንፋለች” ብሎ ጻፈ።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('8928cd0f-6a8c-5422-a952-cc87130a63be', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 13, 13, 'ከዚህም በኋላ ዳርዮስ በነቃ ጊዜ ያቺን መጽሐፍ አንሥተው ሰጡት፤ አነበባትም።'),
  ('20b4182e-0336-59cb-a384-cad1d88eedef', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 14, 14, 'በሜዶንና በፋርስ ያሉ አዛዦችን ሁሉ፥ መሳፍንቱንና ሹሞቹን፥ አለቆቹንና መኳንንቱንም ወደ አዳራሹ ይጠሩ ዘንድ ላከ፤'),
  ('4ab6309e-6a99-5e13-ae15-34cebd06a233', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 15, 15, 'በአጠገቡም ተቀምጠው ያችን መጽሐፍ በፊታቸው አስነበቧት።'),
  ('bd2199ca-fdf1-5117-a557-40f886117a6a', '544d2914-8258-5c50-a596-c4984640a01f', 'dea0cf3a-8649-52ec-a784-5129c2199678', 16, 16, 'እርሱም፥ “እነዚያን ጐልማሶች ሰዎች ጥሯቸው፤ እነርሱ ራሳቸው ነገራቸውን ይናገሩ” አለ፤ ጠርተውም አገቡአቸው።'),
  ('00d3669d-a72f-57e4-a69c-986fbc1a7f8a', '544d2914-8258-5c50-a596-c4984640a01f', '3ff9bf9a-e7d8-5726-a014-36b8c2dc6065', 1, 17, 'እንዲህም አላቸው፥ “ነገራችሁን ተናገሩ፥” ወይን ያሸንፋል ብሎ መጀመሪያ የተናገረውም ይናገር ጀመር።'),
  ('51c8781e-875e-5127-a877-1b1d17fe24fb', '544d2914-8258-5c50-a596-c4984640a01f', '3ff9bf9a-e7d8-5726-a014-36b8c2dc6065', 2, 18, 'እንዲህም አለ፥ “እናንተ ሰዎች፥ ወይን የሚጠጣውን ሰው ሁሉ እንደሚያሸንፈው፥ አእምሮውንም እንደሚያሳጣው አስተውሉ።'),
  ('fe685fb8-7a8b-5df2-a355-9f7acbd01b3b', '544d2914-8258-5c50-a596-c4984640a01f', '3ff9bf9a-e7d8-5726-a014-36b8c2dc6065', 3, 19, 'የንጉሡንና የድኃ አደጉን፥ የባሪያዉንና የነጻዉን፥ የድኃውንና የባለጸጋውን ልቡና አንድ ያደርገዋል።'),
  ('98b2dbba-59fc-5922-a62f-6ee4ff79bf88', '544d2914-8258-5c50-a596-c4984640a01f', '3ff9bf9a-e7d8-5726-a014-36b8c2dc6065', 4, 20, 'የሰውን ሁሉ ልቡና ወደ ደስታ መልሶ ደስ ያሰኛቸዋል፤ ኀዘኑንም ሁሉ አያስቡትም፤ ጭንቀቱንም ሁሉ አያስቡትም።'),
  ('cefe7421-ff51-5b33-a356-d7e4f59aba99', '544d2914-8258-5c50-a596-c4984640a01f', '3ff9bf9a-e7d8-5726-a014-36b8c2dc6065', 5, 21, 'የሰውን ሁሉ ልቡና ባለ ጸጋ ያደርገዋል፤ ንጉሡንም አያስቡትም፤ ፈጣሪያቸውንም አያስቡትም ሰውንም ሁሉ ከባድ ነገር ያናግረዋል።'),
  ('89a81073-a1db-5b5c-ac2b-1fd9cee6596f', '544d2914-8258-5c50-a596-c4984640a01f', '3ff9bf9a-e7d8-5726-a014-36b8c2dc6065', 6, 22, 'በጠጡትም ጊዜ ወዳጅ ወዳጁን፥ ወንድምም ወንድሙን ይረሳዋል፥ ሾተላቸውንም ያማዝዛቸዋል።'),
  ('14ed552c-4e84-5bf5-afcf-faf2a689f39c', '544d2914-8258-5c50-a596-c4984640a01f', '3ff9bf9a-e7d8-5726-a014-36b8c2dc6065', 7, 23, 'ከስካራቸውም በነቁ ጊዜ ያደረጉትን አያስቡትም።'),
  ('ab327890-ae49-53c0-a6ab-c79701bad85c', '544d2914-8258-5c50-a596-c4984640a01f', '3ff9bf9a-e7d8-5726-a014-36b8c2dc6065', 8, 24, 'እናንተ ሰዎች፥ በግድ እንዲህ የሚያደርገው ወይን አያሸንፍምን?” ከዚህም በኋላ እርሱ እንዲህ ብሎ ተናግሮ ዝም አለ።'),
  ('b2a85979-b0c5-52a4-a97d-3ba7ca04847d', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 1, 1, 'ንጉሥ ያሸንፋል ያለው ሁለተኛውም ይናገር ጀመረ።'),
  ('ca905749-0da4-56cd-ad6a-aee7f99640ec', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 2, 2, '“እናንተ ሰዎች ሆይ፥ ሰዎች ምድርን የሚያሸንፏት፥ ባሕርንም፥ በውስጧ ያለውንም ሁሉ የሚገዙ አይደለምን?'),
  ('345fedff-a0ed-5b5b-aa35-0e75125a0e56', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 3, 3, 'ንጉሥም ለእነርሱ ጌታቸው ነው፤ ፈጽሞም ይገዛቸዋል፤ እርሱ ያዘዛቸውንም ሁሉ ያደርጋሉ።'),
  ('bb80495e-e0ac-518c-a64e-dc1274e2bd80', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 4, 4, 'ባልንጀራችሁን ግደሉ ቢላቸውም ይገድላሉ ወደ ጦርነትም ሂዱ ቢላቸው ይሄዳሉ፤ ተራሮችንም ይንዳሉ፤ አጥሩንና ግንቡንም ያፈርሳሉ።'),
  ('47b61dc5-013e-5d22-acd3-d824bc7dd6d9', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 5, 5, 'የንጉሡንም ትእዛዝ እንቢ እንዳይሉ ይገድላሉ፤ ይገደላሉም፤ ድል ቢያደርጉም የማረኩትን ምርኮ ሁሉ ለንጉሡ ያገባሉ።'),
  ('91915d8f-7189-5727-a62d-9903fb7019f7', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 6, 6, '“ያልዘመቱና ያልተዋጉ፥ ምድርን የሚያርሱ እነርሱ ዘርተው አዝመራቸውን ባገቡ ጊዜ ግብሩን ለንጉሡ ይሰጣሉ። ለንጉሡም ግብር እንዲከፍል አንዱ ሌላውን ያስገድደዋል።'),
  ('bbdf7ffb-d086-577f-a9b2-21338b8198c7', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 7, 7, 'እርሱ ግን አንድ ብቻ ነው፤ ግደሉ ቢላቸው ይገድላሉ፤ ተዉ ቢላቸውም ይተዋሉ።'),
  ('96113534-218d-5bd9-a726-389e33918fa7', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 8, 8, 'ግረፉ ቢላቸውም ይገርፋሉ፤ ገንቡ ቢላቸውም ይገነባሉ፤ አፍርሱ ቢላቸውም ያፈርሳሉ።'),
  ('4ce471a0-37ca-5a66-a7b5-788ac9c342aa', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 9, 9, 'ቍረጡ ቢላቸው ይቈርጣሉ፤ ትከሉ ቢላቸውም ይተክላሉ።'),
  ('f2b1f423-bbf9-5472-a1e2-385c6c1d3798', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 10, 10, 'ሕዝቡ ሁሉና ሠራዊቱም ላንድ ለእርሱ ይታዘዙለታል፤ ከዚህም ሁሉ ጋራ እርሱ ተቀምጦ በልቶና ጠጥቶ ይተኛል።'),
  ('77fb9af6-82f4-5f16-a81e-6a25e2567dde', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 11, 11, 'ሌላውም ዙሪያውን ይጠብቃል፤ ከእነርሱም ተለይቶ ሄዶ ጉዳዩን ማድረግ የሚችል አንድም የለም፤ በማናቸውም ነገር እንቢ ይሉት ዘንድ አይችሉም።'),
  ('2bc1e08c-5886-5a59-aa1d-367984b7bc88', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '522e8de7-19ec-583a-acd9-93a1aee98b8f', 12, 12, 'እናንተ ሰዎች ሆይ፥ ሁሉ እንዲህ የሚታዘዝለት ንጉሥ አያሸንፍምን?” ከዚህም በኋላ ዝም አለ።'),
  ('eb6fc210-45ea-5b25-a091-14a28c7205c5', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 1, 13, 'ስለ ሴቶችና ስለ እውነት የተናገረው ሦስተኛውም ይናገር ጀመረ፤ እርሱም ዘሩባቤል ነው። እርሱም እንዲህ አለ፦'),
  ('42ea4d2d-9bff-5bb0-a7bd-e3a6d5864534', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 2, 14, '“እናንተ ሰዎችሆይ፥ ንጉሡ ታላቅ አይደለምን? ሰዎቹስ ብዙ አይደሉምን? ወይንስ ብርቱ አይደለምን? እኒህንስ የሚገዛቸውና የሚያዝዛቸው ማነው? ሴቶች አይደሉምን?'),
  ('36c0b436-0733-516f-ad39-4a75ede642a8', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 3, 15, 'ሴቶች ምድርንና ባሕርን የሚገዙ ንጉሡንና ሕዝቡን ሁሉ ወልደዋል።'),
  ('3d65b2ba-fb50-50f2-a087-b1152b7c1a27', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 4, 16, 'ከእነርሱም ተወለዱ፤ እነርሱም ከእርሱ ወይን የሚገኝበት የወይን ተክልን የሚተክሉ ሰዎችን አሳደጉ።'),
  ('0ed750ae-c479-5342-acd4-da012d4bb286', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 5, 17, 'እነርሱም ለሰዎች ልብስን ይሠራሉ፤ ለወንዶችም ክብርን ያደርጋሉ፤ ወንዶችም ያለ ሴት መኖር አይቻላቸውም።'),
  ('23a46c06-345d-5fa8-aab4-364287ab91b1', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 6, 18, 'ሰዎች ምንም እንኳ ብሩንና ወርቁን፥ መልካሙንም ዕቃ ሁሉ ቢሰበስቡ፥ መልኳ ያማረና ደም ግባትዋ የተወደደ አንዲት ሴትን ባዩ ጊዜ፥'),
  ('2d7d008e-4bf7-58c4-aafd-acbbafd84118', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 7, 19, 'ያን ሁሉ ረስተው እርሷን ይመለከታሉ፤ አፏንም ያያሉ፤ ሁሉም ያደንቋታል፤ ከወርቅና ከብር፥ ካማረውም ዕቃ ሁሉ እርሷን ይመርጧታል።'),
  ('a236761a-1df8-5732-a08f-318445023df4', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 8, 20, 'ሰውም ያሳደገውን አባቱንና ሀገሩን ትቶ ሚስቱን ይከተላል።'),
  ('3e264824-19e6-54d2-ac02-eaf1afa71e2b', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 9, 21, 'ስለ ሚስቱም ነፍሱን ይሰጣል፤ አባትና እናቱን፥ ሀገሩንም አያስባቸውም።'),
  ('35ec8b78-4bef-5bf0-a7a4-22dacec2e5eb', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 10, 22, 'በዚህም ሴቶች እንደሚያሸንፏችሁ ታውቃላችሁ፤ ጥራችሁና ደክማችሁም ሁሉን አምጥታችሁ ለሴቶች የምትሰጧቸው አይደላችሁምን?'),
  ('ae0f91bb-310b-53bc-a57d-4b2b05b97488', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 11, 23, 'ወንድ ጦሩን ይዞ ወጥቶ ይሄዳል፤ ይሰርቃል፤ ይዘርፋልም፤ በባሕሩና በወንዙ ይጓዛል፤'),
  ('fda6a9ad-4378-59f4-ab83-e33347165a62', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 12, 24, 'አንበሳንም እያየ ይሄዳል፤ በጨለማም ይሄዳል። በሰረቀና በነጠቀ፥ በዘረፈም ጊዜ ሁሉን ለሚወዳት ይሰጣል።'),
  ('70abca0c-8848-57a6-a1d0-24d36d27f6d6', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 13, 25, 'ወንድ ከወለዱት ከእናቱና ከአባቱ ይልቅ ሚስቱን ይወዳታል።'),
  ('5b10d95b-3dcf-54c3-a6fd-ee6f7c014d39', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 14, 26, 'በሴቶች ምክንያት ልባቸው የጠፋ፥ ስለ እነርሱም የተገዙና ባሮች የሆኑ ብዙዎች ናቸው።'),
  ('b3b4e908-9bf4-556b-a0ee-d8a233fa36ec', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 15, 27, 'በሴቶችም ምክንያት የሞቱ፥ የተሳሳቱና የበደሉ ብዙዎች ናቸው።'),
  ('d77365b7-75f3-5ac9-ac69-c14382020a7b', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 16, 28, '“አሁንም አታምኑኝምን? ንጉሥ በሥልጣኑ ታላቅ አይደለምን? ሕዝቡስ ሁሉ ባዩት ጊዜ እርሱን መንካት የሚፈሩ አይደለምን?'),
  ('9e91725e-de3d-53f7-ab70-6392dbdfd887', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 17, 29, 'እነሆ የንጉሡ ዕቅብት የክቡር የበርጠቁ ልጅ ኤጴሜን በንጉሡ ቀኝ ትቀመጣለች።'),
  ('3502f12a-b228-52a2-af87-ab3a8d576999', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 18, 30, 'የንጉሡን ዘውድ ከራሱ ላይ አውርዳ በራሷ ላይ ትደፋለች፤ ንጉሡንም በግራ እጇ በጥፊ ትመታዋለች።'),
  ('35eb21f9-1e6b-5b02-a4f3-f5a70cd14941', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 19, 31, 'ከዚህም ሁሉ ጋራ ንጉሥ አፏን ያያል፤ ብትስቅ ይስቃል፤ ብትቈጣም ትናገር ዘንድ፥ ቍጣዋም ይበርድ ዘንድ ያቈላምጣታል።'),
  ('02dc5647-b447-531b-a59a-07beda06535e', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'df45bf63-5561-5a1c-a0a7-42511e71c842', 20, 32, 'እናንተ ሰዎች፥ እንዲህ የሚያደርጉ ሴቶች አያሸንፉምን?”'),
  ('4e1ef4ce-a3db-50ae-ae20-ee8e66ebecae', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '125ff78c-9a66-5c68-a905-2df2dafcf7ca', 1, 33, 'ከዚህም በኋላ ንጉሡና መኳንንቱ እርስ በርሳቸው ተያዩ፤ ከዚህም በኋላ የእውነትን ነገር ይናገር ጀመረ።'),
  ('68f8568f-84ec-5ded-a8c1-d2d67033b7b4', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '125ff78c-9a66-5c68-a905-2df2dafcf7ca', 2, 34, 'እንዲህም አለ፥ “እናንተ ሰዎች ሆይ፥ እውነት የሚያሸንፍ አይደለምን? ምድርስ ታላቅ ነው፤ ሰማይም ከፍ ያለ ነው፤ ፀሐይም በዙረቱ ፈጣን ነው፤ ባንዲት ቀን ሰማይን ዙሮ በቀኙ ወደ ቦታው ይመለሳልና'),
  ('7910f55c-f0f4-523b-ab3e-fcd6e45b4a45', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '125ff78c-9a66-5c68-a905-2df2dafcf7ca', 3, 35, 'እንዲህ የሚያደርግ ታላቅ አይደለምን? እውነትም ታሸንፋለች፤ ከዚህም ሁሉ ትበልጣለች።'),
  ('c51a9b10-d44c-5e80-a409-8672016bcce5', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '125ff78c-9a66-5c68-a905-2df2dafcf7ca', 4, 36, 'ዓለም ሁሉ እውነትን ይጠራታል፤ ሰማይም ይባርካታል፤ ፍጥረትም ሁሉ ለእርሷ ይንቀጠቀጣል፤ ይናወጣልም፤ ከእውነትም ጋር ዐመፃ አይገኝም።'),
  ('420729e8-bcc3-5901-a8ab-32510b280203', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '125ff78c-9a66-5c68-a905-2df2dafcf7ca', 5, 37, 'ወይን በደለኛ ነው፤ ንጉሥም በደለኛ ነው፤ ሴቶችም በደለኞች ናቸው፤ የሰው ልጅም በደለኛ ነው፤ ሥራቸውም ሁሉ በደል ነው፤ ይህ ሁሉ በእውነት ዘንድ የለም፤ እነዚህም ሁሉ በበደላቸው ይሞታሉ።'),
  ('0de1e0a9-1daa-5638-a2e7-0c1772e9aea1', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '125ff78c-9a66-5c68-a905-2df2dafcf7ca', 6, 38, '“እውነት ግን ሁልጊዜ ታሸንፋለች፤ ሕይወትም ናት፤ ለዘለዓለሙም ፈጽማ ጸንታ ትኖራለች።'),
  ('c5caa189-bfa8-5df7-adec-f53ddb9a8660', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '125ff78c-9a66-5c68-a905-2df2dafcf7ca', 7, 39, 'በእርሷ ዘንድ ልዩነትና ለፊት ማዳላት የሉም፤ ነገር ግን እውነት በሐሰትና በክፉ ሁሉ አትኖርም። ሰዎች ሁሉም ሥራዋን ይወድዳሉ።'),
  ('ce1f0e29-0820-5e44-a8e2-92abc2fb25fe', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '125ff78c-9a66-5c68-a905-2df2dafcf7ca', 8, 40, 'በፍርድዋም ዐመፅ የለባትም፤ እርስዋም ታሸንፋለች፥ መንግሥት፥ ገናናነትና በዓለም ውስጥ ያለ ሥልጣን ሁሉ የእርስዋ ነው፤ መንግሥት የእርሱ የሆነ እግዚአብሔር ይመስገን” ብሎ ዝም አለ።'),
  ('05d746b4-c1c3-51fd-a435-666bb10f26ca', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 1, 41, 'ከዚህም በኋላ ሕዝቡ ሁሉ ድምፃቸውን ከፍ በማድረግ፥ “እውነት ታላቅ ናት! ፈጽማም ታሸንፋለች!” አሉ።'),
  ('35b73fcd-b8cb-5cd6-a709-490f26f795e2', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 2, 42, 'ንጉሡም፥ “የምትወድደውን ከተጻፈው ሁሉ አብልጠህ ለምን፤ እኔም እሰጥሃለሁ። አንተ ዐዋቂ ሆነሃልና፥ ተለይተህም ከእኔ ጋር ትቀመጣለህ፤ የእኔም ዘመድ ትሆናለህ” አለው።'),
  ('5ac130c9-045d-5a9b-a237-0e3e6d512985', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 3, 43, 'እርሱም ንጉሡን እንዲህ አለው፥ “በነገሥህ ጊዜ ኢየሩሳሌምን ትሠራት ዘንድ የተሳልኸውን ስእለት ዐስብ።'),
  ('1c3f2749-26c8-5cf6-a306-f79bcf165787', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 4, 44, 'ከኢየሩሳሌም የተወሰዱትን፥ ቂሮስ ባቢሎንን ለማጥፋት በጀመረ ጊዜ ለይቶ ያኖራቸውንና ወደዚያ ለመመለስ የተሳላቸውን ዕቃዎችን ትመልስ ዘንድ ዐስብ።'),
  ('bef39140-851b-57ab-aa13-70a61ca8bdd1', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 5, 45, 'አንተም ከለዳውያን ይሁዳን ባጠፏት ጊዜ ኤዶማውያን ያቀጠሏትን ቤተ መቅደስ ትሠራ ዘንድ ተስለሃል።'),
  ('e49594c2-7c90-57eb-ad71-7f1a0d5fe1e6', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 6, 46, 'አሁንም ጌታዬ ንጉሥ ሆይ፥ የምማልድህና የምለምንህ ይህ ነው፤ ካንተም የምፈልጋት ታላቅ ነገር ይህች ናት፥ ጌታዬ ለሰማይ አምላክ የተሳልኸውን ስእለትህን ታደርግ ዘንድ እሺ በለኝ፥ ካንደበትህ የወጣውንም አድርግ።”'),
  ('a5362d1d-4503-5859-a110-8d51659ff6cb', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 7, 47, 'ከዚህ በኋላም ንጉሡ ዳርዮስ አቅፎ ሳመው፤ እርሱንና ይሠሯት ዘንድ ወደ ኢየሩሳሌም የሚወጡትን ከእርሱ ጋር ያሉትን ሁሉ ይሹ ዘንድ ወደ ግምጃ ቤት አዛዦችና ወደ አለቆች፥ ወደ መሳፍንቱና ወደ መኳንንቱ ሁሉ ደብዳቤዎችን ጻፈለት።'),
  ('e5256f43-7ade-56ce-af7e-75c468b10c02', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 8, 48, 'ከእርሱም ጋር ከተማዋን ይሠሩ ዘንድ የዋንዛውን እንጨት ወደ ኢየሩሳሌም እንዲያመጡ በቄሌ-ሶርያና በሊባኖስ ላሉ መሳፍንት ሁሉ ደብዳቤዎችን ጻፈ።'),
  ('b6b6a028-c6f7-5faf-adcc-243b77704edf', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 9, 49, 'ኀይላቸው የሚሆኑ ባልንጀሮችንም ሁሉ ከመገዛታቸው ነጻ ያወጧቸው ዘንድ ከግዛቱ ወደ ይሁዳ ለሚወጡትም አይሁድ ሁሉ ጻፈ። የግምጃ ቤት አዛዦች፥ መሳፍንቱና መኳንንቱም ወደ በራቸው እንዳይገቡ ጻፈ።'),
  ('320e738d-615c-5c6a-a803-4dbe6dff1b82', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 10, 50, 'ባውራጃቸው ላሉትም ግብሩን ይተዉላቸው ዘንድ፥ ኤዶማውያንም አጽንተው የያዙትን ቦታቸውን ለአይሁድ ይተዉ ዘንድ ጻፈ።'),
  ('9dd48bef-f60e-54ad-a19e-72f4dc1e8337', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 11, 51, 'ሕንጻውም እስኪፈጸም ድረስ ለቤተ መቅደሱ ሥራ የሚሆን በየዓመቱ ሃያ መክሊት ወርቅ ይሰጧቸው ዘንድ ጻፈ።'),
  ('a9d6c2cd-0e4f-5d6c-aca5-3cf4dd4f3715', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 12, 52, 'እንደ ልማዳቸውም በሕጉ ሁልጊዜ በመሠዊያው ላይ ለሚሠዉት የዘወትር መሥዋዕት ዐሥራ ሰባት፥ በየዓመቱም ሌላ ዐሥር መክሊት ወርቅ ይሰጧቸው ዘንድ ጻፈ።'),
  ('3e10d044-1d4c-5bb0-a8e1-f4205b897249', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 13, 53, 'ከተማዋንም ለመሥራት ከባቢሎን ለሚመጡት ሁሉ ለእነርሱና ለልጆቻቸው አገዛዝን ይተውላቸው ዘንድ ጻፈ።'),
  ('ef1d6778-aa81-599d-a982-6a557f69b7e5', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 14, 54, 'ለሚወጡ ካህናትም ሁሉ ምግባቸውንና የሚያገለግሉበት የአገልግሎት ልብሳቸውን ጻፈላቸው።'),
  ('401fc0ba-f716-50ba-a7a2-1c1039f22a26', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 15, 55, 'ለሌዋውያንም፦ የኢየሩሳሌምና የቤተ መቅደስ ሥራ እስኪፈጸም ድረስ ምግባቸውን ይሰጧቸው ዘንድ ጻፈላቸው።'),
  ('3466189f-4265-561e-a37a-1185cc851840', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 16, 56, 'ለሚያገለግሉና ከተማዋን ለሚሠሩ ሁሉ ምግባቸውን ይሰጧቸው ዘንድ ጻፈላቸው።'),
  ('aeea8a79-b712-571d-a8f9-9078219d4154', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', '143b3674-91c5-51cf-ab2d-17534b05f1e7', 17, 57, 'ቂሮስ ከባቢሎን ያወጣውን ንዋየ ቅድሳቱንም ሁሉ፥ ሁሉንም ቂሮስ እንዳዘዘላቸው ያደርጉ ዘንድ፥ እርሱም እንዲሁ እንዲያደርጉና ወደ ኢየሩሳሌም እንዲልኩ አዘዛቸው።'),
  ('b0dbcc39-3949-50b1-a6d2-655d8084c6d6', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'b39dea00-6e4d-5409-a6ce-7c8b0c0fa595', 1, 58, 'ከዚህም በኋላ ወጣቱ በወጣ ጊዜ በኢየሩሳሌም አንጻር ፊቱን ወደ ሰማይ አቀና፤ የሰማይንም ንጉሥ አመሰገነው።'),
  ('545de53e-1248-57fe-adda-6feda44552ca', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'b39dea00-6e4d-5409-a6ce-7c8b0c0fa595', 2, 59, 'እንዲህም አለ፥ “ድል መንሣት ከአንተ ዘንድ ነው፤ ጥበብም ከአንተ ዘንድ ነው፤ ክብርም ለአንተ ነው፤ እኔም ያንተ ባሪያ ነኝ።'),
  ('1f13fe65-cb41-5124-a842-262e61d930e7', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'b39dea00-6e4d-5409-a6ce-7c8b0c0fa595', 3, 60, 'ጥበብን የሰጠኸኝ አንተም ቡሩክ ነህ፤ የአባቶቻችን ጌታ አመሰግንሃለሁ።”'),
  ('54876d8a-48f2-5205-af87-1de778cff1ee', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'b39dea00-6e4d-5409-a6ce-7c8b0c0fa595', 4, 61, 'ደብዳቤዎችንም ተቀብሎ ወደ ባቢሎን ሄደ፤ ይህንም ለወንድሞቹ ሁሉ ነገራቸው።'),
  ('88b71ca9-1e81-551e-a161-fe3bb487d06e', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'b39dea00-6e4d-5409-a6ce-7c8b0c0fa595', 5, 62, 'ያባቶቻቸውንም አምላክ አመሰገኑ፤ ዕረፍትን ሰጥትዋቸዋልና፥ ይቅርም ብሏቸዋልና፥'),
  ('669147b3-21e5-5499-a967-63d6b95ba4f0', '74c2d417-ad7e-5459-a0f7-7c9f20689a2b', 'b39dea00-6e4d-5409-a6ce-7c8b0c0fa595', 6, 63, 'ኢየሩሳሌምንና ስሙ የተጠራባት ቤተ መቅደስንም ይሠሩአት ዘንድ፤ ለመውጣት ፈቅዶላቸዋልና። በመሰንቆና በበገናም ደስ እያላቸው ሰባት ቀን ተቀመጡ።'),
  ('562b1f77-c62b-53ef-a32a-00e68332d4c0', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 1, 1, 'ከዚህም በኋላ የሚወጡትን ያባቶቻቸውን ቤተ ሰቦች አለቆች በየወገኖቻቸው ለዩ፤ ሚስቶቻቸውን፥ ወንዶች ልጆቻቸውንና ሴቶች ልጆቻቸውን፥ ወንዶች አገልጋዮቻቸውንና ሴቶች አገልጋዮቻቸውን፥ ከብቶቻቸውንም ለዩ።'),
  ('ab9163ee-0870-57a5-aca8-bd46cb8f9ecf', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 2, 2, 'ዳርዮስም በመሰንቆ፥ በበገናና በከበሮ በሰላም ወደ ኢየሩሳሌም ያደርሷቸው ዘንድ ከእነርሱ ጋር ሺህ ፈረሰኞችን ላከ።'),
  ('504fa7ac-2e85-5845-ab81-7562f9cfb409', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 3, 3, 'ወንድሞቻቸውም ሁሉ እየዘፈኑ ከእነርሱ ጋር በአንድነት እንዲሄዱ አደረገ።'),
  ('9ef099e4-56d7-5640-ac5a-40d3ca993c8b', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 4, 4, 'በየሀገራቸውና በየወገናቸው፥ አለቆቻቸውን ተከትለው የወጡ ሰዎችም ስማቸው ይህ ነው።'),
  ('a6a0ae83-aa76-5a88-a1dd-5e765e24f9f3', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 5, 5, 'ካህናት የፊንሐስ ልጆች፥ የአሮን ልጆች፥ የሰራህያ ልጅ የኢዮሴዴቅ ልጅ ኢዮስስ፥ ከይሁዳ ወገን ከፋሬስ ወገን ከዳዊት ወገን የሆነ የሰላትያል ልጅ የዘሩባቤል ልጅ ኢዮአቄም፤'),
  ('774a7638-5649-55d8-abd7-e1925de1ed23', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 6, 6, 'ዘሩባቤልም በፋርስ ንጉሥ በዳርዮስ ፊት በሁለተኛው ዓመተ መንግሥቱ በመጀመሪያው ወር በሚያዝያ የጥበብን ነገር የተናገረ ነው።'),
  ('c05ce540-4bcf-5994-a0e4-e632f2950b16', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 7, 7, 'የባቢሎን ንጉሥ ናቡከደነፆር ከማረካቸው ከፋርስ ምርኮ የወጡ ከይሁዳ የሆኑ ሰዎች እኒህ ናቸው።'),
  ('15ace88d-8f9d-5d9a-a75b-915246c90e34', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 8, 8, 'እነርሱም ወደ ኢየሩሳሌምና ወደ ሌላዎች የይሁዳ ክፍሎች ተመለሱ። ሁሉንም በየከተሞቻቸው ላካቸው፤ እነዚህም አስቀድመው ከተሾሙላቸው ከመጀመሪያዎቹ ሹሞች፥ ከኢያሱና ከዘሩባቤል፥ ከነህምያ፥ ከዛርያስ፥ ከሬስያስ፥ ከኤኔንዮስ፥ ከመርዶክዮስ፥ ከቦኤልሰሮስ፥ ከአስፈራሶስ፥ ከሬልዮስ፥ ከኢሮምዮስና ከበዓናስ ጋር የመጡ ናቸው።'),
  ('671a50c0-6fa0-5659-acd4-238388e5134b', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 9, 9, 'የሕዝቡም ቍጥር፥ የፋሬስ ልጆች ሁለት ሺ አንድ መቶ ሰባ ሁለት ናቸው፤ የሳፋንም ልጆች ሦስት መቶ ሰባ ሁለት ናቸው።'),
  ('fea96374-ab90-5f4d-a0d7-5bd02e51e817', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 10, 10, 'የሐሬስ ልጆችም ሰባት መቶ አምሳ ስድስት ናቸው።'),
  ('6eb62016-33ee-5f1e-a726-35f3eca70700', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 11, 11, 'የፈሓት ሞዓብ ልጆችም ከሮብአምና ከኢዮስስ ልጆች ጋራ ሁለት ሺ ስምንት መቶ ዐሥራ ሁለት ናቸው።'),
  ('cab6353e-d100-5bf4-a342-26ca8ff9ee28', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 12, 12, 'የኤላም ልጆች አንድ ሽህ ሁለት መቶ አምሳ አራት ናቸው፤ የዛጦንም ልጆች ዘጠኝ መቶ ስድሳ ናቸው፤ የኮሮባ ልጆች ሰባት መቶ አምሳ ናቸው፤ የባኒን ልጆችም ስድስት መቶ አርባ ስምንት ናቸው።'),
  ('3a5d2f7c-0b9e-53ad-a536-a02ddc5b4c19', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 13, 13, 'የቤባይ ልጆችም ስድስት መቶ ሠላሳ ሦስት ናቸው፤ የዓዝጋድ ልጆችም ሺህ ሦስት መቶ ሃያ ሁለት ናቸው።'),
  ('3ddf6032-c840-53ff-ac55-5c86728f3d49', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 14, 14, 'የአዶኒቃም ልጆች ስድስት መቶ ስድሳ ሰባት ናቸው፤ የበጉዋይ ልጆችም ሁለት ሺህ ስድሳ ሰባት ናቸው፤ የአዲኖስም ልጆች አራት መቶ አምሳ አራት ናቸው።'),
  ('a2e696b7-2ff3-5d7b-ad59-fd4ddd816421', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 15, 15, 'የአዝራቅዮ፥ የቄላንና የአዛጦን ልጆች ስድሳ ሰባት ናቸው፤ የአዛሩ ልጆችም አራት መቶ ሠላሳ ሁለት ናቸው።'),
  ('aecb4e98-f9ff-5b64-aae0-9e68f1a29190', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 16, 16, 'የሐናንያም ልጆች መቶ አንድ ናቸው፤ የአሮምና የባሕሴ ልጆች ሦስት መቶ ሃያ ሦስት ናቸው፤'),
  ('f8b45463-a9db-5aa4-add2-b5ef48e220f3', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 17, 17, 'የአርስፋሪስት ልጆች አንድ መቶ ዐሥራ ሁለት ናቸው። የበጢሩስ ልጆችም ሦስት ሽህ አምስት ናቸው፤ የኤናውም ልጆች መቶ አምሳ ስምንት ናቸው። የቤትሎሞን ልጆችም መቶ ሃያ ሦስት ናቸው።'),
  ('9c8416f3-6c74-533d-a098-ec7b2d0856ed', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 18, 18, 'ከኒጤባስም ልጆች አምሳ አምስት፥ ከኤናጦስም ልጆች መቶ አምሳ ስምንት፥ የቤትሳሞስ ልጆች አርባ ሁለት፥'),
  ('2083c41a-9380-5535-a3b8-9c4bb69b5603', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 19, 19, 'የቀታርቲሐርዮስ ልጆችም ሃያ አምስት፥ የጳሬስና የፎሮግ ልጆች ሰባት መቶ አርባ ሦስት ናቸው፤'),
  ('e07a8b40-9654-5c71-ade7-dc2e37fd34bb', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 20, 20, 'አካዲያስና አሚዳውያንም አራት መቶ ሃያ ሁለት ናቸው፥ የቂራማና የጋቢስ ልጆች ስድስት መቶ ሃያ አንድ ናቸው።'),
  ('c0ee30ac-3e78-572d-aa0b-52ab5ea8951a', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 21, 21, 'የመቃሉንም ልጆች መቶ ሃያ ሁለት፥ ከቤጠሊም ልጆች አምሳ ሁለት፥ የኔፋስም መቶ አምሳ ስድስት ናቸው።'),
  ('3ff69626-6502-5908-a610-0cb7427db00b', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 22, 22, 'የቀላምሎምና የሁነስ ልጆች ሰባት መቶ ሃያ አምስት፥ የኤሪካ ልጆች ሦስት መቶ አርባ አምስት፤'),
  ('0cc85de0-577c-562e-a2ff-f93e5af613d3', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 23, 23, 'የሰናሐሰም ልጆች ሦስት ሺህ ሦስት መቶ አንድ ናቸው።'),
  ('ff167781-f772-5921-a377-612559571773', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 24, 24, 'የኢዮስስ ልጆች፥ ካህናቱም ከአናሲብ ልጆች ጋራ ስምንት መቶ ሰባ ሁለት ናቸው። የኤምሩት ልጆችም ሁለት መቶ አምሳ ሁለት ናቸው።'),
  ('c68570ed-78f6-5952-a077-7275a15574e3', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 25, 25, 'የፋሰሩ ልጆችም አንድ ሺህ ሁለት መቶ አርባ ሰባት፥ የካርሚ ልጆች ሽህ ዐሥራ ሰባት ናቸው።'),
  ('734bdd8d-ee2b-53c4-a4da-70dbc1ac6ed9', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 26, 26, 'ሌዋውያን ግን፦ የኢዮስስ የቆድሔሉ፥ የባኑና የሱዱይ ልጆች ሰባ አራት፤'),
  ('6c5a8474-3521-561a-ae69-2dff07c4c6b8', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 27, 27, 'መዝሙር የሚዘምሩ የካህናት ልጆች፦ የአሳፍ ልጆች መቶ ሃያ ስምንት፥'),
  ('d7e03fa4-4b61-500f-a965-e24f8d13e46e', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 28, 28, 'በረኞች የሰሎም ልጆች፦ የአጤር ልጆች፥ የጤልሞን ልጆች፥ የዓቁብ ልጆች፥ የሐጢጣ ልጆች፥ የሰባይ ልጆች ሁሉም መቶ ሠላሳ ዘጠኝ ናቸው።'),
  ('53e1c3d0-fdf9-5637-aa33-33cfc682f158', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 29, 29, 'የቤተ መቅደስ አገልጋዮች፦ የኤሳው ልጆች፥ የሓሱፋ ልጆች፥ የጠብይት ልጆች፥ የቀራስ ልጆች፥ የሲዓ ልጆች፥ የፋዶን ልጆች፥ የሌብና ልጆች፤ የአባጋ ልጆች፥'),
  ('4ba82163-b4bd-5823-a7d1-63563391cfb9', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 30, 30, 'የዐቁድ ልጆች፥ የሐጡ ልጆች፥ የኪጣብ ልጆች፥ የአቀባ ልጆች፥ የሳባዊ ልጆች፥ የሐና ልጆች፥ የቃጡዓ ልጆች፥ የጌዱር ልጆች፤'),
  ('af3f5907-652b-56ab-a0b9-3e9a462d2741', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 31, 31, 'የያሳሩ ልጆች፥ የዴሳን ልጆች፥ የነሒሴቦ ልጆች፥ የካሴባ ልጆች፥ የቀዚራ ልጆች፥ የዖዝያ ልጆች፥ የፋኑሕ ልጆች፥ የአዛራ ልጆች፥ የባስቲ ልጆች፥ የአስና ልጆች፥ የማአኒ ልጆች፥ የነፋሲ ልጆች፥ የአቁፋ ልጆች፥ የአኪባ ልጆች፥ የአሱር ልጆች፥ የፋራቂም ልጆች፥ የባስሊም ልጆች፤'),
  ('d613158c-d8ec-5fad-a6a8-aec34be25de7', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 32, 32, 'የሚዳ ልጆች፥ የኩታ ልጆች፥ የሴርያ ልጆች፥ የባርኩስ ልጆች፥ የሴሬር ልጆች፥ የቶምሔ ልጆች፥ የናሲ ልጆች፥ የአጢፍ ልጆች።'),
  ('021371d7-e035-56da-a619-f2e785633b1d', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 33, 33, 'የሰሎሞን አገልጋዮች ልጆች፦ የአሳፍያት ልጆች፥ የፋሬዳ ልጆች፥ የሐሊ ልጆች፥ የሎዝን ልጆች፥ የያሴዳሔል ልጆች፥ የሳፋት ልጆች፤'),
  ('264f8df4-ebac-5a60-a300-022416dc1d64', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 34, 34, 'የሐጋያ ልጆች፥ የፈቀሬተሰባይ ልጆች፥ የሳሮትዮ ልጆች፥ የማሲያስ ልጆች፥ የጋስ ልጆች፥ የአዱስ ልጆች፥ የሱባስ ልጆች፥ የአፌራ ልጆች፥ የባሩዲስ ልጆች፥ የሳፋጥ ልጆች፥ የአሎም ልጆች፤'),
  ('bd3a0928-922c-5977-a78d-f729aebd1ac0', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 35, 35, 'እነዚህ ቤተ መቅደሱን የሚያገለግሉ ሁሉና የሰሎሞን አገልጋዮች ልጆች ሁሉ ሦስት መቶ ሰባ ሁለት ናቸው።'),
  ('62953ceb-e8a0-574c-a0b1-55fb346d3def', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 36, 36, 'ከቴልሜሬትና ከቴሌርሳስ የወጡት ሁሉ፥ አለቆቻቸውም ካራኃታንና ከሀለር ናቸው።'),
  ('3b44e606-1d64-59c0-a7f5-b31d59ca815b', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 37, 37, 'ሀገራቸውንና ዘመዳቸውን፥ ከእስራኤልም ወገን መሆናቸውን መናገር አልቻሉም። የጡባን ልጆች፥ የዱዳን ልጆች፥ የነቆዲንም ልጆች ስድስት መቶ አምሳ ሁለት ናቸው።'),
  ('10c2cbff-4afc-5a4a-aed3-031b27ecd845', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 38, 38, 'ከካህናቱ ወገን የሆኑ፥ የክህነትን ሥራ የሚሠሩ፥ ተመዝግበው ያልተገኙ፦ የሐብያ ልጆች፥ የአቅቦስ ልጆች፥ ከቤርዜሊ ልጆች ወገን በስሙ የተጠራች አውግያን ያገባ የይሆድስ ልጆች ናቸው።'),
  ('b34d18c4-4586-5064-ae21-f9402deeebf9', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 39, 39, 'የዘመዶቹ ትውልድ ቍጥር በተጻፈበት መጽሐፍ ትውልዱን ፈልገው አጡ፤ የክህነት አገልግሎቱንም አስተዉት።'),
  ('0712ebba-e5d4-51d7-ae72-d411f3cc5ce9', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 40, 40, 'ነህምያና ሐቴርሳታም፥ የክህነትና የጽድቅ ልብስ የሚለብስ ሊቀ ካህናት እስኪሾሙ ድረስ ከተቀደሰው ነገር ሁሉ እንዳይሰጡት አዘዙአቸው።'),
  ('4356219f-0bd7-5145-a9a3-d543b3d43ac4', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 41, 41, 'ከዐሥራ ሁለት ዓመት በላይ ያሉት እስራኤል ሁሉ ከሴቶች አገልጋዮቻቸውና ከወንዶች አገልጋዮቻቸው በቀር አርባ ሁለት ሺህ ሦስት መቶ ስድሳ ነበሩ።'),
  ('921a288d-ccb9-58ce-a474-07783dc0fc79', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 42, 42, 'ወንዶችና ሴቶች አገልጋዮቻቸውም ሰባት ሺህ ሦስት መቶ ሠላሳ ሰባት ነበሩ፤ ሴቶችና ወንዶች መዘምራንም ሁለት መቶ አርባ አምስት ነበሩ።'),
  ('5b267923-84a9-50eb-ae00-3b4ed40ee6d3', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 43, 43, 'ግመሎቹም አራት መቶ ሠላሳ አምስት፥ ፈረሶቹም ሰባት ሺህ ሠላሳ ስድስት፥ በቅሎዎችም ሁለት መቶ አርባ አምስት፥ አህዮችም አምስት ሺ አምስት መቶ ሃያ አምስት ነበሩ።'),
  ('eac15f44-f86a-5e2c-a0c0-a47e07e24d46', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 44, 44, 'ከሀገሮቻቸው አለቆችም ዐያሌዎች በኢየሩሳሌም ወዳለው ወደ እግዚአብሔር ቤተ መቅደስ በደረሱ ጊዜ እንደሚቻላቸው መጠን ቤተ መቅደሱን በቦታው ያቆሙት ዘንድ ጸለዩ።'),
  ('464ef37d-610b-5bd3-a594-653d3785b22e', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 45, 45, 'ለቤተ መቅደሱ የሥራ ጣጣም አንድ ሺህ ወቄት ወርቅ፥ አምስት ሺህ ወቄት ብርና መቶ የካህናት ልብስ ወደ ግምጃ ቤቱ ያገቡ ዘንድ ተሳሉ።'),
  ('8d3e3b02-c744-5610-a088-468f4edd49c7', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '527e8df0-6b04-54a3-ad72-c68919220e8d', 46, 46, 'ካህናቱም፥ ሌዋውያኑም በኢየሩሳሌምና በአካባቢዋ ከሚኖሩ ሕዝቦችም፥ መዘምራኑ፥ በር ጠባቂዎቹም፥ እስራኤልም ሁሉ በየቦታቸው ይቀመጡ ነበር።'),
  ('4fc310bb-a845-5488-a7a1-7d660e59fa6f', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '7cea8262-70ce-537e-a1e6-23d8c38c504f', 1, 47, 'የእስራኤልም ልጆች በያገራቸው ተቀምጠው ሳሉ በሰባተኛው ወር መባቻ በምሥራቁ በር ዳርቻ ባለው አደባባይ በአንድነት ተሰበሰቡ።'),
  ('56e6cb8c-39e9-58a5-adc3-1149dc6e98d3', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '7cea8262-70ce-537e-a1e6-23d8c38c504f', 2, 48, 'የኢዮሴዴቅ ልጅ ኢያሱና ወንድሞቹ ካህናት፥ የሰላትያል ልጅ ዘሩባቤልና ወንድሞቹም፥ ተነሡ፤'),
  ('29d42f2a-88e1-5348-a149-e3661b156609', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '7cea8262-70ce-537e-a1e6-23d8c38c504f', 3, 49, 'በእግዚአብሔር ሰው በሙሴ መጽሐፍ እንደ ተጻፈ እንደ ሕጉ መሥዋዕት ይሠዉ ዘንድ ለእስራኤል ፈጣሪ ለእግዚአብሔር መሠዊያውን አዘጋጁ።'),
  ('d7dd9cdc-04bc-5cb0-ab05-e263d1c6555c', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '7cea8262-70ce-537e-a1e6-23d8c38c504f', 4, 50, 'ሌሎችም የምድር አሕዛብ ከእነርሱ ጋር ተሰብስበው በቦታቸው በመሥዊያው አጠገብ ተዘጋጁ፤ ተሰልፈው ነበርና፤ ከዚህም በኋላ የምድር አሕዛብን አሸነፏቸው፤ በየጊዜው የሚደረገውንም የነግሁንና የሠርኩን መሥዋዕት ቍርባኑንም ለእግዚአብሔር አቀረቡ።'),
  ('fc5db71a-2c5e-5a8e-a91b-a463569532da', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '7cea8262-70ce-537e-a1e6-23d8c38c504f', 5, 51, 'በሕግ እንደ ተጻፈ የዳስ በዓልን አደረጉ፤ በየዕለቱም እንደ ቀድሞው መሥዋዕቱን ሠዉ።'),
  ('9b5d158e-f534-5629-af0b-08bbfbec5365', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '7cea8262-70ce-537e-a1e6-23d8c38c504f', 6, 52, 'ዳግመኛም የዘወትሩን ቍርባንና የሰንበቱን መሥዋዕት፥ የመባቻዎችንና የተቀደሱትን በዓላት መሥዋዕት አቀረቡ።'),
  ('41c49736-4a7d-5d82-a94e-21f2deed7f4b', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '7cea8262-70ce-537e-a1e6-23d8c38c504f', 7, 53, 'ለእግዚአብሔርም ስእለት የተሳሉ ሰዎች ሁሉ ከሰባተኛው ወር መባቻ ጀምሮ መሥዋዕቱን ለእግዚአብሔር ያቀርቡ ጀመሩ፤ የእግዚአብሔርም ቤተ መቅደስ ገና አልተሠራም ነበር።'),
  ('4b711f62-e2df-56ca-a2ed-ec9fa3692bb1', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '7cea8262-70ce-537e-a1e6-23d8c38c504f', 8, 54, 'ደንጊያ ለሚያለዝቡና እንጨት ለሚጠርቡ ሰዎችም ወርቅና ብር ሰጧቸው፤ ለምግባቸውም መብሉንና መጠጡን ሰጧቸው።'),
  ('dbb475b5-2224-5b4d-adb4-6aca48f320bd', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', '7cea8262-70ce-537e-a1e6-23d8c38c504f', 9, 55, 'የሲዶናና የጢሮስ ሰዎችንም የዋንዛውን እንጨቶች ከሊባኖስ በኢዮጴ ባሕር በኩል በመርከብ ያገቡላቸው ዘንድ አዘዟቸው፤ ከፋርስ ንጉሥ ከቂሮስ ዘንድም የትእዛዝ ደብዳቤ ጻፉላቸው።'),
  ('5229a6f7-3413-54a8-a018-d5cf39bc57b3', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 1, 56, 'ከዚህ በኋላ ወደ ኢየሩሳሌም ወደ እግዚአብሔር ቤት በደረሱ በሁለተኛው ዓመት በሁለተኛው ወር የሰላትያል ልጅ ዘሩባቤል፥ የኢዮሴዴቅ ልጅ ኢያሱ፥ ወንድሞቻቸው ካህናቱና፥ ሌዋውያኑም፥ ከምርኮ ወደ ኢየሩሳሌም የተመለሱትም ሁሉ ቤተ መቅደስን ይሠሩ ዘንድ ጀመሩ።'),
  ('214f6181-35b3-5397-a26e-503b2868bf4f', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 2, 57, 'ወደ ኢየሩሳሌምና ወደ ይሁዳ በገቡ በሁለተኛው ዓመት በሁለተኛው ወር መባቻ የእግዚአብሔር ቤተ መቅደስን መሠረት አኖሩ።'),
  ('8aa7e204-1ab4-5138-a0d5-490eb1520a3a', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 3, 58, 'ሌዋውያንንም በቤተ እግዚአብሔር ሥራ ላይ ሾሟቸው፤ ኢያሱና ልጆቹ፥ ወንድሞቹም፥ ወንድሙ አድያምያልም፥ የኢያሱ ልጅ ሄሜዴቦን፥ የኤልያዳን ልጅ የይሁዳ ልጆች፥ ከልጆቹና ከወንድሞቹ ጋር ሌዋውያንም ሁሉ የእግዚአብሔርን ቤት ይሠሩ ዘንድ የሥራ አለቆች ሆነው በአንድነት ተሾሙ።'),
  ('cf6cbd9e-e527-58b8-abc0-ec429373b463', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 4, 59, 'ካህናቱም ልብሰ ተክህኖውን ለብሰው፥ መሰንቆውንና መለከቱን ይዘው ቆሙ። የአሳፍ ልጆች ሌዋውያንም እግዚአብሔርን በጸናጽል ያመሰግኑ ነበር።'),
  ('27b65aee-9c0e-58b3-a595-81578c714996', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 5, 60, 'በእሴይ ልጅ በእስራኤል ንጉሥ በዳዊት መዝሙርም ያመሰግኑት ነበር።'),
  ('2d381d8f-112e-54c5-a8af-ac94859b6186', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 6, 61, 'ጮኸውም እያስተዛዘሉ እግዚአብሔርን ያመሰግኑ ነበር፤ ምስጋናው ለዘለዓለም ነውና፥ ቸርነቱም በእስራኤል ሁሉ ላይ ነውና።'),
  ('52590174-ec6e-50bd-a327-127bd3864562', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 7, 62, 'የእግዚአብሔር ቤተ መቅደስ በመነሣቱ ሕዝቡ ሁሉ መለከቱን እየነፉ፥ ከፍ ባለ ድምፅም እየጮሁ እግዚአብሔርን አመሰገኑ።'),
  ('1e34de50-d399-5010-a8c4-d4b880247e5c', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 8, 63, 'ቀድሞ በዚያ በያገራቸው ይኖሩ ከነበሩ ከካህናትና ከሌዋውያንም የዚያን ቤት ሥራውን ቀድሞ ያዩት አለቆችም በታላቅ ድምፅ ፈጽመው እያለቀሱ መጡ።'),
  ('450bf562-53d2-5b0d-a2c6-c314e4a6adab', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 9, 64, 'ሕዝቡም እስኪሰማ ድረስ ደስ ብሏቸው ቀንደ መለከት የሚነፉ ብዙ ሰዎች ነበሩ።'),
  ('c6ae6e93-554d-51cb-ad10-82718ca0db42', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 10, 65, 'በሩቅ እስኪሰማ ድረስ በታላቅ ድምፅ ቀንደ መለከት የሚነፉ ብዙ ሰዎች ነበሩና ከሕዝቡ ልቅሶ የተነሣ የመለከቱን ድምፅ አልሰሙም።'),
  ('af274c1d-b6d3-5bf8-a3a7-2a15fff13d2a', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 11, 66, 'የይሁዳና የብንያም ወገኖች ጠላቶችም ያን በሰሙ ጊዜ የቀንደ መለከቱ ድምፅ ምን እንደ ሆነ ያውቁ ዘንድ መጡ።'),
  ('7932cde1-a74d-5db9-afd4-1a045dff449d', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 12, 67, 'ከምርኮ የተመለሱ እስራኤልም የፈጣሪያቸው የእግዚአብሔርን ቤተ መቅደስ እንደሚሠሩ ባወቁ ጊዜ፥'),
  ('d2aa8b9e-15d9-5c9e-a93a-048ac074a046', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 13, 68, 'ወደ ዘሩባቤልና ወደ ኢያሱ ወደ አገሮቻቸውም ሹሞች ሄደው እንዲህ አሏቸው፥ “እኛ ከእናንተ ጋራ እንሥራ፥'),
  ('3c58d1d0-535c-5416-aeda-f3118a63f826', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 14, 69, 'የአሦር ንጉሥ ስልምናሶር ወደዚህ ካመጣን ጀምሮ እንደ እናንተ ለፈጣሪያችሁ እንገዛለንና፥ መሥዋዕቱንም ለእርሱ እንሠዋለንና።”'),
  ('7e8477cd-43b6-5280-a0bf-11796195ceac', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 15, 70, 'ዘሩባቤልና ኢያሱም፥ የየሀገሮቻቸው ሹሞችም እንዲህ አሉአቸው፥ “የእስራኤልን ጌታ የእግዚአብሔርን ቤት መሥራት ለእኛም፥ ለእናንተም አይገባንም፤'),
  ('33117d63-4550-5656-ac45-59cd4f31f7e9', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 16, 71, 'ሐጌ እንደ ተናገረ፥ የፋርስ ንጉሥ ቂሮስም እንዳዘዘን የእስራኤልን ጌታ የእግዚአብሔርን ቤተ መቅደስ እኛ ለብቻችን እንሠራለን።”'),
  ('b369a4ea-ce78-5c98-aa6b-7a4c25bfe70e', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 17, 72, 'የሚመክቱ ያገሩ ሰዎች አሕዛብ ግን በይሁዳ ያሉትን ፈጽመው ተሰብስበው ተዋጓቸው።'),
  ('53fac024-47e6-557a-a7d9-fc3c8c1b45c5', 'dbb307dd-3ebc-52c6-a878-d9a81434858e', 'b2cd125e-dea7-501e-a984-0c9af704dfa3', 18, 73, 'አወኳቸው፤ ሥራቸውንም አስቆሙ፤ በንጉሡ በቂሮስ ዘመንም ሁሉ እንዳይሠሩ ከለከሏቸው፤ እስከ ዳርዮስ ሁለተኛ ዓመተ መንግሥትም ድረስ ሥራውን አስተዉአቸው።'),
  ('8edad9f4-9e92-52b9-a70c-78d02697ddbd', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 1, 1, 'በዳርዮስ በሁለተኛው ዓመተ መንግሥቱ፦ ነቢያቱ ሐጌና የሐዶ ልጅ ዘካርያስ በይሁዳና በኢየሩሳሌም ባሉ አይሁድ ላይ በእስራኤል አምላክ በእግዚአብሔር ስም ትንቢት ተናገሩ።'),
  ('b667c619-78b8-54c7-ac0b-e22aa4a6b638', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 2, 2, 'ከዚህም በኋላ የሰላትያል ልጅ ዘሩባቤልና የኤዮሴዴቅ ልጅ ኢያሱ ተነሡ፤ የእግዚአብሔርም ነቢያት እየረዱአቸው ከእነርሱ ጋር ሳሉ በኢየሩሳሌም ያለውን የእግዚአብሔርን ቤት ይሠሩ ጀመሩ።'),
  ('4aa70fee-c6a0-5c51-a98d-21b8c52941f0', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 3, 3, 'በእነዚያም ወራት የሶርያና የፊንቂስ ገዥ ሲሳኒስና ሳትራቡዛኒስ ከባልንጀሮቻቸው ጋር ወደ እነርሱ መጡ።'),
  ('e9b7e2d1-187e-52a4-a57b-89605359b4c5', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 4, 4, 'እንዲህም አሏቸው፥ “ይህን ቤትና ጣራውን፥ ሌላውንም ሥራ ሁሉ ትሠሩ ዘንድ ማን አዘዛችሁ? የሚሠሩትስ ግንበኞች እነማን ናቸው?”'),
  ('10d0f33c-9c65-5729-a199-d9f6fc55eba8', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 5, 5, 'ያንጊዜም እግዚአብሔር ይቅር ብሏቸዋልና ለአይሁድ ሽማግሌዎች ባለሟልነትን ሰጣቸው።'),
  ('25553cb4-a839-5110-a31f-c4489323e02b', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 6, 6, 'ወደ ዳርዮስ እስኪልኩ፥ ደብዳቤንም እስኪያመጡላቸው ድረስ ሥራውን አልከለከሏቸውም።'),
  ('a1fec44f-df62-5dbc-ad0d-f1e04567c25b', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 7, 7, 'የሶርያና የፊንቂስ ገዥ ሲሳኒስና ሳትራቡዛኒስ፥ በሶርያና በፊንቂስም ከእነርሱ ጋር ያሉ ሹሞች፥ ባልንጀሮቻቸውም “ለንጉሡ ለዳርዮስ ትድረስ” ብለው ወደ ዳርዮስ ጽፈው ላኩ።'),
  ('9c6caa75-78a7-54ee-abb6-c28cbda16c2e', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 8, 8, '“ጌታችን ንጉሥ ሆይ ሰላም ለአንተ ይሁን! ሁሉን እንድታውቅ ወደ ይሁዳ ወደ ኢየሩሳሌም በመጣን ጊዜ የአይሁድ ምርኮኞች አለቆችን በኢየሩሳሌም ከተማ አገኘናቸው።'),
  ('9ffe6635-df15-5453-a243-1663bfd2e864', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 9, 9, 'በተጠረበና ዋጋው ብዙ በሆነ ድንጋይ፥ በየወገናቸው ማዕዘን ባላቸው እንጨቶችም ታላቅና አዲስ የሆነውን የእግዚአብሔርን ቤት ሲሠሩ አገኘናቸው።'),
  ('4b0ee72c-ce54-5ace-aa92-3463c859f5b3', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 10, 10, 'በችኰላም ይሠሩና ያፋጥኑ ነበር፤ በእጃቸውም እያስተካከሉ በትጋት ይሠሩ ነበር። በክብርና በጥንቃቄም ተሠራ።'),
  ('acf56c51-2747-538a-a84b-9a1b8b0a955b', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 11, 11, 'ከዚህም በኋላ ‘ይህን ቤት ትሠሩ ዘንድ፥ ይህንም መሠረት ትጥሉ ዘንድ ማን አዘዛችሁ?’ ብለን አለቆቻቸውን ጠየቅናቸው።'),
  ('bdb78280-4298-5eaf-ad38-e21f3f8cdbf9', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 12, 12, 'ሰዎቻቸውንና የሥራ መሪዎቻቸውንም በየስማቸው ጽፈን ወደ አንተ እንልክ ዘንድ መረመርናቸው፤ አለቆቻችውንም ጠየቅናቸው።'),
  ('64ce03fe-8119-5fa8-ac2c-56ba15957c3d', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 13, 13, 'እነርሱም እንዲህ ብለው መለሱልን፦ ‘እኛስ ምድርንና ሰማይን የፈጠረ የእግዚአብሔር ባሮች ነን።’'),
  ('46183ae5-02a3-54f0-a2da-b7b5675308f2', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 14, 14, 'ይህ ቤት ከብዙ ዘመን አስቀድሞ በታላቁና በብርቱው የእስራኤል ንጉሥ ሰሎሞን ተሠርቶ ተፈጽሞ ነበር።'),
  ('9835b46f-a792-5ad0-a8a5-409b1aad5fa8', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 15, 15, 'ነገር ግን አባቶቻችን ኀጢአት ሠርተው ሰማያዊውን የእስራኤል ፈጣሪ አሳዝነውታልና በባቢሎን ንጉሥ በናቡከደነፆርና በፋርስ ንጉሥ እጅ ጣላቸው።'),
  ('8a30f65b-2b85-57f9-ac75-d76ff8a08660', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 16, 16, 'ይህንም ቤት አፈረሰ፤ በእሳትም አቃጠለ፤ ሕዝቡንም ማረከ፤ ወደ ባቢሎንም ወሰዳቸው።'),
  ('33a02813-344d-51b7-a572-05ab73c54160', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 17, 17, 'ቂሮስም በባቢሎን በነገሠ በመጀመሪያው ዓመት ንጉሡ ቂሮስ ይህን ቤት ይሠሩ ዘንድ ጻፈ።'),
  ('5feaee01-cfe3-5de4-a0c0-4cf63846c2a8', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 18, 18, 'ናቡከደነፆርም በኢየሩሳሌም ካለው ቤተ መቅደስ ያወጣውን፥ ባዳራሹም ያኖረውን የወርቅና የብር ንዋየ ቅድሳቱን፥ ንጉሥ ቂሮስ በባቢሎን ካለ አዳራሹ አውጥቶ ለዘሩባቤልና ለገዥው ለሰናባሶርስ ሰጣቸው።'),
  ('0aa5a868-1bda-570b-a36f-6e84182b368a', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 19, 19, 'ይህንም ንዋየ ቅድሳት ወስደው በኢየሩሳሌም ባለ ቤተ መቅደስ ያኖሩት ዘንድ፥ የእግዚአብሔርንም ቤተ መቅደስ በቦታው ይሠሩት ዘንድ አዘዛቸው።'),
  ('777c68f7-2ae4-5f6b-aae0-7dd4833211f6', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 20, 20, 'ከዚህም በኋላ ያ ሰናባሳሮስ በደረሰ ጊዜ በኢየሩሳሌም ያለ የእግዚአብሔርን ቤት ይሠራ ጀመረ፤ ከዚያም ቀን ጀምሮ እስከ ዛሬ ድረስ ይሠሩ ነበር፤ ነገር ግን አልጨረሱም።'),
  ('592fced7-0638-5149-a03a-48ec416313d5', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 21, 21, 'አሁንም ጌታችን ንጉሥ ሆይ! በባቢሎን ያለ የንጉሡን የቂሮስን መንግሥት የታሪክ መጻሕፍት ገልጠህ መርምር።'),
  ('13375baf-5872-51aa-a8a4-2776d567cf3b', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '227011fb-759a-588a-aa5d-6cb7e14d74a1', 22, 22, 'ንጉሡ ቂሮስ በኢየሩሳሌም ያለውን የእግዚአብሔርን ቤት ይሠሩ ዘንድ እንደ ፈቀደ ብታገኝ፥ ጌታችን ንጉሥ ሆይ! አንተም ፈቅደህላቸው እንደ ሆነ ስለዚህ ነገር ላክልን።”'),
  ('9419ff16-44c2-570d-a780-43781ed5aab8', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', 'c62f49bc-0e2e-58d6-a84c-34cc8036e7d1', 1, 23, 'ከዚህም በኋላ ንጉሡ ዳርዮስ በባቢሎን የታሪክ መጽሐፍ ውስጥ ይፈልጉ ዘንድ አዘዘ፤ በሜዶን አውራጃ በጣኒስ-ባሪ ከተማ ውስጥ የታሪክ መጽሐፉን ባኖሩበት በአንድ ቦታ ተገኘ፤ እንዲህም ይላል፦'),
  ('55240c49-e4ad-5aaf-ada6-32fdd449e696', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', 'c62f49bc-0e2e-58d6-a84c-34cc8036e7d1', 2, 24, '“በንጉሡ በቂሮስ በመጀመሪያው ዓመተ መንግሥት በየዕለቱ በእሳት መሥዋዕት የሚሠዉበትን፥ በኢየሩሳሌም ያለውን የእግዚአብሔርን ቤት ይሠሩ ዘንድ አዘዘ።'),
  ('02716b7f-5f03-5a02-add2-1be678e19869', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', 'c62f49bc-0e2e-58d6-a84c-34cc8036e7d1', 3, 25, 'ቁመቱ ስድሳ ክንድ ወርዱም ስድሳ ክንድ ይሁን፤ ሥራውም በሦስት ወገን በጥርብ ድንጋይ፥ ባንዲት ወገንም በሀገሩ አዲስ የዝግባ እንጨት ይሁን፤ ወጭውንም ከንጉሡ ከቂሮስ ዕቃ ቤት ይሰጧቸው ዘንድ አዘዘ።'),
  ('7ae17ea3-685d-5a3c-aa26-315b5bb827cb', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', 'c62f49bc-0e2e-58d6-a84c-34cc8036e7d1', 4, 26, 'ናቡከደነፆርም በኢየሩሳሌም ካለው ከቤተ መቅደስ አውጥቶ ወደ ባቢሎን የወሰደውን የወርቁንና የብሩን የእግዚአብሔርን ቤት ንዋየ ቅድሳት በኢየሩሳሌም ወዳለው ቀድሞ ወደ ነበረበት ወደዚያ ቤት ይመልሱት ዘንድ አዘዘ።”'),
  ('3af11da0-65cb-5c8c-a605-8868bc2f43b6', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '67f8297d-7e92-549b-a167-2474a4844cb6', 1, 27, 'የእግዚአብሔር ባሪያ የይሁዳ አለቃ ዘሩባቤልና በይሁዳ ያሉ ሽማግሌዎች የእግዚአብሔርን ቤት በቦታው ይሠሩት ዘንድ የሶርያና የፊንቂስ ገዥ ሲሳኒስና ሳትራቡዛኒስ፥ ከእነርሱም ጋራ ያሉ ጓደኞቻቸው የሶርያና የፊንቂስ ሹሞች ቦታቸውን ይተዉላቸው ዘንድ አዘዘ፤'),
  ('71ab4b39-7c5e-5f90-ac7f-b3bb132e1bed', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '67f8297d-7e92-549b-a167-2474a4844cb6', 2, 28, '“እኔም የእግዚአብሔርን ቤት ሠርተው እስኪፈጽሙ ድረስ ከተማረኩበት የተመለሱ የአይሁድ ወገኖች ሁሉ አንድ ሁነው ተሰማርተው የእግዚአብሔርን ቤት ይሠሩ ዘንድ አዘዝኋቸው።'),
  ('b1ad3fc1-de4a-515a-a70d-d6b4b68b41cf', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '67f8297d-7e92-549b-a167-2474a4844cb6', 3, 29, 'ከቄሊ-ሶርያና ፊኒቂ ከሚገባው ግብር ለእግዚአብሔር መሥዋዕት ፍየሎችንና ላሞችን፥ በጎችንም እንደ ሥርዐቱ ለእነዚህ ሰዎችና ለአለቃው ለዘሩባቤልም ሰጥታችሁ ደስ አሰኙአቸው።'),
  ('78063f70-6ae6-546e-acad-ca1bbcd5459f', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '67f8297d-7e92-549b-a167-2474a4844cb6', 4, 30, 'እንደዚሁም የሚያነዱትን እንጨት፥ ስንዴውን፥ ጨዉንና ወይኑን፥ ዘይቱንም፥ የዘወትሩንም ወጭ ገንዘብ ሁሉ፥ በየዓመቱም የሚያደርሳቸውን፥ በኢየሩሳሌም ያሉ ካህናቱ ያሏችሁን ያህል ስጧቸው፤ ግብሩንም ሳትከራከሩ እነርሱ የሚሏችሁን የሚበቃቸውን ስጧቸው።'),
  ('521e2760-998f-5aa8-ac0f-4486b9cd33b9', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '67f8297d-7e92-549b-a167-2474a4844cb6', 5, 31, 'ስለ ንጉሡና ስለ ልጆቹ ለልዑል እግዚአብሔር ቍርባኑን ያቀርቡ ዘንድ፥ ስለ ሕይወታቸውም ይጸልዩላቸው ዘንድ።'),
  ('56038c67-8396-5dfb-abef-ccf508d60542', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '67f8297d-7e92-549b-a167-2474a4844cb6', 6, 32, '“በዚች ደብዳቤ እንደ ተጻፈ አልሠራም የሚል፥ የሚከራከራቸውም ቢኖር ከራሱ ቤት እንጨት አምጥተው በዚያ ይስቀሉት፤ ገንዘቡንም ይዝረፉት፤ ለንጉሡ ቤትም ይሁን።'),
  ('2210ded9-6b5a-5510-a0f7-7d2628e79944', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '67f8297d-7e92-549b-a167-2474a4844cb6', 7, 33, 'ስለዚህም ስሙ በዚያ የተጠራ እግዚአብሔር በኢየሩሳሌም ያለውን የእግዚአብሔርን ቤት ሥራ ይከለክሏቸው ዘንድ፥ ክፉ ሥራም ይሠሩ ዘንድ እጃቸውን የሚያነሡ ነገሥታትንና አሕዛብን ሁሉ ያጥፋቸው።'),
  ('0531664a-23dc-5120-ac28-c7d5f144cffe', '3210c7cb-1f97-5d0c-a9c6-5aa29d5546d0', '67f8297d-7e92-549b-a167-2474a4844cb6', 8, 34, 'እኔ ዳርዮስ እንዲህ አድርገው ተግተው ይሠሩ ዘንድ አዘዝሁ።”'),
  ('ec9089f4-4e90-5b33-af26-ac11a3a0f181', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'b9953004-2806-59d8-a6ab-5e18fcf193e4', 1, 1, 'ከዚህም በኋላ የቄሌ-ሶርያና የፊንቂስ ገዥ ሲሳኒስና፥ ሳትራቡዛኒስ፥ ባልንጀሮቻቸውም ንጉሡ ዳርዮስ እንዳዘዘ ይሠሩ ዘንድ ጀመሩ።'),
  ('d9c1b8e4-4daf-55a7-a6f3-8c574b940b73', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'b9953004-2806-59d8-a6ab-5e18fcf193e4', 2, 2, 'እነርሱም ተግተው ከአይሁድ ሽማግሌዎች ጋር ቆመው ያዝዙ ነበር።'),
  ('bd28b7a7-963a-5343-a33f-14bafad8554a', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'b9953004-2806-59d8-a6ab-5e18fcf193e4', 3, 3, 'የቤተ መቅደሱም ሥራ፥ ነቢያቱ ሐጌና ዘካርያስ ትንቢት እየተናገሩላቸው ፈጥኖ ተከናወነ።'),
  ('86517b94-86cf-5118-abad-6487fa992332', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'b9953004-2806-59d8-a6ab-5e18fcf193e4', 4, 4, 'በፋርስ ነገሥታት በቂሮስና ዳርዮስ፥ በአርጤክስስም ፈቃድ በእስራኤል አምላክ በእግዚአብሔር ትእዛዝ ሥራውን ፈጸሙ።'),
  ('5987b628-d691-56a9-af71-b391bc298e3e', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'b9953004-2806-59d8-a6ab-5e18fcf193e4', 5, 5, 'ቤተ መቅደሱ አዳር በሚባል ወር በጨረቃ በስምንተኛው ቀን በዳርዮስ በስድስተኛው ዓመተ መንግሥት ተፈጸመ።'),
  ('efb49ac1-0256-5a27-a603-c2acfd7a827b', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'b9953004-2806-59d8-a6ab-5e18fcf193e4', 6, 6, 'የእስራኤል ልጆችና ካህናት፥ ሌዋውያንም፥ ከምርኮ የተመለሱት ሕዝቡም ሁሉ በሙሴ መጽሐፍ እንደ ተጻፈ ሥርዐቱን አደረጉ።'),
  ('f55427b1-42ac-5010-a29f-9036a12a9019', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'b9953004-2806-59d8-a6ab-5e18fcf193e4', 7, 7, 'ለእግዚአብሔር ቤተ መቅደስ ቅዳሴም ቤት መቶ ኮርማዎችን፥ ሁለት መቶ ፍየሎችና አራት መቶ በጎችን አቀረቡ።'),
  ('77f217bd-3003-5a06-a43b-23819591d501', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'b9953004-2806-59d8-a6ab-5e18fcf193e4', 8, 8, 'ስለ እስራኤልም ኀጢአት ሁሉ ማስተስረያ፦ ባሥራ ሁለቱ ነገደ እስራኤል ሹሞች ቍጥር ዐሥራ ሁለት ሙክቶችን አቀረቡ።'),
  ('360b0734-5299-5d9d-afd2-4f134699c19d', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'b9953004-2806-59d8-a6ab-5e18fcf193e4', 9, 9, 'ካህናቱና ሌዋውያኑም በሙሴ መጽሐፍ እንደ ተጻፈ እንደ ሥርዐታቸው ለእስራኤል አምላክ ለእግዚአብሔር አገልግሎት በየወገናቸው ልብሰ ተክህኖውን ለብሰው ቆሙ። በረኞችም በየበሮቻቸው ቆሙ።'),
  ('748a52bb-e8cf-50cc-a317-82e6752d51b3', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'c5f91f56-f087-5cbb-a533-94ad45c481d2', 1, 10, 'ከምርኮ የተመለሱ የእስራኤል ልጆችም በመጀመሪያው ወር በዐሥራ አራተኛው ቀን የፋሲካን በዓል አከበሩ። ካህናቱና ሌዋውያኑ፥ ሁሉም ራሳቸውን በአንድነት አንጽተዋልና።'),
  ('58c175d9-c5f6-5fd6-abde-34cf373bc3a5', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'c5f91f56-f087-5cbb-a533-94ad45c481d2', 2, 11, 'ከምርኮ የተመለሱት ልጆቻቸው ግን ሁሉም ሰውነታቸውን አላነጹም ነበር፤ ሌዋውያን ግን ሁሉም ነጽተው ነበርና፤'),
  ('fd5816b9-2c4f-5c36-a561-b5f4e7756131', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'c5f91f56-f087-5cbb-a533-94ad45c481d2', 3, 12, 'ከምርኮ ለተመለሱት ለእስራኤል ልጆች ለወንድሞቻቸው ለካህናትና ለራሳቸውም የፋሲካን በግ ሠዉ።'),
  ('52120cf7-255f-5a62-a662-4fa500c3f025', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'c5f91f56-f087-5cbb-a533-94ad45c481d2', 4, 13, 'ከምርኮ የተመለሱ የእስራኤል ልጆች ሁሉ፥ እግዚአብሔርንም ይሹት ዘንድ ከምድር አሕዛብ ርኵሰት የተለዩት ሁሉ ፋሲካውን በሉ።'),
  ('7dc230b9-1f3a-5386-a362-e13df97cd34a', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'c5f91f56-f087-5cbb-a533-94ad45c481d2', 5, 14, 'በእግዚአብሔርም ፊት ደስ ብሏቸው ሰባት ቀን የቂጣዉን በዓል አከበሩ።'),
  ('7571e160-f9f8-5ed6-a919-9398bf4a89bf', '1507bd0c-8131-5a62-a1fe-dd145b298370', 'c5f91f56-f087-5cbb-a533-94ad45c481d2', 6, 15, 'እግዚአብሔር የፋርሱን ንጉሥ ልቡና መልሶላችዋልና፥ ለእስራኤል አምላክ ለእግዚአብሔር ሥራም እጃቸውን አጽንቶላቸዋልና።'),
  ('29885186-4515-52c9-ab0f-6d65c22199a5', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '16057baf-399b-593f-aa9a-87f7cf3e875d', 1, 1, 'ከዚህም በኋላ በፋርስ ንጉሥ በአርጤክስስ መንግሥት ዕዝራ መጣ፤ እርሱም የሠራያ ልጅ፥ የአዛርያስ ልጅ፥ የኬልቅዩ ልጅ፥ የሴሎም ልጅ፤'),
  ('ace0ee02-c06e-545f-acae-0d4ecdfa89e9', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '16057baf-399b-593f-aa9a-87f7cf3e875d', 2, 2, 'የሳዶቅ ልጅ፥ የአኪጦብ ልጅ፥ የአማርትዩ ልጅ፥ የአዝያን ልጅ፥ የቡቂ ልጅ፥ የአቢሱ ልጅ፥ የፊንሐስ ልጅ፥ የአልዓዛር ልጅ፥ የመጀመሪያው ካህን የአሮን ልጅ፤'),
  ('1d4097b7-9aae-5a4a-a5ef-367902ba1af1', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '16057baf-399b-593f-aa9a-87f7cf3e875d', 3, 3, 'ይህም ዕዝራ ከባቢሎን መጣ፤ እርሱም የእስራኤል አምላክ የሰጠውን የሙሴን ኦሪት ሁሉ ያውቅ ነበረ፤ እርሱም ጸሓፊ ነበር።'),
  ('62b8bf08-537d-55cb-a5e5-42a0ae12899e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '16057baf-399b-593f-aa9a-87f7cf3e875d', 4, 4, 'ንጉሡም ክብርን ሰጠው፤ በፊቱ ባለሟልነትን አግኝትዋልና፥ በሁሉም ላይ ሹሞታልና።'),
  ('13c1d88d-1c6d-501f-af5b-fa4c4f63ee4e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '16057baf-399b-593f-aa9a-87f7cf3e875d', 5, 5, 'ከእስራኤልም ልጆች፥ ከካህናቱና ከሌዋውያኑ፥ ከመዘምራኑና ከበረኞች፥ ከቤተ መቅደስ አገልጋዮችም፥ ዐያሌዎቹ ወደ ኢየሩሳሌም ወጡ።'),
  ('c1d259c9-aa21-58ae-a7b0-d5f4c86dea2b', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '16057baf-399b-593f-aa9a-87f7cf3e875d', 6, 6, 'በአርጤክስስ በሰባተኛው ዓመተ መንግሥቱ፥ በአምስተኛው ወር፥ በወሩ መባቻ ከባቢሎን ወጡ፤ እግዚአብሔርም መንገዳቸውን እንዳቀናላቸው በመጀመሪያው ወር መባቻ ወደ ኢየሩሳሌም ደረሱ።'),
  ('74e7380b-3927-56fd-ab39-fec06c835809', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '16057baf-399b-593f-aa9a-87f7cf3e875d', 7, 7, 'ዕዝራም ብዙ ትምህርት የሚያውቅ ነበረ፤ ለእስራኤልም ሥርዐትንና ፍርድን ያስተምር ዘንድ ከእግዚአብሔር ሕግና ትእዛዝ የሚጐድለው አልነበረም።'),
  ('13df747c-2246-5abb-ac31-16f58fe15b22', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 1, 8, 'ንጉሡ አርጤክስስም ወደ ካህኑና የእግዚአብሔርን ሕግ ወደሚጽፈው ወደ ዕዝራ ደብዳቤ ላከ። ከአርጤክስስም የእግዚአብሔርን ሕግ ወደሚጽፈው ወደ ካህኑ ዕዝራ የተላከው ደብዳቤ እንዲህ ይላል፦'),
  ('d981b95a-c4e9-55af-a8fd-f0320f4f6b6a', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 2, 9, '“ከንጉሠ ነገሥት ከአርጤክስስ ለእግዚአብሔር ሕግ ጸሓፊ፥ ለካህኑ ለዕዝራ ሰላም ለአንተ ይሁን፤'),
  ('dc576b9f-40ec-5d76-a627-52342c891d48', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 3, 10, 'እኔ ሰውን በመውደድ አስቤ ከአይሁድ ወገን በመንግሥቴ ካሉ ከካህናትና ከሌዋውያን ወደ ኢየሩሳሌም ይሄዱ ዘንድ የሚወዱትን ሁሉ ከአንተ ጋር ይሂዱ ብዬ አዝዣለሁ።'),
  ('ba1127a9-da75-5164-ac44-17725986571b', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 4, 11, 'ወደ ኢየሩሳሌምም ይሄዱ ዘንድ የሚወዱ ሁሉ ይሁዳንና ኢየሩሳሌምን አይተው ከእናንተ ጋር ይተባበሩ።'),
  ('86fad678-0787-5529-a9bf-0822fc461228', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 5, 12, 'እንደ እግዚአብሔር ሕግ ሄደው ያደርጉ ዘንድ እኔና ሰባቱ ባለሟሎች፥ አማካሪዎችም እንዲህ አዝዘናል።'),
  ('9e688030-b1a4-5197-aeac-0126356c8dd7', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 6, 13, 'እኔና ባለሟሎች የተሳልነውን ቍርባን፥ በባቢሎን ሀገር የተገኘውንም ወርቁንና ብሩን ሁሉ በኢየሩሳሌም ለእግዚአብሔር ያቀርቡ ዘንድ፥'),
  ('81890cfc-dfe6-5efd-aa3b-78343a8e4f20', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 7, 14, 'ሕዝቡ በኢየሩሳሌም ባለው በእግዚአብሔር ቤተ መቅደስ ከሚያገቡት ስእለት ጋራ ወርቁንና ብሩን፥ ለበሬዎች፥ ለፍየሎችና ለበጎች መግዣ ይሰብስቡ፥'),
  ('a6708567-b55e-5a6e-a767-ea4fe0956ca5', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 8, 15, 'እንደ ሥርዐታቸው በኢየሩሳሌም ባለው በእግዚአብሔር መሠዊያ መሥዋዕት ይሠዉ ዘንድ፥'),
  ('25196023-90d2-5a8e-af50-21008721102c', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 9, 16, 'ለሚያስፈልጋቸው ሁሉ፥ ከባልንጀራህ ጋር ታደርገው ዘንድ የምትወደውን ሁሉ በዚህ ወርቅና ብር እንደ አምላክህ ፈቃድ አድርግ።'),
  ('9d279fa0-6f92-55ef-acdd-3d801e189199', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 10, 17, 'በኢየሩሳሌም ላለ ለአምላክህ ቤተ መቅደስ ግዳጅ የሚሆነውን ንዋያተ ቅድሳት።'),
  ('7f4ed5fe-30cc-5fc0-abb4-7fa9dc527a2e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 11, 18, 'ለአምላክህ ቤተ መቅደስ ግዳጅ የምትሻው ሌላም ቢኖር ከንጉሡ ዕቃ ቤት እሰጣለሁ።'),
  ('fa8cdcb2-b39e-5e16-aaeb-8cacf601981f', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 12, 19, '“እኔ ንጉሥ አርጤክስስ የልዑል እግዚአብሔርን ሕግ የሚጽፍ ካህኑ ዕዝራ የሚጠይቀውን ሁሉ በሶርያና በፊንቂስ ካለው ዕቃ ቤት እንዲሰጡት አዘዝሁ። ስጡ፤ እንቢም አትበሉ።'),
  ('c61e44d0-d12e-5342-af5d-1cbdeebb9918', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 13, 20, 'እስከ መቶ መክሊት ብር፥ ዳግመኛም እስከ መቶ የቆሮስ መስፈሪያ ስንዴ፥ እስከ መቶም የኔባል መስፈሪያ ወይን፥ ብዙ ጨውም ቢሆን ስጡ።'),
  ('1e76cfdc-4ab1-5640-a39f-03e2541dbcd4', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 14, 21, 'በንጉሥ መንግሥትና በልጆቹ ላይ መከራ እንዳይመጣ በልዑል እግዚአብሔር ሕግ ይሥሩ።'),
  ('9c9b791f-043d-5d89-a860-4f883775d75e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 15, 22, 'ከካህናቱና ከሌዋውያኑ፥ ከመዘምራኑና ከበረኞቹ ግብር አትቀበሉ። ከቤተ መቅደስም አገልጋዮች፥ ተቀጥረው ቤተ መቅደስን ከሚያገለግሉ ሁሉ ምንም አትቀበሉ፥ አትግዟቸውም።'),
  ('feae95d8-7a26-5c40-ab56-e3df73481b80', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 16, 23, '“አንተም ዕዝራ! እግዚአብሔር በገለጠልህ ጥበብ የአምላክን ሕግ ከሚያውቁ ወገኖች ውስጥ ሶርያንና ፊንቂስን የሚገዙ መኳንንቱንና መሳፍንቱን ሹም፤ የእግዚአብሔርን ሕግ የማያውቁትንም አስተምራቸው።'),
  ('618823cc-96cb-5d37-a8db-e59c513487f6', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '1be1aa21-07c7-5be4-a264-fe55939f9e0a', 17, 24, 'የአምላክህን ሕግና የንጉሡን ትእዛዝ የሚተላለፈውንም ሁሉ ቸል አትበሉ፤ ቅጡ፤ በሞትም ቢሆን፥ በግርፋትም ቢሆን፥ በባርነትም ቢሆን፥ በመውረስም ቢሆን፥ ሁሉንም በየኀጢአቱ ቅጡት።”'),
  ('a3e4bc6f-cf0e-5a36-a60a-b64af8a512d8', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '810640d2-adbb-539e-aaca-b0b07f7d406a', 1, 25, 'ዕዝራም እንዲህ አለ፥ “በኢየሩሳሌም ያለውን የእግዚአብሔርን ቤት ያከብር ዘንድ ይህን ነገር በንጉሥ ልብ ያሳደረ እግዚአብሔር ይመስገን።'),
  ('963f184e-e17c-5964-a9fb-0d4ef917d0cb', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '810640d2-adbb-539e-aaca-b0b07f7d406a', 2, 26, 'በነገሥታቱና በአማካሪዎቹ፥ በወዳጆቹና በመኳንንቱ ሁሉ ፊት እኔን አክብሮኛልና።'),
  ('60c6aaf7-b4a7-5e04-a22c-8a5896af54df', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '810640d2-adbb-539e-aaca-b0b07f7d406a', 3, 27, 'ከዚህም በኋላ በፈጣሪዬ በእግዚአብሔር ጸጋ ታመንሁ። ከእኔም ጋር ይወጡ ዘንድ ከእስራኤል ሰዎችን ወሰድሁ።”'),
  ('78cb295f-1195-54b6-a528-3aba3cac7756', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 1, 28, 'በንጉሡ በአርጤክስስ መንግሥት በየሀገራቸውና በየአውራጃቸው ግዛት ከእኔ ጋር ከባቢሎን የወጡ አለቆችም እነዚህ ናቸው።'),
  ('48b574c3-4ff7-5c8d-a6b0-6a1172d7eb46', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 2, 29, 'ከፎሮስ ልጆች ጣስጣሞስ፥ ከኢዮጥማሩም ልጆች ጋሜሎስ፥ ከዳዊትም ልጆች የሴኬንያስ ልጅ አጡስ፥'),
  ('32164b5d-7902-56de-ae8d-45f30c43effb', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 3, 30, 'ከፋሬስም ልጆች ዘካርያስ፥ ከእርሱም ጋር መቶ አምሳ ሰዎች ተቈጠሩ።'),
  ('4bcd64fb-3862-5908-ae57-1cc1fdd70b36', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 4, 31, 'ከፎአት ሞዓብም ልጆች የዛርያ ልጅ ኤሊዎንያ፥ ከእርሱም ጋር ሁለት መቶ ሰዎች።'),
  ('cecde9c0-9139-5fae-a373-dbef36565bee', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 5, 32, 'ከዘቶይስም ልጆች የኢያሐቲሉ ልጅ ኢያኬንያስ፥ ከእርሱም ጋር ሁለት መቶ ሰዎች፥ ከአዲኑ ልጆች የዮናታን ልጅ ኦቤድ፥ ከእርሱም ጋር ሁለት መቶ አምሳ ሰዎች።'),
  ('cbc30f26-6af7-5091-a1a5-3188ce7de39d', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 6, 33, 'ከኤላም ልጆች የጎቶልያ ልጅ ኢሴይ፥ ከእርሱም ጋር ሰባ ሰዎች።'),
  ('36b76531-e42d-5e45-a707-2984244a192b', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 7, 34, 'ከሳፋጢ ልጆች የሚካኤል ልጅ ዛርያስ፥ ከእርሱም ጋር ሰባ ሰዎች።'),
  ('03c79bec-0c46-52cf-a72d-c8488a71e3ae', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 8, 35, 'ከኢዮአብም ልጆች የኢዝኤል ልጅ ኦባድያ፥ ከእርሱም ጋር ሁለት መቶ ዐሥራ ሁለት ሰዎች።'),
  ('fa12c697-324b-5f0b-a33b-f867ecf4ab82', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 9, 36, 'ከባኒ ልጆችም የኢዮሳፌይ ልጅ አስሊሞት፥ ከእርሱም ጋር መቶ ስድሳ ሰዎች።'),
  ('1c6acece-cbc5-535c-a0ab-3f304082b375', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 10, 37, 'ከቤዔር ልጆችም የባቢ ልጅ ዘካርያስ፥ ከርሱም ጋር ሃያ ስምንት ሰዎች።'),
  ('388a2520-9a06-5faf-a66f-e9182f8c071d', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 11, 38, 'ከአሰጣያትም ልጆች የአዝጋድ ልጅ ዮሐንስ፥ ከርሱም ጋር መቶ ዐሥር ሰዎች።'),
  ('5c1d81c2-eeea-52ad-a377-ed6ae27974f4', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 12, 39, 'ከአዶኒቃም ልጆች የቀሩት ሁሉ ስማቸው ይህ ነው፦ ኤሊፋሊ፥ ይዑኤል፥ ሰሚያስ፥ ከእነርሱም ጋራ ሰባ ሰዎች።'),
  ('e9c94bf9-abd7-505f-a2e0-ff0fdacdfe06', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'a1df647c-9af5-58f5-abee-ca5d888c1b61', 13, 40, 'ከቤኑስም ልጆች የአስጣስቆሩ ልጅ ዑታይ ከእርሱም ጋራ ሰባ ሰዎች ተቈጠሩ።'),
  ('06656647-ac01-54a3-aaaf-ba8d18882f4f', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'f9d4f0fd-bc09-5a49-a386-e6284537c8f1', 1, 41, 'ቴራን ወደሚባል ወንዝም ሰበሰብኋቸው፤ በዚያም ሦስት ቀን አደርን፤ አስቈጠርኋቸውም።'),
  ('c48e2574-91ad-5126-a145-2f1238d282f4', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'f9d4f0fd-bc09-5a49-a386-e6284537c8f1', 2, 42, 'ከውስጣቸውም ካህናትንና ሌዋውያንን አላገኘንም።'),
  ('7463594f-73f0-5742-a561-6de4869993a7', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'f9d4f0fd-bc09-5a49-a386-e6284537c8f1', 3, 43, 'ወደ አልዓዛርም ላክሁ፤ ከእኔም ጋር መአስመንን፥ አንዐጣንን፥ ሰምያስን፥ ኢዮሪቦን፥ ናታንን፥ አርጦንን፥ ዘካርያስን፥ ሞሱላሞስን ወሰድሁ።'),
  ('b72fd28d-f7c5-5340-a12a-9e87b6b0f5e9', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'f9d4f0fd-bc09-5a49-a386-e6284537c8f1', 4, 44, 'ከእነርሱም ጋር ከመሳፍንቶቻቸውና ከዐዋቂዎቻቸው ወሰድሁ።'),
  ('891a516e-a88a-5975-aaa6-53ce8971599c', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'f9d4f0fd-bc09-5a49-a386-e6284537c8f1', 5, 45, 'ወደ ዕቃ ቤቱም ሹም ወደ ያድዮን ይሄዱ ዘንድ ነገርኋቸው።'),
  ('9db0b3e4-d9d6-55b6-af97-a66184c558ec', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'f9d4f0fd-bc09-5a49-a386-e6284537c8f1', 6, 46, 'ለእግዚአብሔርም ቤት ካህናትን እንዲልኩልን ለያድዮንና ለወንድሞቹ፥ በዚያም ቦታ ለአሉ ሰዎች ይነግሯቸው ዘንድ አዘዝኋቸው።'),
  ('8b9250b3-d68d-55f3-a784-3e5c8bfbbe9e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'f9d4f0fd-bc09-5a49-a386-e6284537c8f1', 7, 47, 'ከእስራኤል ልጅ ከሌዊ ልጅ ከሞሐሊ ልጆች ጠቢባን ሰዎችን አሲብያንና ልጆቹን፥ ዐሥራ ስምንት ወንድሞቹንም አመጡልን፥'),
  ('f1dc038c-bea9-54c7-a80e-c30e226f3aaf', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'f9d4f0fd-bc09-5a49-a386-e6284537c8f1', 8, 48, 'ከከዓኑ ልጆችና ከልጆቻቸውም ውስጥ የሆኑ ሃያ ሰዎች፥'),
  ('95c478ee-0d58-5ddc-a169-a65ee4665a1a', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'f9d4f0fd-bc09-5a49-a386-e6284537c8f1', 9, 49, 'ዳዊት የሠራቸው የቤተ መቅደስ አገልጋዮችና አለቆቻቸው ለሌዋውያን ሥራ የተጨመሩ የካህናት ልጆች ሁለት መቶ ሃያ ናቸው፤ የሁሉም ስማቸው ተጻፈ።'),
  ('3628645b-b73d-5fc1-a8af-f584f94e6d69', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'e28ff33e-a58f-5943-abdc-48cd48096e0a', 1, 50, 'በአምላካችን በእግዚአብሔርም ፊት ከልጆቻችን ጋራ በዚያ እንጾም ዘንድ ለልጆቻችንና ለከብቶቻችንም ይቅርታን እንለምን ዘንድ ተሳልን።'),
  ('76f1a15c-5985-5469-a44a-91cc0a06f88f', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'e28ff33e-a58f-5943-abdc-48cd48096e0a', 2, 51, 'ሀገራችንን የሚያጸኑና ከጠላቶቻችን ጋራ የሚመካከቱ እግረኞችንና ፈረሰኞችን እንዲሰጠን ለንጉሡ እልክ ዘንድ አፍሬአለሁና።'),
  ('819f19e6-d353-53eb-acd5-3d253a5d5dbf', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'e28ff33e-a58f-5943-abdc-48cd48096e0a', 3, 52, 'ሥራውን ሁሉ ያቀናላቸው ዘንድ ከሚፈልጉት ሰዎች ጋራ የጌታችን ከሃሊነት እንደሚኖር ለንጉሡ ነግረነው ነበርና።'),
  ('b825dc7a-ed2b-553c-af2d-2154064ea11e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'e28ff33e-a58f-5943-abdc-48cd48096e0a', 4, 53, 'ዳግመኛም ስለዚህ ሁሉ ወደ እግዚአብሔር ለመን፤ እርሱም ይቅር አለን።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('9a3321df-5207-531d-a100-c2d7b855dcc8', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'd7cabc9f-204c-5481-af81-56a7b98d4ccd', 1, 54, 'ከሕዝቡና ከካህናቱ ሹሞች ዐሥራ ሁለቱን ሰዎች፥ ኤሴርያንና አሴሚያን፥ ከእነርሱም ጋር ከወንድሞቻቸው መካከል ዐሥር ሰዎችን ለየሁ።'),
  ('8817a361-11c3-5ee3-a48a-7f300f52b7cb', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'd7cabc9f-204c-5481-af81-56a7b98d4ccd', 2, 55, 'ንጉሡና መኳንንቱ፥ አማካሪዎቹም እስራኤልም ሁሉ የሰጡንን ወርቁንና ብሩን የእግዚአብሔርንም ቤት ንዋየ ቅድሳት መዝኜ ሰጠኋቸው።'),
  ('d03f206d-1c55-5f93-a63b-30a1685e203e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'd7cabc9f-204c-5481-af81-56a7b98d4ccd', 3, 56, 'ስድስት መቶ አምሳ መክሊት ብርም መዝኜ ሰጠኋቸው።'),
  ('f73bc322-64f9-514a-afd9-8a0702bc7f5c', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'd7cabc9f-204c-5481-af81-56a7b98d4ccd', 4, 57, 'መቶ መክሊት የብር ዕቃ፥ መቶ መክሊትም ወርቅ፥ ሃያ መክሊትም የወርቅ ዕቃ፥ የሚወደድ እንደ ወርቅም የጠራና የጠነከረ ዐሥራ ሁለት የናስ ዕቃ መዝኜ ሰጠኋቸው።'),
  ('a45e0f73-9fb2-5ef4-a689-5d648af80bfc', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'd7cabc9f-204c-5481-af81-56a7b98d4ccd', 5, 58, 'እንዲህም አልኋቸው፥ “እናንተም ለእግዚአብሔር ተለዩ፥ ለአባቶቻችን ፈጣሪ ለእግዚአብሔር ስእለት የሆነውን የብሩንና የወርቁን ንዋየ ቅድሳትም ለዩ።'),
  ('467fa658-9e96-5a47-a3bf-1c6ba15dfa24', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'd7cabc9f-204c-5481-af81-56a7b98d4ccd', 6, 59, 'ለመሳፍንቱና ለመኳንንቱ፥ ለካህናቱ አለቆችና ለሌዋውያኑ፥ ለእስራኤልም ሀገሮች አለቆች በኢየሩሳሌም በአምላካችን ቤት አዳራሽ ውስጥ እስክትሰጧቸው ድረስ ተግታችሁ ጠብቁ።”'),
  ('1b800587-8d1a-5a58-afdd-e41b703b22ce', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'd7cabc9f-204c-5481-af81-56a7b98d4ccd', 7, 60, 'ካህናቱና ሌዋውያኑም የተቀበሉትን ወርቁንና ብሩን፥ የኢየሩሳሌምንም ንዋየ ቅድሳት ወደ እግዚአብሔር ቤተ መቅደስ አገቡ።'),
  ('009dd7b7-4fb7-5575-af20-73f4b308908f', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '30ffe240-8cc8-584e-ae26-5699d0224943', 1, 61, 'በመጀመሪያው ወር በዐሥራ ሁለተኛው ቀን ቴራን ከሚባል ሀገር ተነሡ፤ ከጠላቶቻችን ሁሉ ባዳነን፥ በፈጣሪያችን ከእኛ ጋር ባለች ጽንዕት እጅም ወደ ኢየሩሳሌም ደረሱ።'),
  ('b1e1555e-260d-5c3d-a743-dfada465fa4d', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '30ffe240-8cc8-584e-ae26-5699d0224943', 2, 62, 'በደረሱ በሦስተኛውም ቀን ወርቁንና ብሩን መዝነውና ቈጥረው በቤተ እግዚአብሔር ለኦርያ ልጅ ለካህኑ ለመርሞቲዮራ ሰጡት።'),
  ('441a4ea1-b00f-5eab-abe0-0efbed39e8d4', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '30ffe240-8cc8-584e-ae26-5699d0224943', 3, 63, 'የሁሉም ልኩ፥ ሚዛኑም ያንጊዜ ተጻፈ።'),
  ('4be8172d-9dad-57c0-acfd-c7b51f4c0ffb', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '30ffe240-8cc8-584e-ae26-5699d0224943', 4, 64, 'ከእርሱም ጋር የፊንሐስ ልጅ አልዓዛር ነበረ፤ ከእነርሱም ጋር ሌዋውያኑ የኢያሱ ልጅ የዘባትና የብኑ ልጅ ሞኢተስ ነበሩ።'),
  ('5dffcde0-6904-513d-a404-8f525bdf2073', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '30ffe240-8cc8-584e-ae26-5699d0224943', 5, 65, 'ከምርኮ የተመለሱትም ለእስራኤል አምላክ ለእግዚአብሔር መሥዋዕት አቀረቡ። ዐሥራ ሁለት ኮርማዎችን፥ ዘጠና ስድስት በጎችን፥'),
  ('4138ff6c-d4c3-51f7-a668-7af9ed38d8ab', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '30ffe240-8cc8-584e-ae26-5699d0224943', 6, 66, 'ስለ ድኅነትም ሰባ ስድስት ሙክቶችን፥ ዐሥራ ሁለት የበግ ጠቦቶችን፥ ሁሉንም ለእግዚአብሔር ሰዉ።'),
  ('b9398bc9-9a55-57a9-a376-b9e5dbdab14f', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', '30ffe240-8cc8-584e-ae26-5699d0224943', 7, 67, 'ከዚህም በኋላ ለንጉሡ ዕቃ ቤት ሹሞች፥ ለሶርያና ለፊንቂ ገዦችም ከንጉሡ የመጣውን ደብዳቤ ሰጧቸው፤ ሕዝቡንና የእግዚአብሔርንም መቅደስ አከበሩ።'),
  ('3688af90-4e22-5026-a023-1f73d5268bac', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 1, 68, 'ከዚህም በኋላ ሹሞች መጥተው የሠሩትን ነገሩኝ።'),
  ('86b1427f-53bb-5cc1-a88a-4b4f671e7bce', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 2, 69, 'እንዲህም አሉኝ፥ “የእስራኤል ወገኖች፥ መኳንንቶቻቸውም፥ ካህኖቻቸውም፥ ሌዋውያኑም ከሌሎች የምድር አሕዛብ ከከናኔዎን፥ ከፌሬዜዎን፥ ከኬጤዎንም፥ ከኢያቡሴዎን፥ ከሞዓባውያን፥ ከግብፃውያንና ከኤዶሜዎን ርኵሰት አልተለዩም።'),
  ('c516444f-7930-5e49-a5d9-b20ef5ba8334', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 3, 70, 'ሴቶች ልጆቻቸውን አገቡ፤ እነርሱና ልጆቻቸውም የከበረውን ዘር ከባዕዳን የምድር አሕዛብ ጋር ቀላቀሉ፤ መሳፍንቶቻቸውና መኳንንቶቻቸውም ከመጀመሪያው ሥራቸው ጀምሮ በዚያች ኀጢአት አንድ ሆኑ።”'),
  ('7dd08bc3-ace0-5287-adbe-33595c9fafe3', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 4, 71, 'ከዚህም በኋላ ይህን በሰማሁ ጊዜ ልብሴንና ልብሰ ተክህኖዬን ቀደድሁ፤ የራሴን ጠጕርና ጢሜንም ነጨሁ፤ ተክዤና አዝኜም ተቀመጥሁ።'),
  ('3517ae85-cceb-5ff8-af09-a1cb28aee23f', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 5, 72, 'እኔም በዚያች ኀጢአት አዝኜና ተክዤ ተቀምጬ ሳለሁ የእስራኤል ፈጣሪ የእግዚአብሔርን ትእዛዝ የሚፈሩ ሁሉ ወደ እኔ ተሰበሰቡ።'),
  ('4920a42a-eac8-5496-a33b-d8f3bbca5dc8', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 6, 73, 'ከዚህም በኋላ በሠርኩ መሥዋዕት ጊዜ ጾመኛ እንደ ሆንሁ ልብሴና የክህነት ልብሴ እንደ ተቀደደ ሆኖ ተነሣሁ፤ በጉልበቴም ተንበረከክሁ፤ እጆችንም ወደ እግዚአብሔር ዘረጋሁ።'),
  ('662eea0e-433d-5a11-a614-279322ef3951', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 7, 74, 'እንዲህም አልሁ፥ “አቤቱ ጌታዬ ከፊትህ የተነሣ አፍራለሁ፤ እፈራለሁም።'),
  ('c3be9779-ac22-59c9-a965-cc183b4c4280', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 8, 75, 'ኀጢአታችን በዝትዋልና፥ ከራሳችንም ከፍ ከፍ ብሏልና፥ አለማወቃችንም እስከ ሰማይ ደርሷልና።'),
  ('43eeced9-ddba-5963-aff0-7af060acd925', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 9, 76, 'ከአባቶቻችን ዘመን ጀምሮ እስከ ዛሬ ድረስ በታላቅ ኀጢአት ላይ ኖረናል።'),
  ('2cf142b3-3c7c-53d0-a9e5-c1c564f07bb0', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 10, 77, 'በእኛ ኀጢአትና በአባቶቻችንም ኀጢአት የምድር ነገሥታት ከወንድሞቻችንና ከንጉሦቻችን፥ ከካህኖቻችንም ጋር ማረኩን፤ በጦራቸውም ዘረፉን፤ እስከ ዛሬም ድረስ አፈርን።'),
  ('5ad771d2-6845-5780-ae8c-90b69e45045b', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 11, 78, 'አሁን ግን በዚያች በተቀደሰችው ቦታህ ሥርንና ስምን ትተውልን ዘንድ እግዚአብሔር ሆይ ቸርነትህ በእኛ ላይ በዝታ ተደረገችልን።'),
  ('2b45c78d-9031-50e0-a5d5-104c8c707972', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 12, 79, 'በአንተም በአምላካችን ቤት ብርሃን ተገለጠልን፤ ተገዥዎችም በሆንን ጊዜ ምግባችንን ሰጠኸን።'),
  ('df27f8f5-f7e2-5596-ae74-6a22acf926c8', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 13, 80, 'በተገዛንም ጊዜ አንተ አምላካችን አልተውኸንም፤ በፋርስ ነገሥታትም ፊት ሞገስን ሰጠኸን፤ ምግባችንን ይሰጡን ዘንድ፥'),
  ('aa48016f-ec9f-5a96-a273-77dafba9bc27', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 14, 81, 'ቤተ መቅደሳችንንም ያከብሩ ዘንድ፥ የጽዮንንም ፍራሿን ይሠሩ ዘንድ፥ በይሁዳና በኢየሩሳሌምም ኀይልን ይሰጡን ዘንድ አልተውኸንም።'),
  ('39604ae7-1b97-543f-ae51-51cd542ce2d8', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 15, 82, '“አቤቱ፥ አሁንስ ይህ በእኛ ላይ ሳለ ምን እንላለን? በባሮችህ በነቢያትም እጅ እንዲህ ስትል የሰጠኸውን ትእዛዝህን ካድን።'),
  ('f87edb1e-5f0b-5abf-a6f1-fcb9e4c43621', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 16, 83, 'ትወርሷት ዘንድ ወደ እርሷ ትገባላችሁ ያልሃቸው ያች ምድር በምድር አሕዛብ ርኵሰት የተዳደፈች ምድር ናት፤ ርኵሰታቸውንም መሏት።'),
  ('401190af-8f67-5d39-a365-9ec67f98b98e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 17, 84, 'ሴቶች ልጆቻችሁን ለወንዶች ልጆቻቸው አታጋቡ፤ ሴቶች ልጆቻቸውንም ለወንዶች ልጆቻችሁ አታጋቡ፤'),
  ('a6e1eb75-ba20-5c8f-ae46-9fb93566d20e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 18, 85, 'ድል ትነሷቸው ዘንድ፥ የምድርንም በረከት ትበሉ ዘንድ፥ ለልጆቻችሁ ለዘለዓለሙ ታወርሷት ዘንድ በዘመናችሁ ሁሉ ከእነርሱ ጋር አትስማሙ።'),
  ('900a6b6b-0679-5d48-ac33-4a10135c2ae8', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 19, 86, 'ይህችም ያገኘችን ሁሉ ስለ ሥራችን ክፋትና ስለ ኀጢአታችን ብዛት ነው።'),
  ('e8c3bff2-544e-5f16-ae4f-c3c58230a8d6', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 20, 87, 'አቤቱ አንተ ግን ኀጢአታችንን ታገሥህ፤ እንመለስም ዘንድ ሥርን ሰጠኸን፤ ዳግመኛም ሕግህን አፍርሰን ከምድር አሕዛብ ርኩሰት ጋር አንድ እንሆን ዘንድ ይገባናልን?'),
  ('2e97c419-6c84-532c-a888-d17172783f79', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 21, 88, 'ብትቈጣንስ ሥርንና ዘርን፥ ስማችንንም እስከማታስቀር ድረስ ባጠፋኸን ነበር።'),
  ('393c524f-1d08-5c7b-ae4c-0ced617065dc', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 22, 89, 'አቤቱ የእስራኤል አምላክ አንተ፥ እውነተኛ ነህ፥ ዛሬ ሥርን ትተህልናልና።'),
  ('7958f0b7-c5a4-5310-ad34-9ee88fe1363e', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 23, 90, 'አሁንም በፊትህ በኀጢአታችን አለን። ስለዚህ በፊትህ እንቆም ዘንድ አይገባንም።”'),
  ('be1b16bf-141a-5019-af19-18402cc20ae0', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 24, 91, 'ዕዝራም በቤተ መቅደሱ አንጻር ተንበርክኮ እያለቀሰ በጸለየና በተናዘዘ ጊዜ በኢየሩሳሌም ያሉ ብዙ ሰዎች ሴቶችና ወንዶች፥ ቆነጃጅቱም ወደ እርሱ ተሰበሰቡ፤ በሁሉም ላይ ታላቅ ልቅሶ ሆነ።'),
  ('37c931db-1e8d-5612-a03b-a5b80432ac13', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 25, 92, 'ከእስራኤልም ልጆች ውስጥ የኢያኤል ልጅ ኢኮንያስ ዕዝራን ጠርቶ እንዲህ አለው፥ “ልዩ ከሚሆኑ ከምድር አሕዛብ ወገን ሚስት ያገባን እኛ እግዚአብሔርን በድለናል፤ አሁንም ይህ ሁሉ በእስራኤል ዘንድ አለ።'),
  ('679ab8a5-e8d1-5a28-acf6-7a50e2fc0b48', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 26, 93, 'ነገር ግን እንደ ፍርድህ ልዩ ከሚሆኑ ከምድር አሕዛብ ወገን ያገባናቸውን ሚስቶቻችንን ሁሉ ከልጆቻቸው ጋራ ከእኛ እናስወጣቸው ዘንድ በእግዚአብሔር ስም እንማማል።'),
  ('664a6acc-07e7-5d10-aa73-842566d88c57', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 27, 94, 'የእግዚአብሔርን ሕግ የሚወዱ ሰዎችንም ሁሉ ተነሥተህ አምላቸው።'),
  ('edbe6689-b20a-53af-a83a-cecb19a16683', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 28, 95, 'ይህ ሥራ ባንተ ላይ ነውና፥ እኛም ካንተ ጋር ነንና፥ እንረዳሃለንምና።”'),
  ('c4eb3c43-5dde-596f-a34e-499cb1b5e4f7', 'e352261f-77e7-54ba-aeeb-ef6fcd586791', 'ff65f92a-8ece-52df-ad36-f66d07034287', 29, 96, 'ዕዝራም ተነሥቶ የሕዝቡን ሹሞችና ካህናቱን፥ ሌዋውያኑንም፥ እስራኤልንም ሁሉ እንዲሁ ያደርጉ ዘንድ አማላቸው፤ እነርሱም ማሉ።'),
  ('829ac20f-3a02-5145-a1d0-40026f0f12ea', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 1, 1, 'ዕዝራም ከቤተ መቅደሱ አደባባይ ተነሥቶ ወደ ናሴሩ ልጅ ወደ ዮሐናን ቤት ሄደ።'),
  ('ef0b9476-b8b3-55f0-a3ca-8bb6f3ffda3e', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 2, 2, 'በዚያም ተቀምጦ ስለ ታላላቆችና ብዙዎች ኀጢአቶቻቸው እያለቀሰ እህልን አልበላም፤ ውኃንም አልጠጣም።'),
  ('8f0c7803-bc50-5a4b-a3a5-f7fab89351de', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 3, 3, 'ከዚህ በኋላ ከምርኮ ለተመለሱ ሁሉ በኢየሩሳሌም ይገኙ ዘንድ፥'),
  ('813862f0-1514-533d-ae96-1c8e3283cad3', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 4, 4, 'እስከ ሁለትና እስከ ሦስት ቀን ድረስ ያልተገኙና ያልደረሱ ሁሉ እንደ ሥርዐታቸው በአለቆቻቸው ቅጣት ይቀጡ ዘንድ፥ ከብቶቻቸውም ይወረሱ ዘንድ፥ እነርሱም ከወገኖቻቸው ይለዩ ዘንድ በይሁዳና በኢየሩሳሌም ዐዋጅ ነገረላቸው።'),
  ('cf4dc766-caa1-5b6d-a557-5a07f4609ef4', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 5, 5, 'የይሁዳና የብንያም ወገኖችም በዘጠነኛው ወር በሃያኛው ቀን በሦስት ቀን ውስጥ በኢየሩሳሌም ተሰበሰቡ።'),
  ('06ec53dd-ef77-5398-aa18-886e21b458f3', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 6, 6, 'ሁሉም በቤተ መቅደሱ አደባባይ ተቀመጡ፤ ክረምት ነበርና ስለ ውርጩ ጽናት ይንቀጠቀጡ ነበር።'),
  ('66f7f1c6-c3b1-5227-a0f6-2c79c9c612b5', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 7, 7, 'ዕዝራም ተነሥቶ እንዲህ አላቸው፥ “ከአሕዛብ ወገን ሚስት ያገባችሁ እናንተ በደላችሁ፤ በእስራኤልም ላይ ኀጢአትን ጨመራችሁ።'),
  ('ca0aa811-908a-5130-a3a9-aae2f5617999', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 8, 8, 'አሁንም ለእግዚአብሔር ተናዘዙ፤ የአባቶቻችንንም አምላክ አመስግኑት።'),
  ('ae4995c7-6a11-5e74-a38d-657324c0301b', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 9, 9, 'ፈቃዱንም ፈጽሙ፤ ከምድር አሕዛብና ከባዕዳት ሚስቶቻችሁም ተለዩ።”'),
  ('5ae701c8-e80c-5f36-a57c-650fce11fc10', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 10, 10, 'ሁሉም በሙሉ በታላቅ ድምፅ ጮኸው እንዲህ አሉት፥ “እሺ አንተ እንዳዘዝኸን እናደርጋለን።'),
  ('87e56999-9fe2-5cab-a543-a2a9580a9e4e', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 11, 11, 'ነገር ግን ሰዉ ብዙ ነው፤ ጊዜውም ክረምት ነው፤ ፈጥነንም እናደርገው ዘንድ አንችልም፤ ሥራውም የአንድ ቀን ወይም የሁለት ቀን ሥራ አይደለም፤ በዚህ ፈጽመን በድለናልና።'),
  ('ca651b4d-6fc6-5153-ab2c-40cc24689ea7', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 12, 12, 'አሁንም ከልዩ ወገን ሚስት ያገቡ መሳፍንት ሁሉና መንደረተኞችም ተሰብስበው ይምጡ።'),
  ('bfc98d91-f1fb-5b75-aa8d-4f79b688280f', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 13, 13, 'በዚህ ሥራ ያገኘን የእግዚአብሔር ቍጣ ከእኛ ይርቅ ዘንድ መንደረተኞቻቸውንና ሽማግሌዎቻቸውን፥ አለቆቻቸውንም ይቅጠሯቸው።”'),
  ('93dd8857-f394-50d8-ac02-36feb7d259f2', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 14, 14, 'የአዛሄል ልጅ ዮናታን፥ የታቃኑ ልጅ ኢያዝያስም መጡ፤ ሞሶላሞስ፥ ሌዊ፥ ሳባጢዎስ፥ እነርሱም እንዲህ ተባበሩ።'),
  ('51ee83fa-936b-5b19-a80d-33adfa27aaec', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 15, 15, 'ከምርኮ የተመለሱትም ሁሉ እንዲሁ አደረጉ።'),
  ('af38e4fd-a020-56f5-a725-26cdce98b571', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 16, 16, 'ካህኑ ዕዝራም ካገሮቻቸው ሽማግሌዎች፥ በያገራቸውም ከሚኖሩት ሁሉ ስማቸው ልዩ ልዩ የሆነ ሰዎችን መረጠ፤ እንዲህም ያደርጉ ዘንድ እስከ ዐሥረኛው ወር መባቻ ድረስ ተቃጠሩ።'),
  ('db00d913-2f31-5489-a2c9-2f40389fdc88', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 17, 17, 'ከልዩ ወገን ሚስት ያገቡ እነዚያም ሰዎች ሁሉ “እስከ መጀመሪያው ወር መባቻ እንፈታለን” ብለው ነገራቸውን ጨረሱ።'),
  ('4efb18eb-4124-5ad6-a3fa-268c807c09bd', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 18, 18, 'ከካህናቱም ውስጥ ከባዕድ ወገን ሚስት ያገቡ ተገኙ።'),
  ('8d25149c-2c31-53dc-a273-fc898e488091', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 19, 19, 'እነርሱም የኢዮሴዴቅ ልጅ የኢያሱ ልጆችና ወንድሞቹ፥ ማቴላስ፥ አልዓዛር፥ ዮሬቦስና ዮአዳኖስም ናቸው።'),
  ('f0f7f15e-6189-54b4-aad9-22e789254a7f', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 20, 20, 'ሚስቶቻቸውንም ፈትተው ስለ ኀጢአታቸው መሥዋዕት ይሠዉ ዘንድ ጀመሩ።'),
  ('ec1620f9-9a56-549b-a4f6-2badf436c392', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 21, 21, 'ከኤሞርም ልጆች ሐናንያ፥ ዘብዴዎስ፥ ሜኑስ፥ ሴሜዎስ፥ ኢያርማየልና አዛርያ ናቸው።'),
  ('0233efab-d4ac-50e6-a401-22bd298bb8bc', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 22, 22, 'ከፌትርኤልም ልጆች ኢልዮኒስ፥ ማስያስ፥ አስማኤሎስ፥ ናትናአሎስ፥ ዎቅዲሎስና አልታሳ ናቸው።'),
  ('491a09db-4618-57ca-ad0e-57deda355770', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 23, 23, 'ከሌዋውያንም ወገን ዮዛባዶስ፥ ሳምያስ፥ ቃሊጣስ የሚሉት ቆዮስ፥ ፋትያስ፥ ይሁዳና ዮናስ ናቸው።'),
  ('be932301-bc20-5d92-a604-8e83d12bb708', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 24, 24, 'ከመዘምራንም ወገን ኤልያሳቦስና ባካሮስ ናቸው።'),
  ('0e8c495e-18ac-591b-aad9-80963aedab3b', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 25, 25, 'ከበረኞችም ወገን ሴሎምና ጦልባኒስ ናቸው።'),
  ('8c12a0ca-a5ee-5e15-a15a-d480f3c4b550', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 26, 26, 'ከእስራኤል ከፎሮስ ልጆች ወገንም ኢየርማስ፥ ኤዝያስ፥ ሚልክያስ፥ ሚያኤሎስ፥ አልዓዛር፥ አስብያስ፥ ባኒያስ ናቸው።'),
  ('d62fc70f-1f89-558e-a706-08634fa82945', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 27, 27, 'ከኤላ ልጆች ወገን ማጣንያስ፥ ዘካርያስ፥ ኢያዚሬሎስ፥ አብድዮስ፥ ኢያሬሞትና ኤዲያስ ናቸው።'),
  ('df83e26c-e9ed-564a-a098-e2b764630c8e', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 28, 28, 'ከዛሞትም ልጆች ወገን ኤሊያዳስ፥ ኤሊያሲሞስ፥ ኦቶንያስ፥ ኢያሪሞስ፥ ሳባቶስ፥ ዘራሊያስ ናቸው።'),
  ('91db20dd-1c8b-5868-a700-b8c84906cf21', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 29, 29, 'ከቤባይም ልጆች ወገን ዮሐንስ፥ ሐናንያ፥ ዮዛብዴዎስ፥ አሜቴዎስ ናቸው።'),
  ('47c22e46-0e16-5401-a616-a64f9264b57f', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 30, 30, 'ከማኒ ልጆችም ወገን ኦላሞስ፥ ማምኮስ፥ ኢያዴዎስ፥ ኢያሶቦስ፥ አስሔሎስ፥ ኢያርሞት ናቸው።'),
  ('ef888f7e-f36b-521b-a5de-ea2968dec388', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 31, 31, 'ከዓዲ ልጆችም ናሐቶስ፥ ሞሐስያስ፥ ለቁናስ፥ ኒዶስ፥ ቢስቀስ-ጰስሚስ ሲአቱል ባልኑስ፥ ሜናስያስ ናቸው፥'),
  ('55f07063-0b19-52a5-ad92-28e913d61574', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 32, 32, 'ከሐናንያ ልጆችም ኢሊዮሳስ፥ አስያስ፥ ሚልክያስ፥ ስብያስ፥ ስምዖን፥ ኮሳሜዎስ ናቸው።'),
  ('8fb8b835-9753-5482-a3cb-7f562baa85ff', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 33, 33, 'ከአሶም ልጆችም መልጠኒዎስ፥ መጣቲያስ፥ ሳባኔዎስ፥ ኤሌፍላት፥ ምናሴ፥ ሴሜይ ናቸው።'),
  ('e18e0972-b3cf-5e4d-adb9-195d798fa5f1', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 34, 34, 'ከባኒ ልጆችም ኤርምያስ፥ ሞምዲስ፥ ስማኤል፥ ኢዮኤል፥ መምዲ፥ ጴዴያስ፥ አናስ፥ ቀሪባሶን፥ አናሲቦስ፥ መንጠኒሞስ፥ አልያሲስ፥ በኑስ፥ ኤልያሊ፥ ሰማይስ፥ ሰላምያስ፥ ናታንያስ ናቸው። ከኤዛርያስ ልጆችም ሴሲስ፥ ኤዝርል፥ አዛኤል፥ ሳማጢስ፥ ዘምበሪ፥ ኢዮሶፎስ ናቸው።'),
  ('36324ebf-1fdb-55af-a00f-a3867437ceb3', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 35, 35, 'ከነሐማ ልጆችም ማዚጢያስ፥ ዘቢዲያስ፥ ኤዴስ፥ ኢዮኤል፥ በኒያስ ናቸው።'),
  ('98c2315b-3da9-5092-a150-84553dc7cd38', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 36, 36, 'ከባዕዳን ከአሕዛብ ወገን ሚስት ያገቡት ሰዎች ሁሉ ሚስቶቻችውን ሁሉ ከልጆቻቸው ጋር አስወጧቸው።'),
  ('8f2002a5-b99c-5d61-a885-090a729decce', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 37, 37, 'ካህናትና ሌዋውያንም፥ ብዙዎች እስራኤልም በሰባተኛው ወር መባቻ በኢየሩሳሌም በያገራቸው ተቀመጡ፤ የእስራኤልም ልጆች በየአውራጃቸው ተመለሱ።'),
  ('e57f688d-02dd-5ea7-ace8-954e2dd5e09e', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 38, 38, 'በቤተ መቅደሱ በር በምሥራቃዊው አደባባይ ሁሉም በአንድነት ተሰበሰቡ።'),
  ('a026e7a2-fafa-5b53-a14d-9fd869c88ba5', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 39, 39, 'ካህኑንና ጸሓፊዉን ዕዝራንም የእስራኤል አምላክ እግዚአብሔር የሰጠውን የሙሴን ሕግ ያመጣ ዘንድ ነገሩት።'),
  ('a40937ae-b972-5ceb-a2e7-120281541580', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 40, 40, 'የካህናት አለቃ ዕዝራም በሰባተኛው ወር መባቻ ለሕዝቡ፥ ለወንዶችም፥ ለሴቶችም ለካህናቱም ሁሉ ሕጉን ይሰሙ ዘንድ አነበበላቸው።'),
  ('e1609b5d-88c8-50c0-a69e-aa4b2dd7cfda', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 41, 41, 'በቤተ መቅደሱም በር ባለው አደባባይ በወንዶቹና በሴቶቹ ፊት ከነግህ ጀምሮ እስከ ቀትር ድረስ አነበበላቸው፤ ሁሉም በፍጹም ልባቸው ሕጉን አደመጡ።'),
  ('d71596b6-4f8b-5d92-a589-d9abbb30d141', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 42, 42, 'ካህኑና የሕጉ ጸሓፊ ዕዝራም ከእንጨት በተሠራ መረባርብ ላይ ቆመ።'),
  ('5a3a49ac-20c4-5cd6-aaee-24fd057c1a1f', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 43, 43, 'ከእርሱም ጋር፦ መተጢያስን፥ ሳሙስን፥ ሐናንያን፥ አዛርያን፥ ኡርያስን፥ ሕዝቅያስን፥ በአልስሞስንም በቀኙ አቆማቸው።'),
  ('f2993db8-efe1-5137-a19b-06b7e6377b2c', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 44, 44, 'በግራውም በኩል ፈሐልዴዎስን፥ ሚሳኤልን፥ ሚልክያስን፥ ሎታሳብስን፥ ናባሪያንና ዘካርያስን አቆመ።'),
  ('b16fd0ee-81fd-5963-a9eb-97033d042667', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 45, 45, 'ዕዝራም ያን መጽሐፍ ይዞ በሕዝቡ ፊት ተቀመጠ፤ ሕዝቡም ሁሉ ያከብሩት ነበር።'),
  ('6c84b8ca-9401-517d-a2b5-3ff295f9e796', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 46, 46, 'የሕጉንም መጽሐፍ በገለጠ ጊዜ ሕዝቡ ሁሉ ተነሥተው ቆሙ፤ አዛርያም ሁሉን የሚገዛ ልዑል እግዚአብሔርን አመሰገነው።'),
  ('028d7475-c386-5121-a415-c6ed630264f8', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 47, 47, 'ሁሉም በሙሉ፥ “አሜን፥ አሜን” ብለው መለሱለት፤ እጆቻቸውንም ወደ ላይ አንሥተው በምድር ወድቀው ለእግዚአብሔር ሰገዱ።'),
  ('ef305dbe-46d8-5076-a293-8e3f848e7efd', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 48, 48, 'ሌዋውያኑም ኢያሱ፥ አኑሲ፥ ሰራቢያስ፥ ኢያዲኖስ፥ ኢያቆብስ፥ ሳብጣያስ፥ አውጥያስ፥ ሚሐና፥ ቀሊጦስ፥ አዛርያ፥ ጠዛብዶስ፥ ሐኒያስ፥ ፈልጣስ የእግዚአብሔርን ሕግ አስተማሯቸው።'),
  ('040d3e05-d0da-593c-a459-b9efec9c947e', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 49, 49, 'ባነበበላቸውም ጊዜ ሁሉም በአንድነት ሆነው ሰሙ።'),
  ('2f96687f-f786-5f8c-abba-0cf1ba176754', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 50, 50, 'አጠራጢም የካህናቱን አለቃና ጸሓፊውን ዕዝራን፥ ለሁሉ የሚያስተምሩ ሌዋውያንንም እንዲህ አላቸው፦'),
  ('f5b2c146-3fb1-5beb-ad2a-e0b1ff8d92ca', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 51, 51, '“ይቺ ቀን ለእግዚአብሔር የተቀደሰች ናት፥” ሁሉም ሕጉን በሰሙ ጊዜ አለቀሱ።'),
  ('8d1fe3a5-d608-5f9a-a19a-770d74b936a9', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 52, 52, 'እንዲህም ተባባሉ፥ “ሂዱና ምሳችሁን ብሉ፤ ጠጡም፤ ለሌላቸውም ሰዎች ምጽዋትን ላኩ። ይቺ ቀን ለእግዚአብሔር የተቀደሰች ናትና፥ አትዘኑም፤ እግዚአብሔር አይጥላችሁምና።”'),
  ('db6644d0-cd49-5b31-aaaf-55c11c1f4bfa', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 53, 53, 'ሌዋውያንም ሕዝቡን ሁሉ እንዲህ ብለው አዘዙ “ይቺ ቀን የተቀደሰች ናትና አትዘኑ።”'),
  ('4878e83d-86ff-5d3f-af05-0169a666a6bf', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 54, 54, 'ሁሉም ሊበሉና ሊጠጡ፥ ደስታም ሊያደርጉ፥ ለሌላቸውም ሰዎች ምጽዋትን ሊሰጡ ሄዱ።'),
  ('5dcd6914-9ea9-5347-aafe-9a51db86886a', '2b085003-be19-5d7e-ad40-2af9a0c04d22', 'b962200f-808e-5fe7-a689-1b1c020bbac7', 55, 55, 'በተሰበሰቡበት ቦታም ያስተማሯቸውን ቃል በሰሙ ጊዜ ታላቅ ደስታን አደረጉ።'),
  ('f7f17a7c-6ffd-5048-a01c-e6b64110e368', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', 'ffc76bc4-cf85-564b-adb7-5327f32e7a69', 1, 1, 'ከንፍታሌም ነገድ ከአሳሄል ወገን የገባኤል ልጅ የጦብኤል ልጅ የጦቢት የነገሩ መጽሓፍ ይህ ነው።'),
  ('9989e64f-0927-535b-a5df-85f0d148c21a', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', 'ffc76bc4-cf85-564b-adb7-5327f32e7a69', 2, 2, 'እርሱም፦ ከአሴር በላይ ካለች ከገሊላ ንፍታሌም ክፍል ከቄዴዎስ በስተቀኝ ካለችው ከታስቢ በአሦር ንጉሥ በአሜኔሴር ዘመን የተማረከው ነው።'),
  ('57ef4528-9784-5427-a713-3e1d9be05d36', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '95d328e1-8f54-5976-ad36-e0767de3c192', 1, 3, 'እኔ ጦቢት በሕይወቴ ዘመን በጽድቅና በቅንነት መንገድ ሄድሁ፤ ወደ አሶር ከተማ ወደ ነነዌ ከእኔ ጋር ለመጡ ወንድሞችና ወገኖች ብዙ ምጽዋትን አደረግሁ።'),
  ('9ef7b72d-a010-56d6-add5-30748e41a102', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '95d328e1-8f54-5976-ad36-e0767de3c192', 2, 4, 'እኔም ሕፃን ሆኜ ከእስራኤል ልጆች ጋር በሀገሬ ሳለሁ የአባቴ የንፍታሌም ወገኖች ሁሉ፥ እስራኤልም ሁሉ በእርሷ ይሠዉ ዘንድ እግዚአብሔር ከእስራኤል ነገድ ሁሉ ከመረጣት የልዑል ቤተ መቅደስ ለትውልድ ሁሉ ለዘለዓለም ከታነጸባትና ከተቀደሰባት ከኢየሩሳሌም ወጥተው ካዱ።'),
  ('3896efe5-bd72-5487-adcc-7085fe2b2a78', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '95d328e1-8f54-5976-ad36-e0767de3c192', 3, 5, 'የካዱ ሰዎችም ሁሉ ደማሊ ለሚባል ጣዖት ሠዉ፤ የአባቴም የንፍታሌም ወገኖች ሁሉ ከእነርሱ ጋር ተባበሩ።'),
  ('faebca9d-ca6a-516f-aace-fbc7e4c5dcf8', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '95d328e1-8f54-5976-ad36-e0767de3c192', 4, 6, 'እኔ ግን በዘለዓለማዊ ትእዛዝ ለእስራኤል ሁሉ እንደ ተጻፈ በበዓላት ቀን ብቻዬን ብዙ ጊዜ ወደ ኢየሩሳሌም እሄድ ነበር፤ በመጀመሪያም ከሸለትሁት ከበጎች ፀጕር ለአሮን ልጆች ለካህናቱ ወደ መሠዊያው እወስድላቸው ነበር።'),
  ('ad2af834-9056-55fd-a796-ba2fc4f5924a', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '95d328e1-8f54-5976-ad36-e0767de3c192', 5, 7, 'እህሉንና መጀመሪያውን ዐሥራት ሁሉ በኢየሩሳሌም ለሚያገለግሉ ለአሮን ልጆች እሰጣቸው ነበር፤ ሁለተኛውን እጅ ዐሥራት ግን እሸጠው ነበር፤ ምጽዋቱንም አውጣጥቼ በየዓመቱ ወደ ኢየሩሳሌም እሄድ ነበር።'),
  ('2eb2b0bc-59f8-5481-a3e2-173e6f3fe47e', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '95d328e1-8f54-5976-ad36-e0767de3c192', 6, 8, 'ሦስተኛውንም እጅ ዐሥራት የአባቴ እናት ዲቦራ እንዳዘዘች ለድሆች እሰጥ ነበር። አባቴና እናቴ በድኃአደግነት ትተውኛልና፤'),
  ('03bc8023-e86a-5981-a45d-a5ad66ca4466', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '95d328e1-8f54-5976-ad36-e0767de3c192', 7, 9, 'አካለ መጠን ባደረስሁም ጊዜ ከዘመዶች ዘር ሚስት አገባሁ፤ ከርስዋም ጦብያን ወለድሁ።'),
  ('00981b8e-ff03-5ac9-a21c-0ca8677c6a14', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '96110dbe-a9fa-5696-a94c-9f4a5b65896d', 1, 10, 'ወንድሞችና ዘመዶች ሁሉ ወደ ነነዌ በተማረኩ ጊዜ ከአሕዛብ እህል በሉ።'),
  ('69b392c8-8933-5910-af97-b64a731b956a', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '96110dbe-a9fa-5696-a94c-9f4a5b65896d', 2, 11, 'እኔ ግን የአሕዛብን እህል እንዳልበላ ሰውነቴን ጠበቅሁ፤'),
  ('8bfc18e0-53ad-580b-a5ea-a3d9116c392f', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '96110dbe-a9fa-5696-a94c-9f4a5b65896d', 3, 12, 'እግዚአብሔርን በፍጹም ልቡናዬ አስበዋለሁና።'),
  ('a5f768c6-427f-5b88-a771-2a636e10d621', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '96110dbe-a9fa-5696-a94c-9f4a5b65896d', 4, 13, 'እግዚአብሔርም በአሜኔሴር ፊት ክብርንና ባለሟልነትን ሰጠኝ፤ እርሱም መጋቢ አድርጎ ሾመኝ።'),
  ('922e97e9-9d5d-5818-ae83-35ec05827946', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '96110dbe-a9fa-5696-a94c-9f4a5b65896d', 5, 14, 'ወደ ምድያምም ሄድሁ፤ በምድያም ክፍል በራጊስ ያለ የጋብርያስ ወንድም ገባኤልንም ዐሥር መክሊት አደራ አስጠበቅሁት።'),
  ('1eedb262-9a12-56c5-a797-ff2c0a943963', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', '96110dbe-a9fa-5696-a94c-9f4a5b65896d', 6, 15, 'አሚኔሴርም በሞተ ጊዜ በእርሱ ፋንታ ልጁ ሰናክሬም ነገሠ፤ ሥራውም ክፉ ነበር፤ ከሹመቴም ሻረኝ፤ እንግዲህም ወዲህ ወደ ምድያም መሄድን አልቻልሁም።'),
  ('c00e4963-85c3-546b-ab63-c14714193b0d', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', 'ddbe3460-0e44-5ad4-a745-11d84310b218', 1, 16, 'በአሚኔሴርም ዘመን ለወንድሞች ብዙ ምጽዋትን አደረግሁ።'),
  ('7ae507f7-f78f-562d-a289-8a7ab53d195d', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', 'ddbe3460-0e44-5ad4-a745-11d84310b218', 2, 17, 'እህሌንም ለተራቡ፥ ልብሴንም ለተራቆቱ ሰጠሁ። ከወገኖችም የሞተ ሰውን በነነዌ ግንብ ሥር ወድቆ ባየሁ ጊዜ እቀብረው ነበር።'),
  ('0f873629-669c-5ca5-a25d-a84202c0b056', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', 'ddbe3460-0e44-5ad4-a745-11d84310b218', 3, 18, 'ንጉሥ ሰናክሬም ከይሁዳ ሸሽቶ በተመለሰ ጊዜ የገደላቸውን ሰዎች እኔ በስውር እቀብራቸው ነበር። እርሱ ተቈጥቶ ብዙዎችን ገድሎ ነበርና። ንጉሡም ሬሳቸውን አስፈለገ፥ አላገኘምም።'),
  ('bae48b55-7bb4-56e8-a7de-26480b7f05da', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', 'ddbe3460-0e44-5ad4-a745-11d84310b218', 4, 19, 'ከነነዌ ሰዎችም አንዱ ሰው ሄዶ እንደ ቀበርኋቸው ነገር ሠርቶ ከንጉሡ ጋር አጣላኝ፤ እኔም ተሰወርሁ፤ ሊገድሉኝ እንደሚፈልጉኝም ባወቅሁ ጊዜ ፈርቼ ገለል አልሁ።'),
  ('7535c046-b5a9-56c8-a329-8c6ee79cc6c8', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', 'ddbe3460-0e44-5ad4-a745-11d84310b218', 5, 20, 'ባጡኝም ጊዜ ገንዘቤን ሁሉ ዘረፉኝ፤ ከሚስቴ ሐናና ከልጄ ጦብያ በቀር ያስቀሩልኝ የለም።'),
  ('f31a6ab6-bf8b-5e4c-a516-56055bbd5990', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', 'ddbe3460-0e44-5ad4-a745-11d84310b218', 6, 21, 'ሁለቱ ልጆቹ እስኪገድሉት ድረስ፥ ሸሽተውም ወደ አራራት ተራራ እስኪሄዱ ድረስ አምሳ አምስት ቀን ከቤቴ አልወጣሁም። ልጁ አስራዶንም በእርሱ ፋንታ ነገሠ፤ የወንድሜ ልጅ የአናሔል ልጅ አኪአኪሮስንም በአባቱ ቤት ሁሉና በሥራታቸው ሁሉ ላይ ሾመው።'),
  ('2a915111-87b3-57c6-a8fc-0d1457a97afc', '56030f8a-3e70-5aed-a3c1-5d89ab3ed367', 'ddbe3460-0e44-5ad4-a745-11d84310b218', 7, 22, 'አኪአኪሮስም ማለደልኝ፤ ወደ ነነዌም መለሰኝ። አኪአኪሮስም የማኅተምና የቤቱ ንብረት ጠባቂ ነበር። አስራዶንም ዳግመኛ ሾመው።'),
  ('7316d90e-c988-51d3-acbf-52e7bf17e28d', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '6dfc2b94-2859-53e0-a393-7709f73f93d4', 1, 1, 'ወደ ሀገሬም በተመለስሁ ጊዜ ሚስቴን ሐናንና ልጄን ጦብያን መለሰልኝ። በሰባተኛው ሱባኤ በተቀደሰችው የበዓለ ኀምሳ ዕለት ለእኔ መልካም ነገር አደረጉልኝ፤ እበላም ዘንድ ተቀመጥሁ።'),
  ('b6367ce7-1a86-577a-a7e1-b3830fa044f0', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '6dfc2b94-2859-53e0-a393-7709f73f93d4', 2, 2, 'ምግቡም እጅግ ብዙ እንደ ሆነ ባየሁ ጊዜ ልጄን እንዲህ አልሁት፥ “ሄደህ ከወንድሞቻችን ያገኘሃቸውን ድኆች ባልንጀሮችን አምጣ። እግዚአብሔርን አስቤዋለሁና። እነሆ እኔም እጠብቅሃለሁ።”'),
  ('1cb9f1ef-ab92-521a-a7d9-d413c38627a4', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '6dfc2b94-2859-53e0-a393-7709f73f93d4', 3, 3, 'በተመለሰ ጊዜም እንዲህ አለኝ፥ “አባቴ! ከወገኖቻችን የተገደለ አንድ ሰው አገኘሁ፤ ሬሳውም በገበያ ወድቆአል።”'),
  ('71de1249-4653-545a-a81e-084773dc8942', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '6dfc2b94-2859-53e0-a393-7709f73f93d4', 4, 4, 'እኔም እህል ሳልቀምስ ተነሣሁ፤ ፀሐይም እስኪገባ ድረስ ወደ አንዱ ቤት አገባሁት።'),
  ('6ee43fd8-c7f7-5628-ab60-e5dc8da33d70', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '6dfc2b94-2859-53e0-a393-7709f73f93d4', 5, 5, 'ወደ ቤቴም ተመልሼ ታጥቤ ምግቤን በኀዘን በላሁ።'),
  ('fef7285b-a6f2-58ce-acf5-ce1c9e22c191', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '6dfc2b94-2859-53e0-a393-7709f73f93d4', 6, 6, 'አሞፅም፥ “በዓላችሁ ወደ ኀዘን፥ ደስታችሁም ወደ ልቅሶ ይመለሳል” ያለውን አስታወስሁ።'),
  ('87d334da-0a32-5297-afcd-660429823936', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '6dfc2b94-2859-53e0-a393-7709f73f93d4', 7, 7, 'ከዚህም በኋላ አለቀስሁ፤ ፀሐይም በገባ ጊዜ ሄጄ መቃብር ቆፍሬ ቀበርሁት።'),
  ('ed56d03a-99e8-5954-aba6-ad03e64c6da7', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '6dfc2b94-2859-53e0-a393-7709f73f93d4', 8, 8, 'ጎረቤቶችም ሳቁብኝ፤ እንዲህም አሉ፥ “ይህ ሰው ስለዚህ ሥራ እገደላለሁ ብሎ አይፈራምን? ንጉሥ የገደላቸውን ይቀብራልና።”'),
  ('6df8885f-b2cb-59c9-a492-b79809c6a356', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '41b24d9e-853e-5b3a-a1ad-5b128360935b', 1, 9, 'በዚያችም ሌሊት ከቀብር ተመለስሁ፤ ረክሼም ስለነበር በዕድሞው ሥር አደርሁ፤ ዓይኖች ግን ተገልጠው ነበር።'),
  ('bbdcedb9-ee6d-51f8-acc6-70d1b93ef72b', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '41b24d9e-853e-5b3a-a1ad-5b128360935b', 2, 10, 'በዕድሞው ላይም ወፎች እንዳሉ አላወቅሁም፤ ፊቴም ተገልጦ ሳለ እነዚያ ወፎች በዐይኔ ላይ የሚያቃጥል ኩስ ጣሉብኝ፤ በዐይኔም ብልዝ ወጣብኝ፤ እኔም ወደ ባለ መድኀኒት ሄድሁ፥ ነገር ግን የጠቀመኝ የለም፤ ብቻዬን ወደ ኤልማድያ እስክሄድ ድረስ አኪአክሮስ ይመግበኝ ነበር።'),
  ('189cae8f-d2d6-5473-a588-3ce816b1e53c', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '41b24d9e-853e-5b3a-a1ad-5b128360935b', 3, 11, 'ሐናም በሴቶች ቤት ታገለግል ነበር።'),
  ('3d16e184-6816-5e0d-a3cb-6631387685fd', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '41b24d9e-853e-5b3a-a1ad-5b128360935b', 4, 12, 'ወደ እመቤቶችዋም ላከች፤ እነርሱም ደመወዟን ሰጧት፤ የበግ ጠቦትም ጨመሩላት።'),
  ('b9840a12-42f4-5456-a3bb-0c7bd861e405', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '41b24d9e-853e-5b3a-a1ad-5b128360935b', 5, 13, 'ወደ እኔም በመጣች ጊዜ ትጮህ ጀመር፤ እኔም እንዲህ አልኋት፥ “ይቺ ጠቦት ከወዴት ናት? የሰረቅሻት ከሆነችም ወደ ጌቶችዋ መልሻት። የተሰረቀ መብላት አግባብ አይደለምና።”'),
  ('86ed597f-b77f-56ae-a36e-e8cb1d9b0602', 'b21cc698-3863-5b2b-ab98-316e4da3493e', '41b24d9e-853e-5b3a-a1ad-5b128360935b', 6, 14, 'እርሷም አለችኝ፥ “በደመወዜ ላይ ሰጡኝ፤” እኔ ግን አላመንኋትም፤ ለባለቤቶቹም መልሺ ብዬ ከእርሷ ጋር ተከራከርሁ፤ እርሷም መልሳ፥ “ጸሎትህና ምጽዋትህ ወዴት ነው? እነሆ በላይህ ያለው ሁሉ ታወቀ” አለችኝ።'),
  ('7a69d9f3-e2d5-5ecf-a487-d56643a22294', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 1, 1, 'ከዚህም በኋላ በልብ ጭንቀት ተከዝሁ፤ አልቅሼም ጸለይሁ።'),
  ('f5bfd3d7-1af9-587d-aa08-fac2b42a6f19', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 2, 2, 'እንዲህም አልሁ፥ “አቤቱ በሥራህ ሁሉ በቸርነትና በፍርድ፥ በሚገባ ጽድቅም አንተ እውነተኛ ነህ፤ አቤቱ አንተ በሚገባ ዓለምን ትገዛለህ።'),
  ('9b62b4f4-33c3-5e28-abb7-56b893982d1d', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 3, 3, 'አስበኝ፤ ተመልከተኝም፤ በራሴ ኀጢአትና አንተን በበደሉ፥ ትእዛዝህንም ባልሰሙ በአባቶች ኀጢአት አትበቀለኝ።'),
  ('e9f69833-eeb1-5df0-a2ae-c4d9565f5fdd', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 4, 4, 'ለመበርበርና ለመማረክ፥ ለመገደልም አደረግኸን፤ በዓለሙ ሁሉና በውስጣቸው በተበተንባቸው በአሕዛብም ዘንድ መተረቻና መዘባበቻ ሆንን።'),
  ('2c501b97-87b8-5777-ac96-948b0b6d5e30', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 5, 5, 'አሁንም እውነተኛ ፍርድህ ብዙ ነው፤ የእኔ ኀጢአትና የአባቶች ኀጢአትም እንዲሰረይ አድርግልኝ፤ ትእዛዝህን አላደረግንምና፥ በፊትህም በእውነት አልሄድንምና።'),
  ('5c466cda-009b-51c0-a379-d27b58280bc6', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 6, 6, 'አሁንም በፊትህ ደስ የሚያሰኝህን በእኔ አድርግ፤ ከመኖር መሞት ይሻለኛልና በሞት እሰናበት ዘንድ፥ መሬትም እሆን ዘንድ ነፍሴን የሚቀበላትን እዘዝልኝ። በሐሰትና በውርደት ተግዳሮትን ሰምቻለሁና፥ ኀዘንም በእኔ ላይ በዝትዋልና ከመከራዬ እሰናበት ዘንድ፥ ወደ ዘለዓለማዊ ቦታም እሄድ ዘንድ እዘዝ፤ ፊትህንም ከእኔ አትመልስ።”'),
  ('98ed12d2-654d-5f0a-af51-cbc7e573a520', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 7, 7, 'በዚያችም ቀን በሜዶን ክፍል በጣኔስ የራጉኤል ልጅ ሣራን ከአባትዋ ሴቶች አገልጋዮች ተግዳሮት አገኛት።'),
  ('bd9dcc33-1b77-5814-a17f-0209a92453f3', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 8, 8, 'ለሰባት ወንዶች አጋብተዋት እንደ ወንድና ሴት ሳይቃረቡ አስማንድዮስ የሚባል ክፉ ጋኔን ገድሏቸዋልና፤ እንዲህም አሏት፥ “ባሎችሽ እየታነቁ እንደሚሞቱ አታውቂምን፦ እነሆ ሰባቱ አገቡሽ፤ ከእነርሱም አንዱ ስንኳ አልተከተለሽም።'),
  ('a4570232-2928-527f-afc9-d3be9bbdbc72', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 9, 9, 'እንግዲህ ስለ እነርሱ ምን አሳዘነን? እነርሱ ሞተዋልና ከእነርሱ ጋር ሂጂ፤ ከአንቺ ወንድ ወይም ሴት ልጅ እስከ ዘለዓለሙ ድረስ አንይ።”'),
  ('3e9b06db-8c85-576b-a609-ca2b7024e396', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'e1bdc32d-6c4a-577f-a803-b56f22e096de', 10, 10, 'ይህንም በሰማች ጊዜ ለመታነቅ እስከምትመኝ ድረስ እጅግ አዘነች። እንዲህም አለች፥ “እኔ ለአባቴና ለእናቴ አንዲት ነኝ፤ እንደዚህም ባደርግ ተግዳሮት እሆንበታለሁ፤ ሽምግልናውንም፥ ሰውነቱንም በጭንቅ ወደ መቃብር አወርዳታለሁ።”'),
  ('c72cfbd9-df44-5406-abeb-6c1e791cae37', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'dac97e8a-1ff0-5234-ab66-192bae309a5f', 1, 11, 'በመስኮቱም በኩል ጸለየች፤ እንዲህም አለች፥ “አቤቱ አንተ ፈጣሪዬ ቡሩክ ነህ፤ ቅዱስና ክቡር ስምህም ለዘለዓለም ይመስገን፤ ሥራህም ሁሉ ለዘለዓለሙ ክቡር ነው።'),
  ('1c2f0b0f-a73e-51e1-a43d-484366b9b43c', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'dac97e8a-1ff0-5234-ab66-192bae309a5f', 2, 12, 'አቤቱ አሁንም ዐይኖችንና ፊቴን ለአንተ ሰጠሁ።'),
  ('07b810c2-5828-5e58-af36-b2ab1c4b5919', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'dac97e8a-1ff0-5234-ab66-192bae309a5f', 3, 13, 'እንግዲህ ወዲህ ተግዳሮትን እንዳልሰማ ከዚህ ዓለም አሰናብተኝ አልኹህ።'),
  ('bad4d420-32b9-590d-adb6-5f93bb7a877b', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'dac97e8a-1ff0-5234-ab66-192bae309a5f', 4, 14, 'ከወንድ ጋር ከሚሠራው ኀጢአት ሁሉ እኔ ንጽሕት እንደ ሆንኹ አቤቱ አንተ ታውቃለህ።'),
  ('a248c775-f118-5753-ae16-ef3b87770a6c', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'dac97e8a-1ff0-5234-ab66-192bae309a5f', 5, 15, 'በተማረክሁበትም ሀገር ስሜንና ያባቴን ስም አላሳደፍሁም፤ እኔም ለአባቴ አንዲት ነኝ። ወንድም የለኝም፤ ሚስት እሆንለት ዘንድ የምጠብቀው የቅርብ ዘመድም የለኝም፤ ሰባቱ ባሎች ሙተውብኛልና እንግዲህ ለምን እኖራለሁ? ልትገድለኝ ባትወድ ግን ወደ እኔ ተመልክተህ ራራልኝ፤ ተግዳሮትንም እንዳልሰማ እዘዝልኝ።”'),
  ('16f1e7df-f2cb-50ec-a47e-17199ca106d1', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'dac97e8a-1ff0-5234-ab66-192bae309a5f', 6, 16, 'የሁለቱም ጸሎታቸው በእግዚአብሔር በገነነ ጌትነቱ ፊት ተሰማ።'),
  ('f2ecaffd-cccb-5dc0-abc3-b2dbe8a9aa73', 'c9f801f8-0235-5948-ac19-87c3e3a70525', 'dac97e8a-1ff0-5234-ab66-192bae309a5f', 7, 17, 'ሩፋኤልንም ላከው፤ ሁለቱን ያድናቸው ዘንድ፥ ከጦቢትም ዐይን ብልዙን ያጠፋለት ዘንድ፥ የራጉኤል ልጅ ሳራንም ሚስት ልትሆነው ለጦቢት ልጅ ለጦብያ ይሰጣት ዘንድ፥ ክፉ ጋኔን አስማንድዮስንም ይሽረው ዘንድ፥ ጦብያ ይወርሳታልና። በዚያም ወራት ጦቢት ተመልሶ ወደ ቤቱ ገባ፤ የራጉኤል ልጅ ሳራም ከሰገነቷ ወረደች።'),
  ('d4197ea0-18f0-5455-a824-642f151162f2', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 1, 1, 'በዚያችም ቀን ጦቢት በሜዶን ክፍል በራጌስ ለገባኤል አደራ ስላስጠበቀው ብር አሰበ።'),
  ('836853e3-cdac-5ba7-a2b7-8e838012f447', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 2, 2, 'አስቦም እንዲህ አለ፥ “እነሆ ልሙት ብዬ ለመንሁ፤ እንግዲህ ልጄን ጦብያን ጠርቼ ሳልሞት የማልነግረው ለምንድን ነው?”'),
  ('7bdd4d2e-da97-5eec-adc8-59867d4c7578', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 3, 3, 'ጠርቶም እንዲህ አለው፥ “ልጄ በሞትሁ ጊዜ በመልካሙ ቅበረኝ፤ እናትህንም ጠብቃት፤ በሕይወትህም ዘመን ሁሉ አክብራት፤ የወደደችውንም አድርግላት፤ አታሳዝናትም።'),
  ('86b57865-4fd4-5216-a0f9-a4a37d76e116', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 4, 4, 'ልጄ፥ በማኅፀን ባንተ ብዙ መከራ እንደ ተቀበለች አስብ፤ በሞተችም ጊዜ በእኔ ዘንድ ባንድ መቃብር ቅበራት።'),
  ('0d620f6c-6a37-5116-a0d7-bf76d95c25d6', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 5, 5, 'ልጄ ሆይ! በዘመኑ ሁሉ ፈጣሪህ እግዚአብሔርን አስበው፤ በደልንና ትእዛዙን መካድን አትውደድ፤ በሕይወትህም ዘመን ሁሉ ጽድቅን ሥራ፤ በዐመፅ መንገድም አትሂድ።'),
  ('8719b0a9-64fb-5b93-a2f0-5d16afde1636', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 6, 6, 'ጽድቅን ከሠራሃት በመንገድህ ሁሉና በሠራኸው ሥራ ሁሉ ትከናወናለህ፤ ጽድቅንም ለሚሠሩዋት ሁሉ ይከናወንላቸዋል።'),
  ('5e2c4466-2c34-5b58-a4aa-1b7066e4f8f8', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 7, 7, 'ከገንዘብህ ምጽዋት ስጥ፤ ምጽዋትንም በምትመጸውት ጊዜ በገንዘብህ አትንፈግ፤ ከድኃም ፊትህን አትመልስ። እግዚአብሔርም ፊቱን ከአንተ አይመልስም።'),
  ('0a351c9d-4f13-5e9a-a1d5-9b4353bbfd8b', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 8, 8, 'ባለህ መጠን የሚቻልህን ያህል ምጽዋት አድርግ።'),
  ('d28feec7-fa9a-5363-ac05-2bcf907cf075', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 9, 9, 'ጥቂትም ቢሆን ለመስጠት አትፈር፤ ምጽዋት መስጠት መልካም ድልብን ታደልብልሃለችና።'),
  ('760ff18e-1ad1-5114-a7c1-23ff1de6a511', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 10, 10, 'ምጽዋት በመከራ ቀን ከሞት ታድናለችና፤ ወደ ጨለማም ከመሄድ ትጠብቅሃለችና።'),
  ('8dccb869-b80c-533e-ac44-83484084075f', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 11, 11, 'ምጽዋትም ለሚያደርጋት ሁሉ በልዑል ፊት መልካም ስጦታ ናት።'),
  ('81b7a946-9b45-57e1-a5a3-174b7d129992', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 12, 12, '“ልጄ! ራስህን ከዝሙት ጠብቅ፤ ከአባቶችህ ዘር ሁሉ አስቀድመህ ሚስት አግባ። ከዘመዶችህ ካልሆነች ከባዕድ ወገን ግን አታግባ። እኛ ከጥንት ጀምረው ከነበሩ ከነቢያት ከኖኅና ከአብርሃም ፥ ከይስሐቅና ከያዕቆብ ልጆች ወገን ነንና፤ ልጄ ሆይ፥ ሁሉም ከአባቶቻቸው ትውልድ ሚስት እንዳገቡ አስብ፤ በልጆቻቸውም እንደ ተባረኩ፥ ዘሮቻቸውም ምድርን እንደ ወረሷት አስብ።'),
  ('976213e5-83cc-5a10-acbe-f898c5031c57', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 13, 13, 'አሁንም ልጄ ሆይ፥ ባልንጀራህን ውደድ፤ በባልንጀራህ፥ በወገኖችህ ወንዶች ልጆችና በወገኖችህ ሴቶች ልጆች ልብህን አታስታብይ፤ ከእነርሱም ወገን ሚስት አግባ። ትዕቢት ባለችበት ዘንድ ውርደት አለችና፥ ብዙ ሁከትም አለና፤ ስንፍናም ባለችበት ዘንድ ችግር አለች፤ ታላቅ ድህነትም አለ፤ ስንፍና የረኃብ እናት ናትና።'),
  ('97be4dfd-4374-59bf-ab46-1889ed7652b3', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 14, 14, 'የተገዛልህ ሁሉ ደመወዝ ባንተ ዘንድ አይደር፤ በጊዜው ስጠው እንጂ። ለእግዚአብሔር ብትገዛ ዋጋህ ይበዛልሃልና፤ ራስህን ዕወቅ፤ በሥራህና በጠባይህ ሁሉ ጠቢብ ሁን።'),
  ('639da4eb-44e5-5128-ae9c-1846b58fecab', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 15, 15, 'ለራስህ የምትጠላውን ለማንም አታድርግ፤ ለመስከርም ወይንን አትጠጣ፤ ከሰካራሞችም ጋር በጎዳና አትሂድ።'),
  ('9697f877-8619-502e-ac11-77190a4971b1', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 16, 16, 'ከእህልህም ለተራበ፥ ከልብስህም ለተራቈተ ስጥ፤ ከተረፈህም ሁሉ ለምጽዋት አድርግ።'),
  ('3a7b57e3-ff83-54e0-afd4-2b7de982c959', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 17, 17, 'እህልህንም በጻድቃን መቃብር ላይ ዝራ፤ ለኀጥኣን ግን አትስጥ።'),
  ('2c63c7b0-c32e-5063-a6de-26b4d76331c2', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 18, 18, 'በጠቢባን ዘንድ ምክርን ፈልግ፤ የምትረባህንም ምክር አታቃል።'),
  ('0c3349dd-4f5c-5cc4-afcd-e817103387ee', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '34e318ca-f459-51cf-a2eb-f6a4fc43d874', 19, 19, 'በየጊዜውም ፈጣሪህ እግዚአብሔርን አመስግነው፤ ጎዳናህም የቀና ይሆን ዘንድ ወደ እርሱ ጸልይ፤ በሥራህ ሁሉና በጎዳናህ ሁሉ ያከናውንልሃል። በጎውን ሁሉ ከሚሰጥ ከእርሱ ከእግዚአብሔር በቀር ከእግዚአብሔር ያልሆነ አሕዛብ ሁሉ የሚመክሩት ምክር ከንቱ ነውና። የወደደውን ያዋርደዋል፤ እርሱም እንደ ወደደ ይሆናል። አሁንም ልጄ ሆይ ትእዛዜን አስብ፤ ከልብህም አይጥፋ።'),
  ('94d3943e-83bb-524d-ab09-5b4b9353f676', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '5cdb4985-506c-5f96-a54e-5bc54bb3beeb', 1, 20, '“አሁንም በሜዶን ክፍል በራጊስ ሰው በግብርያል ልጅ በገባኤል ዘንድ አደራ ስላስጠበቅሁት ስለ ዐሥሩ የብር መክሊት እነግርሃለሁ።'),
  ('2f378560-3e5c-5d3f-a36a-657f6f037e8b', 'b00fee3a-03ba-53be-a232-0fc6d90b64a3', '5cdb4985-506c-5f96-a54e-5bc54bb3beeb', 2, 21, 'ልጄ ሆይ! ከድህነት የተነሣ አትፍራ። ድሆች ባንተ ዘንድ ብዙ በረከትን ይቀበላሉና፥ እግዚአብሔርን ብትፈራው ከኀጢአትም ሁሉ ብትርቅ እግዚአብሔርንም ደስ የሚያሰኘውን ሥራ በፊቱ ብታደርግ ብዙ በረከት ባንተ ዘንድ ይኖራል።”'),
  ('9dd42b6d-b8b8-5e39-a281-54663ec03ffe', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 1, 1, 'ጦብያም መለሰ እንዲህም አለ፥ “አባቴ! ያዘዝኸኝን ሁሉ አደርጋለሁ።'),
  ('ef2a8a03-79ed-5d0b-a058-938f6e5feac8', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 2, 2, 'ነገር ግን ከማላውቀው ሰው ያን ብር መቀበል እንዴት እችላለሁ?”'),
  ('eee0c566-3fbc-5b7a-a58e-35ca23dfce38', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 3, 3, 'እርሱም ደብዳቤ ሰጠው፤ እንዲህም አለው፥ “ከአንተ ጋር የሚሄድ ሰው ፈልግ፤ እኔም በሕይወት ሳለሁ ደመወዙን እሰጠዋለሁ፤ ሄደህም ያንን ብር ተቀበል።”'),
  ('a9387691-93a9-56b5-ad99-0e4bd97ce0b5', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 4, 4, 'እርሱም ሰውን ሊፈልግ ሄዶ መልአኩን ሩፋኤልን አገኘው፤ ነገር ግን መልአክ እንደ ሆነ አላወቀም።'),
  ('4c12456c-084b-52bb-a8a5-af61bc2f6382', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 5, 5, 'እርሱም አለው፥ “ሀገሩን ታውቅ እንደ ሆነ ወደ ሜዶን ክፍል ወደ ራጊስ ከኔ ጋራ መሄድ ትችላለህን?”'),
  ('8d00f425-42ba-5d2a-ae3f-9d97ff7ad51d', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 6, 6, 'መልአኩም እንዲህ አለው፥ “ከአንተ ጋር እሄዳለሁ፤ መንገዱንም ዐውቃለሁ፤ በገባኤልም ዘንድ ነበርሁ።”'),
  ('c71baf30-a600-5dc4-afc4-58d7f8f63f04', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 7, 7, 'ጦብያም፥ “ላባቴ እስክነግረው ድረስ ቈየኝ” አለው።'),
  ('af9214f4-ee98-53d0-a2b7-e097019a2c2a', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 8, 8, 'እርሱም፥ “ሂድ፤ አትቈይ” አለው፤ ለአባቱም፥ “ከእኔ ጋር የሚሄድ እነሆ አገኘሁ” አለው። እርሱም፥ “ከማን ወገን እንደ ሆነ፥ ካንተም ጋራ ለመሄድ የታመነ እንደ ሆነ ዐውቅ ዘንድ ወደ እኔ ጥራው” አለው።'),
  ('836e2d9b-55b6-56f2-a8a9-ef0c95dfc283', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 9, 9, 'ጠራውና ገባ፤ እርስ በርሳቸውም እጅ ተነሣሡ።'),
  ('2dd94164-a847-5052-ad6a-0cd9a0c3557e', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 10, 10, 'ጦቢትም፥ “አንተ ወንድሜ! ከማን ወገን ነህ? ከወዴትስ ሀገር ነህ?” አለው።'),
  ('cdaf1480-8314-5cb2-a567-9c22aea43204', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 11, 11, 'መልአኩም፥ “ወገኔንና ሀገሬን ትመረምር? ወይስ ከልጅህ ጋራ የምሄድበትን ዋጋ ትሰጠኝ?” አለው። ጦቢትም፥ “አንተ ወንድሜ ዘመድህንና ስምህን ዐውቅ ዘንድ እወዳለሁ” አለው።'),
  ('d8f41ae0-ea34-5296-a099-53eb06c8299a', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 12, 12, 'እርሱም፥ “እኔስ የወንድምህ የታላቁ አናንያ ዘመድ አዛርያ ነኝ” አለው።'),
  ('d7bec724-3356-59a5-ad2e-7ae3f10199f6', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 13, 13, 'ጦቢትም አለው፥ “አንተ ወንድሜ ደኅና ነህን? ወገንህንና ሀገርህን ዐውቅ ዘንድ መርምሬአለሁና አትንቀፈኝ፤ ነገር ግን አንተ በእውነቱ ከደግና ከተባረከ ወገን ነህ፤ እኔም የታላቁ የሴምዩን ልጆች አናንያንና ኢታያንን ዐውቃቸዋለሁ፤ እንሰግድ ዘንድ ከእነርሱ ጋር አብረን ወደ ኢየሩሳሌም ሄደን ነበር፤ በኵራቱንና የእህላችንን ዐሥራት ወስደን ነበር፤ ነገር ግን በአባቶቻችን በደል አልበደልንም።'),
  ('1a34ab93-be05-59d9-accd-81cf95a73169', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 14, 14, 'ወንድሜ አንተ ግን ከደግ ቤተ ሰብ ነህ፤ ነገር ግን ንገረኝ፤ ደመወዝህን ምን እንስጥህ? በየቀኑ አንድ ድራህማ እንስጥህን? ምግብህስ ከልጄ ጋር ይሁን?'),
  ('1406fa71-63e4-5a6a-a685-d36da4ded56d', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 15, 15, 'በደኅና ከተመለሳችሁ በደመወዝህ ላይ እጨምርልሃለሁ፤” እንደዚህም ጨረሱ።'),
  ('acdc4da7-ed68-5760-ab6a-71b3754b6354', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 16, 16, 'ጦብያንም አለው፥ “ትሄዱ ዘንድ፥ ትከናወኑም ዘንድ ተዘጋጁ።” ልጁም ለመንገድ ስንቃቸውን አዘጋጀ፤ አባቱም አለው፥ “ከዚህ ሰው ጋር ሂድ፤ በሰማያት የሚኖር እግዚአብሔር መንገዳችሁን ያቅናላችሁ፤ መልአኩም አብሮአችሁ ይሂድ፤” ሁለቱም ወጥተው ሄዱ፤ ሌላው ልጃቸውም ተከተላቸው።'),
  ('cb451bc7-def2-5516-a640-69944ff99b6a', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 17, 17, 'እናቱ ሐናም አለቀሰች፤ ጦቢትንም እንዲህ አለችው፥ “ልጄን ለምን ላክኸው? እርሱ በፊታችን የሚወጣና የሚገባ፥ በእጃችን ያለ ምርኩዛችን አይደለምን?'),
  ('12e5c3ab-f9d3-5121-ab88-9fc1a2886ea1', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 18, 18, 'ብሩስ ይጥፋ የልጄም ቤዛ ይሁን!'),
  ('e9adeed7-70e9-55a8-a1b7-23b53c45cbd4', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 19, 19, 'የምንኖርበት እግዚአብሔር የሰጠን ይበቃናልና።”'),
  ('28bc640a-1925-5582-abfa-f89150d0da5f', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 20, 20, 'ጦቢትም አላት፥ “እኅቴ አትጨነቂ፤ በደኅና ይመለሳል፤ በዐይኖችሽም ታይዋለሽ።'),
  ('8d992dac-b23a-5ef5-a8ce-b99a5a56ab4b', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 21, 21, 'ቸር መልአክ በፊቱ ይሄዳልና፥ ጎዳናውንም ያቃናለታልና፥ በደኅናም ይመለሳልና።”'),
  ('4f7e49c8-94cd-55a1-ae63-b01a9c1574a4', '4324c957-0951-54eb-a0cf-cece70937432', 'c0d7b195-4563-5ac1-adbf-ddc320b131e6', 22, 22, 'ሐናም ልቅሶዋን ተወች።'),
  ('b6bbf32d-5723-5c96-a80d-1e69cb28977c', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 1, 1, 'በመንገዳቸውም ሲሄዱ ወደ ጤግሮስ ወንዝ ማታ ደረሱ፤ በዚያም አደሩ።'),
  ('fb1b6661-cffb-580f-ad19-187b5871d0d3', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 2, 2, 'ያም ልጅ ሊታጠብ ወረደ፤ ከውኃውም ውስጥ ዓሣ ወጥቶ ተወረወረ፤ ያንም ልጅ ይውጠው ዘንድ ወደደ።'),
  ('febb3315-94a5-5848-a884-5eced421ef6b', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 3, 3, 'መልአኩም፥ “ያን ዓሣ ያዘው” አለው፤ ያም ልጅ ዓሣውን ያዘው፤ ወደ የብስም አወጣው።'),
  ('1fb62e01-344e-5a82-a08e-50bf422efcb1', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 4, 4, 'ያም መልአክ፥ “ዓሣውን እረደው፤ ልቡንና ጉበቱን፥ ሐሞቱንም ያዝ፤ አጥብቀህም ጠብቅ” አለው።'),
  ('b76a2c8b-998c-5f25-ae51-5d4a29bd378d', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 5, 5, 'ያም ልጅ መልአኩ እንዳዘዘው አደረገ፤ ዓሣውንም ጠብሰው በሉ፤ ሁለቱም ገሥግሠው ሄደው፥ ወደ በጣኔስ ደረሱ።'),
  ('f57cbf14-f56d-5c89-aa42-a04c36288719', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 6, 6, 'ያም ልጅ መልአኩን አለው፥ “አንተ ወንድሜ አዛርያ! የዚህ ዓሣ ልቡ፥ ጉበቱና ሐሞቱ ለምንድን ነው?”'),
  ('59ea621c-205d-5406-a495-269fa9e3e57c', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 7, 7, 'መልአኩም አለው፥ “ልቡና ጉበቱ፦ የሚያሳምም ክፉ ጋኔን ያደረበት ቢኖር፥ ወይም ርኩስ መንፈስ ያደረበት ቢኖር ያን ለዚያ ሰው በፊቱ ያጤሱለታል፤ ሴትም ብትሆን ያጤሱላታል፤ ከዚያም በኋላ አይታመሙም።'),
  ('ad4684c4-d5c1-5767-a209-f257567295ae', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 8, 8, 'ሐሞቱን ግን በዐይኑ ላይ ብልዝ ያለበትን ሰው ይኩሉታል፤ እርሱም ይድናል።”'),
  ('70bb7610-7f2c-5b14-a797-2fe1ef79dde2', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 9, 9, 'ወደ ራጊስም በቀረቡ ጊዜ፥'),
  ('8db1b45f-0272-55fd-a422-54b7a358d606', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 10, 10, 'መልአኩ አለው፥ “አንተ ወንድሜ! ዛሬ በራጉኤል ቤት እናድራለን፤ እርሱም ዘመድህ ነው፤ አንዲት ልጅም አለችው፤ ስሟም ሳራ ይባላል፤ ሚስት ትሆንህ ዘንድ እንዲሰጥህ ስለ እርስዋ እናገራለሁ፤ ለአንተ ውርሷ ይደርስሃልና።'),
  ('d3796bb2-60e2-519d-acaa-e718610fd42d', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 11, 11, 'ከዘመዶችዋም ወገን አንተ አለህ፤ ልጂቱም ደግና ልባም ናት።'),
  ('0a9180ba-afd6-5013-a945-3d965d2614c7', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 12, 12, 'አሁንም ስማኝ፤ ለአባትዋም እነግረዋለሁ፤ ከራጊስም በተመለስን ጊዜ የሠርግ በዓል እናደርጋለን፤ ራጉኤል፦ በሙሴ ሕግ መሠረት ለሌላ ሰው ይሰጣት ዘንድ አይወድድምና፥ ብትሞትም በወደደ ነበር፤ከሰው ሁሉ ይልቅ ውርሷ ላንተ ይደርስሃልና።”'),
  ('57e0157f-0096-508c-a5ed-4b08fa5faf9c', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 13, 13, 'ያም ልጅ መልአኩን አለው፥ “አንተ ወንድሜ አዛርያ! ያቺን ልጅ ለሰባት ወንዶች እንዳጋቧት እኔ ሰምቻለሁ፤ ሁሉም በሠርጉ ጊዜ ሞቱ።'),
  ('0ac27992-20d8-5226-ac4f-46a50fc5c6cf', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 14, 14, 'አሁንም እኔ ላባቴ ብቸኛ ነኝ፤ ወደ እርሷም በገባሁ ጊዜ እንዳልሞት ፥ ያባቴንና የናቴንም ሕይወት በእኔ ምክንያት በጭንቅ ወደ መቃብር እንዳላወርድ እፈራለሁ፤ የሚቀብራቸውም ሌላ ልጅ የላቸውምና።”'),
  ('c3f3e67f-d154-5f15-a714-db6a88b0f11d', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 15, 15, 'ያም መልአክ አለው፥ “ከዘመዶችህ ሚስት ታገባ ዘንድ አባትህ ያዘዘህን ቃል አታስብምን? አሁንም አንተ ወንድሜ ስማኝ፤ የጋኔኑ ነገርስ አያሳዝንህ፤ በዚች ሌሊት ከዘመዶችህ ወገን እርሷ ሚስት ሆና ትሰጥሃለችና፤'),
  ('9430cdf4-2af8-5579-a345-de6e00353814', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 16, 16, 'ወደ ጫጕላ ቤትም በገባህ ጊዜ የዕጣን ዕራሪ ውሰድ፤ ከዚህም ዓሣ ከጉበቱና ከልቡ ጨምረህ አጢስበት።'),
  ('6891a306-b2ed-5b81-a2c0-c52f99aa3941', '78ac10da-199c-5dd8-a5e8-63b5b2bbf2cc', 'b9d82f9f-394b-5ce2-a276-9377c5f0bb7b', 17, 17, 'ጋኔኑም በሸተተው ጊዜ ይሸሻል፤ ለዘለዓለሙም አይመለስም። ወደ እርሷም በገባህ ጊዜ ሁለታችሁ ይቅር ባይ ወደ ሆነው ወደ እግዚአብሔር ጩኹ፤ እርሱም ያድናችኋል፤ ይቅርም ይላችኋል። እንግዲህ አትፍራ፤ ከጥንት ጀምሮ እርሷን አዘጋጅቶልሃልና፤ አንተም ታድናታለህ፤ እርሷም ካንተ ጋራ ትሄዳለች፤ ከእርሷም ልጆችን እንደምትወልድ እነግርሃለሁ፤” ጦብያም ይህን ሰምቶ አደነቀ፤ ልቡም ወደ እርሷ ተሳበ፤ ወደ ባጥናም ደረሱ።'),
  ('c2d1be13-d8eb-572b-a02b-2f72ab074b74', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 1, 1, 'ወደ ራጉኤልም ቤት ደረሱ፤ ሣራም ተቀብላ ደስ አሰኘቻቸው፤ እንዲሁ እነርሱም እርሷን ደስ አሰኙአት፤ ወደ ቤትም አስገባቻቸው።'),
  ('74ef43e4-73f3-5761-a9d9-d50b68e21483', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 2, 2, 'ራጉኤልም ሚስቱ አድናን፥ “ይህ ልጅ ድንቅ ነው፤ ከዘመዶች ወገን የሆነ ጦቢትን ይመስለዋል” አላት።'),
  ('d3886cb4-ecb8-5614-a62e-d772c97ca4d5', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 3, 3, 'ራጉኤልም፥ “ወንድሞቻችን! እናንተ ከወዴት ናችሁ?” አላቸው፤ እነርሱም፥ “ወደ ነነዌ ከተማረኩት ከንፍታሌም ልጆች ነን” አሉት።'),
  ('299f6828-c967-574e-aae3-46259742cbd3', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 4, 4, 'ራጉኤልም፥ “ወንድሜ ጦቢትን ታውቁታላችሁን?” አላቸው፤ እነርሱም፥ “እናውቀዋለን” አሉት። እርሱም፥ “በሕይወት አለን? ደኅና ነውን?” አላቸው።'),
  ('0aa40156-e986-5409-a08b-9c84c0ff2b7d', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 5, 5, 'እነርሱም፥ “አዎ ደኅና ነው” አሉት፤ ጦብያም፥ “አባቴ ነው” አለው።'),
  ('fb227138-3468-52e5-a663-f7f5cc21f9a0', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 6, 6, 'ራጉኤልም ተነሥቶ ሳመው፤ አለቀሰም።'),
  ('c22c6075-3bb7-5caf-af1e-564f684bf558', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 7, 7, '“አንተ የደግ ሰው ልጅ ነህ” ብሎ መረቀው፤ የጦቢትም ዐይኖች እንደ ጠፉ ነገረው። የጦቢትም ዐይኖች እንደ ጠፉ በሰማ ጊዜ አዝኖ አለቀሰ።'),
  ('685f9095-39b3-5c68-ac20-fd26621982d4', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 8, 8, 'ሚስቱ አድናና ልጁ ሣራም አለቀሱ፤ በደስታም ተቀበሉዋቸው፤ በግ አርደውም፥ ማዕድ አቀረቡላቸው፤ እጅግም መሸ። ጦብያም አዛርያን፥ “አንተ ወንድሜ አዛርያ በጎዳና ያልኸኝን ነገር ተናገር፤ ነገሩም ይለቅ፥” አለው።'),
  ('752f1d58-bbd0-5701-af25-0f73c88c2665', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 9, 9, 'ራጉኤልም ጦብያ መልአኩን እንደሚያነጋግረው ሰምቶ ጦብያን አነጋገረው፦ እንዲህም አለው፥ “አንድ ጊዜ ብላ፤ ጠጣ፤ ደስም ይበልህ፤'),
  ('a0454ecc-41cf-50a6-a030-c540178c0ee7', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 10, 10, 'ልጄ ለአንተ ትገባለችና፥ አንተም ታገባታለህና።'),
  ('89162706-7271-589c-a2d4-938b54ae2ad8', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 11, 11, 'እኔም እውነቱን እነግርሃለሁ፤ ይህችን ልጄን ለሰባት ወንዶች አጋባኋት፤ ወደ እርሷም እንደ ገቡ በሌሊት ይሞታሉ፤ ነገር ግን አንድ ጊዜ ደስ ይበልህ፤” ጦብያም፥ “ነገሩን ለኔ እስክትጨርሱልኝ ድረስ፥ ነገሬንም እስክታጸኑልኝ ድረስ በዚህ ምንም አልቀምስም” አለ።'),
  ('404a52f5-e81b-5e42-a71f-064849ca225c', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 12, 12, 'ራጉኤልም አለው፥ “ከአሁን ጀምሮ እንደ ሥርዐቱ ውሰዳት፤ አንተ ወንድሟ ነህና፥ እርሷም እኅትህ ናትና፤ ይቅር ባይ እግዚአብሔርም የሚበጀውን ያከናውንላችሁ።”'),
  ('46e00d66-3934-5871-aa8a-108bbebc1e19', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 13, 13, 'ልጁ ሣራንም ጠራት፤ እጅዋንም ይዞ ሚስት ልትሆነው ለጦብያ ሰጣት፤ “እነሆ በሙሴ ሥርዐት ውሰዳት፤ ወደ አባትህም ቤት አግባት” ብሎ መረቃቸው።'),
  ('b815f3ec-8efa-5a87-a9d0-b500b9805152', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 14, 14, 'ሚስቱ አድናንም ጠራት፤ ወረቀትም ወስዶ ጻፈና አተማት።'),
  ('e20636e1-4270-540a-a116-f64b3ed258f2', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 15, 15, 'ከዚህም በኋላ ይበሉ ጀመሩ።'),
  ('1c71e211-28c5-59f6-a6af-f1114f3b7389', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 16, 16, 'አድናንም ጠርቶ፥ “አንቺ እኅቴ ሌላ የጫጕላ ቤት አዘጋጂ፤ ወደዚያም አግቢያት” አላት።'),
  ('4a882c7c-100f-526d-aea4-ca69ae931cc9', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 17, 17, 'እንዳላትም አደረገች፤ ወደዚያም አገባቻት፤ አለቀሰችም፤ የልጅዋንም እንባ ጠረገች።'),
  ('1b8c3765-a9b6-57e1-a5b4-7f2ca6213df6', '54de3b35-b9be-5b2b-a08d-774eed9078ca', 'fa7556ac-2d7a-5167-a1be-407d31a0befa', 18, 18, '“ስለዚች ኀዘንሽ ፋንታ የሰማይና የምድር ጌታ ደስታን እንደሚሰጥሽ እመኝ” አለቻት።'),
  ('ce74eb94-ff56-5802-a892-215c6ec74f27', 'fef9d310-de19-5470-abcd-7877b42744e0', '79aa81ef-61be-52ad-a3d3-af3b3a10f865', 1, 1, 'ተመግበውም በጨረሱ ጊዜ ጦብያን ወደ እርሷ አገቡት።'),
  ('68abe192-566e-555c-a093-d0f99efb0942', 'fef9d310-de19-5470-abcd-7877b42744e0', '79aa81ef-61be-52ad-a3d3-af3b3a10f865', 2, 2, 'ወደ እርሷም በገባ ጊዜ የሩፋኤልን ነገር አሰበ፤ የዕጣን ዕራሪ ወሰደ፤ ከዚያም ዓሣ ከልቡና ከጉበቱ ጨምሮ አጤሰው።'),
  ('2711ea19-d6cc-576c-a843-8d8d9d3c94ed', 'fef9d310-de19-5470-abcd-7877b42744e0', '79aa81ef-61be-52ad-a3d3-af3b3a10f865', 3, 3, 'ሽታውም ያን ጋኔን በሸተተው ጊዜ እስከ ላይኛው ግብፅ አውራጃ ድረስ ሸሸ። ያም መልአክ ጋኔኑን አሰረው።'),
  ('cf09e89c-9386-536c-a981-8f0a715f61be', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 1, 4, 'ሁለቱም በተዘጋባቸው ጊዜ ጦብያ ከአልጋው ተነሥቶ፥ “እኅቴ ተነሽ፤ እግዚአብሔር ይቅር ይለን ዘንድ እንጸልይ” አላት።'),
  ('7f7a2457-cd11-5b69-a59f-c379f4af73d7', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 2, 5, 'ጦብያም እንዲህ ይል ጀመረ፥ “አቤቱ የአባቶቻችን አምላክ አንተ ቡሩክ ነህ፤ ቅዱስ ስምህም ይባረክ፤ ለዘለዓለሙም ይመሰገናል። ሰማያትና የፈጠርሃቸው ሁሉ ያመሰግኑሃል።'),
  ('f6748a82-dc66-57bf-a01e-d286875bf884', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 3, 6, 'አንተ አባታችን አዳምን ፈጠርኸው፤ ትረዳውና ታሳርፈውም ዘንድ ሔዋንን ሰጠኸው፤ ከእነዚያም የሰው ዘር ተወለደ፤ አንተም አልህ፦ ‘ሰው ብቻውን ይኖር ዘንድ መልካም አይደለምና የሚረዳውን እንፍጠርለት።’'),
  ('c25cf04f-1bde-5e35-a07a-bd94e2b1a293', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 4, 7, 'አሁንም ይህቺን እኅቴን የማገባት በሚገባ ነው እንጂ ስለ ዝሙት አይደለምና አቤቱ አብረን ወደ ሽምግልና እንድንደርስ እንረዳዳ ዘንድ ለእኔና ለእርሷ ይቅርታን ላክልን።”'),
  ('c2340d2b-fc47-5e25-a4fd-93ee76dd6446', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 5, 8, 'እርሷም ከእርሱ ጋር “አሜን” አለች።'),
  ('e5fbb795-cea0-5542-a211-41b0d9dc2656', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 6, 9, 'ሁለቱም በዚያች ሌሊት አብረው አደሩ።'),
  ('b9e6e1f7-2a5e-52b0-a8e2-4b371c16d9f3', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 7, 10, 'ከዚህም በኋላ ራጉኤል ተነሥቶ ሄደ፤ እርሱም “ምናልባት ይሞት ይሆናል” ብሎ መቃብር ቈፈረ።'),
  ('12dce0b5-710f-51ff-abb3-89d74393cea3', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 8, 11, 'ራጉኤልም ወደ ቤቱ ተመለሰ።'),
  ('cf096681-8ea0-55c8-ade8-5d2e22d63998', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 9, 12, 'ሚስቱ አድናንም አላት፥ “ደኅና እንደ ሆነ ታየው ዘንድ አንዲት ልጅ ላኪ፤ ሞቶም እንደ ሆነ ማንም ሳያውቅ እንቀብረዋለን።”'),
  ('a5ca4894-12e3-540e-aeea-9da8a084fe27', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 10, 13, 'ያቺም ልጅ ሄዳ ደጃፉን ከፈተች፤ ሁለቱም ተኝተው አገኘቻቸው።'),
  ('97330021-74f5-58ba-afbf-d47289938486', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 11, 14, 'ተመልሳም እርሱ ደኅና እንደ ሆነ ነገረቻቸው።'),
  ('8ff3aa34-9c10-541d-a43d-4c58d1e6e37c', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 12, 15, 'ራጉኤልም እግዚአብሔርን አመሰገነው፤ እንዲህም አለ፥ “አቤቱ አንተ የተመሰገንህ ነህ፤ ንጽሕትና ቅድስት በሆነች ምስጋና ሁሉ የተመሰገንህ ነህ። ጻድቃንህ፦ በሠራኸው ሥራ ሁሉ ያመሰግኑሃል፤ መላእክትህና የመረጥኻቸውም ሁሉ ለዘለዓለም ያመሰግኑሃል።'),
  ('9d4b32b7-95ed-5bf3-a5ce-7cb1e11280e3', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 13, 16, 'ደስ አሰኝተኸኛልና አቤቱ አንተ የተመሰገንህ ነህ፤ እንደ ጠረጠርሁት አልተደረገብኝም፤ ነገር ግን እንደ ቸርነትህ ብዛት አደረግህልኝ።'),
  ('1559b9fd-b73b-5091-a5fe-d668f5dcf5fe', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 14, 17, 'አንተ ቡሩክ ነህ፤ ሁለቱን ብቸኞች ይቅር ብለሃቸዋልና፥ ዘመናቸውን በደኅንነትና በደስታ፥ በቸርነትህ ይፈጽሙ ዘንድ አቤቱ በጎነትን አድርገህላቸዋልና።”'),
  ('0750fecf-5a74-5728-a3f9-af74cbdfe327', 'fef9d310-de19-5470-abcd-7877b42744e0', '137c05e3-9d84-56dd-a3f0-a0b2930bfe2a', 15, 18, 'ከዚያም በኋላ ራጉኤል ያን መቃብር ይደፍኑ ዘንድ አገልጋዮቹን አዘዛቸው።'),
  ('ebafdfa5-4d00-544b-a79b-65c5fac68606', 'fef9d310-de19-5470-abcd-7877b42744e0', '57845cc5-7fef-5c4d-a684-b30441266580', 1, 19, 'ከዚህም በኋላ ዐሥራ አራት ቀን በዓል አደረገላቸው።'),
  ('0e9b3312-2191-54c6-a32c-598ee0410428', 'fef9d310-de19-5470-abcd-7877b42744e0', '57845cc5-7fef-5c4d-a684-b30441266580', 2, 20, 'ራጉኤልም የሠርጉ ዐሥራ አራት የበዓል ቀን እስኪፈጸም ድረስ ወጥቶ እንዳይሄድ ጦብያን አማለው።'),
  ('bd60eb2e-3063-5a75-a6f9-96fe1bf630a8', 'fef9d310-de19-5470-abcd-7877b42744e0', '57845cc5-7fef-5c4d-a684-b30441266580', 3, 21, 'ከዚህም በኋላ ሄዶ የገንዘቡን እኩሌታ ይወስድ ዘንድ፥ ወደ አባቱም በደኅና ይሄድ ዘንድ፥ የተረፈውን ግን እርሱና ሚስቱ ከሞቱ በኋላ ይወስድ ዘንድ አስማለው።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4320ff51-6217-5459-ab23-41e4c2b0f8be', '9f1d186a-76c1-5b27-a005-3137e6bdb2c2', '527e4576-8bd3-5355-a831-468968fed97e', 1, 1, 'ጦብያም ሩፋኤልን ጠርቶ እንዲህ አለው፦'),
  ('d5ce166c-ef00-5ed6-aa0a-de3efe468558', '9f1d186a-76c1-5b27-a005-3137e6bdb2c2', '527e4576-8bd3-5355-a831-468968fed97e', 2, 2, '“አንተ ወንድሜ አዛርያ ሆይ፥ ሁለት ብላቴኖችንና ግመሎችን ይዘህ የሜዶን ክፍል ወደምትሆን ወደ ራጊስ ወደ ገባኤል ቤት ሂድ፤ የብሩንም መክሊት አምጣ። እርሱንም ወደ ሰርጉ በዓል ጥራው።'),
  ('d7946025-c847-56f8-af6f-e9693c7a5302', '9f1d186a-76c1-5b27-a005-3137e6bdb2c2', '527e4576-8bd3-5355-a831-468968fed97e', 3, 3, 'የሰርጉ በዓል ሳያልቅ እንዳልወጣ ራጉኤል አምሎኛልና።'),
  ('75f64897-cea7-5050-a68c-91205c7c7ecf', '9f1d186a-76c1-5b27-a005-3137e6bdb2c2', '527e4576-8bd3-5355-a831-468968fed97e', 4, 4, 'አባቴ ግን ቀኑን ይቈጥራል፤ ብዘገይም ፈጽሞ ያዝናል።”'),
  ('f5bfc810-d694-560f-a759-c6756782a9b9', '9f1d186a-76c1-5b27-a005-3137e6bdb2c2', '527e4576-8bd3-5355-a831-468968fed97e', 5, 5, 'ሩፋኤልም ሄደ፤ በገባኤልም ቤት አደረ፤ ደብዳቤውንም ሰጠው፤ እነዚያንም ከረጢቶች እንደታተሙ አምጥቶ ለሩፋኤል ሰጠው።'),
  ('ecc98fd3-594a-52a6-a555-03e3e016fced', '9f1d186a-76c1-5b27-a005-3137e6bdb2c2', '527e4576-8bd3-5355-a831-468968fed97e', 6, 6, 'በጧትም በአንድነት ገሥግሠው ሄዱ፤ ወደ ሰርጉም ደረሱ፤ ጦብያም ያን ብር ባመጣለት ጊዜ ሩፋኤልን መረቀው።'),
  ('83768dfe-ebed-5b2d-a4cc-8a2e2ee477c9', '0379c2cb-91e8-5189-a109-f5e3f0336af0', 'f8624501-bad8-5170-a6b9-eef27aa97da8', 1, 1, 'አባቱ ጦቢት ግን ቀኑን ይቈጥር ነበር። ቀጠሮውም አልቆ ሳይመጡ በቀሩ ጊዜ፥'),
  ('9f1595e0-3f76-53c1-a447-dd712a710c10', '0379c2cb-91e8-5189-a109-f5e3f0336af0', 'f8624501-bad8-5170-a6b9-eef27aa97da8', 2, 2, 'እንዲህ አለ፥ “ምናልባት እነሆ፥ ልጄ ታስሮ ይሆን? ወይስ ገባኤል ሞቶ ብሩን የሚሰጠው አላገኘ ይሆን?”'),
  ('147b2ca8-b89f-569e-af04-b8ff0490e193', '0379c2cb-91e8-5189-a109-f5e3f0336af0', 'f8624501-bad8-5170-a6b9-eef27aa97da8', 3, 3, 'እጅግም አዘነ።'),
  ('1dd828e7-5d8f-5352-a838-5e24df57c213', '0379c2cb-91e8-5189-a109-f5e3f0336af0', 'f8624501-bad8-5170-a6b9-eef27aa97da8', 4, 4, 'ሚስቱም፥ “ልጄስ ሞትዋል፤ ስለዚህም ነገር ዘገየ” አለችው።'),
  ('bc100833-ecb0-544e-a70c-06b0a816f579', '0379c2cb-91e8-5189-a109-f5e3f0336af0', 'f8624501-bad8-5170-a6b9-eef27aa97da8', 5, 5, 'እንዲህም እያለች ታለቅስ ጀመረች፤ “ያይኔን ብርሃን ልጄን ያጠፋህብኝ ባይሆን ባላሳዘነኝም ነበር።”'),
  ('299939ee-b65a-590c-a4f2-312005bc9219', '0379c2cb-91e8-5189-a109-f5e3f0336af0', 'f8624501-bad8-5170-a6b9-eef27aa97da8', 6, 6, 'እርሱም፥ “ዝም በዪ፤ አትጨነቂ፤ እርሱስ ደኅና ነው” አላት።'),
  ('ec0b5a17-5dd1-5c18-a22d-4dae5bed82cd', '0379c2cb-91e8-5189-a109-f5e3f0336af0', 'f8624501-bad8-5170-a6b9-eef27aa97da8', 7, 7, 'እርሷም አለችው፥ “አንተም ዝም በል፤ አታታለኝ፤ ልጄስ ሞትዋል።” ታለቅስለትም ዘንድ በሄደበት ጎዳና ሁልጊዜ ትሄድ ነበር። የሰርጉ በዓል ሳያልቅ እንዳይሄድ ራጉኤል ያማለው ዐሥራ አራቱ የበዐዓል ቀን እስኪፈጸም ድረስ ለልጅዋ ለጦብያ እያለቀሰችለት በቀን እህል አትበላም ነበር፤ በሌሊትም ዝም አትልም ነበር።'),
  ('8ca34ed3-deb2-507f-a13a-c47f3b73fa42', '0379c2cb-91e8-5189-a109-f5e3f0336af0', '56e90f86-cdc1-5297-a46a-b22e4895f7a8', 1, 8, 'ከዚህ በኋላ የሰርጉ በዐል ባለቀ ጊዜ ጦብያ ራጉኤልን አለው፥ “እንግዲህስ ወዲያ አሰናብተኝ፤ አባቴና እናቴ ተስፋ ቈርጠዋልና እንግዲህ ወዲህም ያዩኝ ዘንድ ተስፋ አያደርጉምና፥”'),
  ('74c03ada-8598-5180-a376-990fb8c63575', '0379c2cb-91e8-5189-a109-f5e3f0336af0', '56e90f86-cdc1-5297-a46a-b22e4895f7a8', 2, 9, 'አማቱም፥ “በእኔ ዘንድ ተቀመጥ፤ ወሬህን ይነግሩት ዘንድ እኔ ወደ አባትህ እልካለሁ” አለው።'),
  ('020c712b-5f3d-5c55-aa35-98057143995c', '0379c2cb-91e8-5189-a109-f5e3f0336af0', '56e90f86-cdc1-5297-a46a-b22e4895f7a8', 3, 10, 'ጦብያም፥ “አይሆንም፥ ወደ አባቴ እሄድ ዘንድ አሰናብተኝ እንጂ” አለው።'),
  ('04de169a-bd9b-5734-a1ab-b6c777184fcf', '0379c2cb-91e8-5189-a109-f5e3f0336af0', '56e90f86-cdc1-5297-a46a-b22e4895f7a8', 4, 11, 'ራጉኤልም ተነሥቶ ሚስቱ ሣራንና፥ የገንዘቡን እኩሌታ፥ አገልጋዮችን፥ ከብቶችንም፥ ብሩንም ሰጠው።'),
  ('ed20a897-bf6e-530c-a827-3dfbc887911d', '0379c2cb-91e8-5189-a109-f5e3f0336af0', '56e90f86-cdc1-5297-a46a-b22e4895f7a8', 5, 12, 'እርሱም፥ “ልጆች ሆይ፥ ሳልሞት የሰማይ ጌታ በጎ ነገር ያድርግላችሁ” ብሎ መረቃቸው፤ ልጁንም እንዲህ አላት፥ “አማቶችሽን አክብሪ፤ እንግዲህ ወዲህ ዘመዶችሽ እነርሱ ናቸውና፤ እኛም በአንቺ መልካሙን እንስማ” ብሎ ሳማት። አድናም ጦብያን አለችው፥ “አንተ የምወድህ ወንድሜ ሆይ፥ የሰማይ ጌታ ከልጄ ከሣራ ልጆችን ሰጥቶህ አይልህ ዘንድ፥ በእግዚአብሔርም ፊት ደስ ይለኝ ዘንድ ጎዳናህን ያቅናልህ። እነሆ፥ ልጄን አደራ ሰጥቼሃለሁ፤ አታሳዝናት።”'),
  ('45f0f6d6-d79c-5224-abbd-c16c9aeb0418', '0379c2cb-91e8-5189-a109-f5e3f0336af0', '56e90f86-cdc1-5297-a46a-b22e4895f7a8', 6, 13, 'ከዚህም በኋላ ጦብያ ሄደ፤ እግዚአብሔርንም አመሰገነው፤ መንገዱን አቅንቶለታልና። ራጉኤልና ሚስቱ አድናም አመሰገኑት፤ እነርሱም ሄዱ፤ ወደ ነነዌም ቀረቡ።'),
  ('1e628b53-9386-58fb-afa6-3ba015111581', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '7a6d105b-572f-5c8f-a3fa-ff210d37c2c7', 1, 1, 'ከዚህም በኋላ ሩፋኤል ጦብያን አለው፥ “አንተ ወንድሜ አባትህን እንዴት እንደ ተውኸው አታውቅምን?'),
  ('ce9d0232-1500-5332-a88c-035a653eaeaa', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '7a6d105b-572f-5c8f-a3fa-ff210d37c2c7', 2, 2, 'ና ከሚስትህ ቀድመን ሄደን ቤቱን እናዘጋጅ።'),
  ('19f91af2-6170-5f7a-a627-ecfcfdfa8dfa', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '7a6d105b-572f-5c8f-a3fa-ff210d37c2c7', 3, 3, 'የዚህንም ዓሣ ሐሞት ያዝ፤” ያም ከእነርሱ ጋር የተከተለው ብላቴና ከእነርሱ ጋር ሄደ።'),
  ('6f8da4c3-8378-53a7-ac07-17c5bb6da306', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '7a6d105b-572f-5c8f-a3fa-ff210d37c2c7', 4, 4, 'ሐና ግን በጎዳና ተቀምጣ ልጅዋን ታይ ዘንድ ትመለከት ነበር።'),
  ('abb2a9ff-aef8-52be-aabf-c8440efdce52', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '7a6d105b-572f-5c8f-a3fa-ff210d37c2c7', 5, 5, 'ሲመጣም አየችው፤ ሄዳም አባቱን፥ “እነሆ፥ ልጅህ መጣ፤ ከእርሱም ጋር የሄደው ያ ሰው መጣ” አለችው።'),
  ('08028a5b-3119-56d7-ae03-14babdb1ff44', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 1, 6, 'ሩፋኤልም አለው፥ “ያባትህ ዐይኖች እንዲበሩ አውቃለሁ፤'),
  ('fa2ea20f-b684-51cd-a24d-f8d23285a23e', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 2, 7, 'አንተ ግን ያን ሐሞት ያባትህን ዐይን ኳለው፤ በተኳለም ጊዜ ዐይኖቹን ያሻል፤ ብልዙም ከዐይኑ ይወጣል፤ በደኅናም ያያል።”'),
  ('fafa2d9d-8a63-5988-a96f-92f882cc8cd8', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 3, 8, 'ሐናም ሮጣ የልጅዋን አንገት አቅፋ፥ “ልጄ ሆይ፥ ካየሁህ እንግዲህ ልሙት” አለችው፤ ሁለቱም አለቀሱ።'),
  ('38bc2f6d-84cd-54d7-ab50-177acec71a54', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 4, 9, 'ጦቢትም ወደ ደጅ ወጣ፤ ተሰነካከለም፤ ልጁም ሮጦ አባቱን አነሣው።'),
  ('3935491e-33c6-5091-a97a-1f258d41a56d', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 5, 10, 'የአባቱንም ዐይኖች በዚያ ሐሞት ኳለና፥ “አባቴ ሆይ፥ እንደምትድን ታመን” አለው።'),
  ('766f9dea-22e4-5bdc-abd9-f5c81784846f', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 6, 11, 'በኳለውም ጊዜ ዐይኖቹን አሸ።'),
  ('0cc00739-7325-5add-ace0-b1d3cae7b4d7', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 7, 12, 'ብልዙም ከዐይኑ ብሌን ተገፈፈ፤ ልጁንም አየው፤ አንገቱንም አቅፎ አለቀሰ።'),
  ('2e5f0870-fea6-5299-ae9e-e6a500e70461', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 8, 13, 'እንዲህም አለ፥ “ጌታ ሆይ፥ የተመሰገንህ ነህ፤ ስምህም ለዘለዓለሙ ይመስገን፤ ቅዱሳን መላእክትህም ሁሉ ቡሩካን ናቸው፤ ገርፈህ ይቅር ብለኸኛልና።'),
  ('4a7a83d6-5d81-507c-a8b1-2dcb235adf2d', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 9, 14, 'እነሆም፥ ልጄ ጦብያን አየሁት፤” ከዚህም በኋላ ልጁ ደስ እያለው ገባ፤ ለአባቱም በሜዶን የተደረገለትን ታላላቅ ነገር ሁሉ ነገረው።'),
  ('7fc07838-1ab7-51d4-a8da-576fbc62f458', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 10, 15, 'ጦቢትም ደስ እያለው ወጥቶ ምራቱን ተቀበላት፤ እግዚአብሔርንም በነነዌ አደባባይ አመሰገነው፤ ሲሄድም ያዩት ሰዎች፥ “እንዴት አየ?” ብለው አደነቁት።'),
  ('6078f39f-15b7-52ef-ac6e-bf897b4504fd', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 11, 16, 'ጦቢት ግን በፊታቸው እግዚአብሔርን አመሰገነ፤ እግዚአብሔር ይቅር ብሎታልና። ጦቢትም ወደ ምራቱ ወደ ሣራ በደረሰ ጊዜ፥ “ልጄ! እንኳን በደኅና ገባሽ!” ብሎ መረቃት፤ ወደ እኛ ያመጣሽ እግዚአብሔርም ይመስገን፤ አባትሽንና እናትሽንም ይባርክ” አላት። በነነዌም ለሚኖሩ ለወንድሞቹ ሁሉ ታላቅ ደስታ ሆነ።'),
  ('149604c7-b11a-5b84-ab17-7e4debd0bf62', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 12, 17, 'አኪአክሮስም መጣ፤ የወንድሙ ልጅ ነሳቦስም መጣ።'),
  ('975eac57-3f3b-52fd-a164-0bec0b3cccc6', 'f616abe0-114e-50ec-a0be-ee9973dc03c5', '9d40e6e6-e7c8-54b8-aae2-5822c85cd9b4', 13, 18, 'ሰባት ቀንም በደስታ የሰርግ በዐል አደረጉ።'),
  ('e7375909-c97a-5a6c-a0e8-940bf66f57b8', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 1, 1, 'ከዚህም በኋላ ጦቢት ጦብያን ጠርቶ፥“ ልጄ ሆይ፥ ከአንተ ጋራ የሄደ የዚህን ሰው ደመወዙን እይለት፤ ዳግመኛም ትጨምርለት ዘንድ ይገባል” አለው።'),
  ('9809be7c-31bd-568c-a030-77dbcfee046a', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 2, 2, 'ጦብያም አባቱን እንዲህ አለው፥ “ያመጣሁትን የገንዘቤን እኩሌታ ስንኳ ብሰጠው የሚጐዳኝ የለም።'),
  ('b1690a20-89fb-500e-acbe-fa7b2296ff41', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 3, 3, 'ወደ አንተ በደኅና መልሶኛልና፥ ሚስቴንም ፈውሷታልና፤ ብሩንም አምጥቶልኛልና፤ እንዲሁም አንተን ፈውሶሃልና።”'),
  ('62a2e035-16bb-56a3-ab74-797c2ec1ac2d', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 4, 4, 'አባቱም፥ “እውነት ተናገርህ” አለው።'),
  ('578462d7-7cd9-5c15-a36f-1a1740eef8eb', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 5, 5, 'ያንም መልአክ ጠርቶ እንዲህ አለው፥ “ከእናንተ ጋር ካመጣችሁት ሁሉ እኩሌታውን ይዘህ በደኅና ሂድ።”'),
  ('1f12cf1a-ebbe-52ee-af18-e06e99831486', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 6, 6, 'ሩፋኤልም ያንጊዜ ሁለቱን ሁሉ ጠራቸው፤ ገለል አድርጎም እንዲህ አላቸው፥ “እግዚአብሔርን አመስግኑት፤ ለእርሱም ተገዙ፤ ለስሙም ምስጋና አቅርቡ፤ ስላደረገላችሁም በጎ ነገር ሁሉ በሰው ሁሉ ፊት እመኑበት፤ እግዚአብሔርን አመስግኑት፤ ስሙንም አመስግኑ፤ የእግዚአብሔርንም ሥራ በክብር ተናገሩ፤ ተአምራቱንም ግለጡ፤ እርሱንም ከማመስገን ቸል አትበሉ።'),
  ('ea989661-76b2-5539-a330-1728c9c89259', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 7, 7, 'የመንግሥትን ምሥጢር ሊሰውሩት፥ የእግዚአብሔርን ሥራ ግን በክብር ሊገልጡት ይገባልና፤ መከራም እንዳታገኛችሁ በጎ ሥራን ሥሯት።'),
  ('3e94ffb7-7276-5589-a683-87acdea0f435', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 8, 8, 'ጸሎት ከጾም፥ ከምጽዋትና ከጽድቅ ጋር መልካም ነው። ከብዙ የዓመፅ ገንዘብ ጥቂት የእውነት ገንዘብ ይሻላል፤ ወርቅንም ከማድለብ ምጽዋት መስጠት ይሻላል።'),
  ('1c3489fc-a7c4-5824-a6b6-73f648ed2cc1', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 9, 9, 'ምጽዋት ከሞት ታድናለች፤ ከኀጢአትም ሁሉ ታነጻለችና፥ ጽድቅንና ምጽዋትን የሚያደርጉም ሁሉ ለራሳቸው ሕይወትን ይሞላሉ።'),
  ('9d50cd6d-8ba7-51b1-a141-f16201820f25', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 10, 10, 'የሚበድሉ ግን ሕይወታቸውን ይጠሏታል።'),
  ('239dd3ce-5f3d-5098-a399-5912775ba439', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 11, 11, '“እነሆ፥ ነገሩን ሁሉ ከእናንተ አልሰውርም፤ የመንግሥትን ምሥጢር ሊሰውሩት የእግዚአብሔርን ሥራ ግን በክብር ሊገልጡት መልካም እንደ ሆነ እነግራችኋለሁ።'),
  ('54bd9efb-d164-54cf-a8f6-5bbea4e64a66', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 12, 12, 'እነሆ፥ አንተና ምራትህ ሣራ በጸለያችሁ ጊዜ የልመናችሁን መታሰቢያ እኔ በቅዱሱ ፊት አቀረብሁ፤ አንተም ሬሳ በቀበርህ ጊዜ ያንጊዜ እኔ ካንተ ጋራ ነበርሁ።'),
  ('0525b533-7403-5ce0-a215-aa32deef469d', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 13, 13, 'ቸል ባላልህ ጊዜ፥ ምሳህንም ትተህ በተነሣህ ጊዜ፥ ሬሳንም ትቀብር ዘንድ በሄድህ ጊዜ፥ በጎ ሥራን መሥራትንም ባልዘነጋህ ጊዜ እኔ ከአንተ ጋር ነበርሁ።'),
  ('2464fd0c-a767-592e-a6b9-3ce9f1893ef9', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 14, 14, 'አሁንም፦ ጌታ እግዚአብሔር አንተን አድንህ ዘንድ፥ ምራትህ ሣራንም ከኀዘኗ አረጋጋት ዘንድ ላከኝ።'),
  ('e0779e74-4fbd-5322-a006-05f331e0d7ee', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 15, 15, 'የቅዱሳንን ጸሎት ከሚያሳርጉ፥ በገናናውና በቅዱሱ ጌትነት ፊት ከሚያቀርቡ ሰባቱ ቅዱሳን መላእክት አንዱ መልአክ እኔ ሩፋኤል ነኝ” አላቸው።'),
  ('269476c4-1713-5ed7-a490-8e1239612dbb', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 16, 16, 'ይህንም ሰምተው ሁለቱ ደነገጡ፤ ፈርተዋልምና በግምባራቸው ወደቁ።'),
  ('174dce9d-7954-53c7-aab5-45dacd811849', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 17, 17, 'መልአኩም እንዲህ አላቸው፥ “አትፍሩ፤ ነገር ግን አምላካችሁ እግዚአብሔርን ፍሩት፥ እግዚአብሔርንም ፈጽማችሁ አመስግኑት፤'),
  ('35d838c6-4003-5afa-aad1-81647f94c6f2', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 18, 18, 'ምስጋና ለእኔ አይገባኝምና፥ ነገር ግን የአምላካችሁ ፈቃድ አመጣኝ፤ ስለዚህም በዘመናት ሁሉ ለዘለዓለሙ እግዚአብሔርን አመስግኑት።'),
  ('42768d5f-3100-5bf7-a448-7e4e1d5b4826', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 19, 19, 'እኔም ተገለጥሁላችሁ፤ ነገር ግን እይታን አያችሁ እንጂ ከእናንተ ጋር አልበላሁም፤ አልጠጣሁምም።'),
  ('5b97be01-6b64-5490-a837-5f4d74acd6ad', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 20, 20, 'አሁንም በእግዚአብሔር እመኑ፥ ወደ ላከኝም ወደ ላይ እወጣለሁና ይህን ሁሉ በመጽሐፍ ጻፉት” አለ።'),
  ('ddc6d549-5781-5592-aa97-35ca9a768a00', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 21, 21, 'ያን ጊዜም ተነሥቶ ሄደ፤ ከዚያ በኋላም አላዩትም።'),
  ('9494ae8e-cf69-53c4-aa64-5837986db55f', 'be95bbde-646f-5222-ae00-d34a6dc76dd4', 'e40f3222-5359-564f-aa33-9bbf86d8f212', 22, 22, 'የእግዚአብሔርም መልአክ ስለ ተገለጸላቸው፥ ገናናና ድንቅ በሚሆን በእግዚአብሔር ሥራ ሁሉ አመኑ።'),
  ('4803106c-9918-5b9b-a4a4-946567262ca1', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 1, 1, 'ጦቢትም የደስታ መጽሐፍን ጻፈ፤ እንዲህም አለ፥ “ለዘለዓለሙ ሕያው የሚሆን፥ መንግሥቱም ለዘለዓለሙ የሆነ እግዚአብሔር ይመስገን።'),
  ('2a2ebeea-93a6-5eca-a921-49b6c2f1bc69', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 2, 2, 'እርሱ ይገርፋል፤ ይቅርም ይላል፤ እርሱ ወደ ሲኦል ያወርዳል፤ ያወጣልም፤ ከእጁም የሚያመልጥ የለም።'),
  ('bc881e2b-74ab-5e40-a2ac-807d42378a1e', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 3, 3, 'እናንተ የእስራኤል ልጆች ሁሉ፥ እርሱ በመካከላቸው በበተነን በአሕዛብ ሁሉ ፊት ተገዙለት።'),
  ('4bcff75a-5a2f-52d1-a470-db00f0e2b37a', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 4, 4, 'በዚያም ገናናነቱን ገለጠላችሁ፤ በሰው ሁሉ ፊትም አክብሩት፤ እርሱ ጌታችን ነውና፥ እርሱ እግዚአብሔር ለዘለዐለም አባታችን ነውና።'),
  ('efa5cbc9-f43e-5346-a29d-12184a566f94', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 5, 5, 'በኀጢአታችን ይገርፈናል፤ ዳግመኛም ይቅር ይለናል፤ በመካከላቸው ከበተነን ከአሕዛብም ሁሉ ይሰበስበናል።'),
  ('919b5ee0-2624-58b3-a785-f382a921089b', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 6, 6, '“በፊቱ እውነትን ትሠሩ ዘንድ በፍጹም ልባችሁ፥ በፍጹም ነፍሳችሁም ወደ እርሱ ከተመለሳችሁ ያን ጊዜ እርሱ ወደ እናንተ ይመለሳል። ፊቱንም ከእናንተ አይሰውርም። ከእናንተ ጋር ያደረገውን ታያላችሁ። በፍጹም ልባችሁ፥ በፍጹም ነፍሳችሁም እመኑበት፤ ጻድቅ እግዚአብሔርን አመስግኑት፤ የዘለዓለምን ንጉሥ በተማረካችሁበት ሀገር ከፍ ከፍ አድርጉት፤ እኔም በተማረክሁበት ሀገር አምንበታለሁ፤ ኀጢአተኞች ለሆኑ ለአሕዛብም ኀይሉንና ገናናነቱን እናገራለሁ። እናንተ ኀጢአተኞች፥ ተመልሳችሁ በፊቱ እውነትን ሥሯት፤ ወድዶም ቸርነቱን ለእናንተ ያደርግላችሁ እንደ ሆነ ማን ያውቃል?'),
  ('4dcbd49f-3645-5e2d-acf4-8f67072c2711', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 7, 7, 'ፈጣሪዬን ከፍ ከፍ አደርገዋለሁ። ሰውነቴም የሰማይን ንጉሥ እግዚአብሔርን ታመሰግነዋለች።'),
  ('b2212224-b23b-56cf-a420-1d0a3c88a6c2', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 8, 8, 'ገናናነቱንም በሁሉ ዘንድ እናገራለሁ።'),
  ('e304348b-99b0-5c53-a722-fc2085327972', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 9, 9, '“ቅድስት ከተማ ኢየሩሳሌም ሆይ፥ በልጆችሽ ኀጢአት በመከራ አይቀሥፍሽምን? ዳግመኛም ደጋግ ለሆኑ ልጆችሽ ይራራላቸዋል።'),
  ('56ccc5ee-ee17-55b5-ab21-2a6178439add', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 10, 10, 'በበጎ ሥራ ለእግዚአብሔር ተገዢ፤ ባንቺም ዘንድ ድንኳኑ በደስታ እንድትሠራ የዘለዓለሙን ንጉሥ አመስግኚ፤ በዚያም ያሉ የተማረኩ ሰዎች ደስ ይላቸዋል። በዘለዓለማዊ ትውልድም ሁሉ የተጠሉ በአንቺ ምክንያት ይወደዳሉ።'),
  ('cbbcbae6-2aed-5f68-a00e-897c1e33ac87', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 11, 11, '“ብዙ አሕዛብ ከሩቅ ወደ ፈጣሪ እግዚአብሔር ስም ይመጣሉ፤ ለሰማይ ንጉሥም እጅ መንሻን ያመጣሉ፥ ትውልድም ሁሉ ያመሰግኑሃል፤ ለስምህም ምስጋናን ያቀርባሉ።'),
  ('c6c90b1e-3196-5a44-a8c8-10c98ee6c85c', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 12, 12, 'የሚጠሉህ ሁሉ የተረገሙ ናቸው፤ የሚወድዱህ ሁሉ ግን ለዘለዓለሙ የተባረኩ ናቸው።'),
  ('d3498fe4-8073-5edf-a6d4-9e0eeba63174', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 13, 13, 'በጻድቃን ልጆች ደስ ይልሃል፤ አቤቱ፥ በአንድነት ተሰብስበው የጻድቃንን ጌታ አንተን ያመሰግናሉና፥ የሚወድዱህ ብፁዓን ናቸውና፤ በሰላምህም ደስ ይላቸዋል።'),
  ('1131e2d7-fb9c-54e5-a916-0860839d8ab9', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 14, 14, 'ስለ መከራህ የሚያዝኑ ሁሉ ብፁዓን ናቸው፤ ክብርህን ሁሉ አይተው በአንተ ደስ ይላቸዋልና፤ ለዘለዓለሙም ደስ ይላቸዋል።'),
  ('c9b87fd6-1ad0-5edf-af5d-80b76cd559fc', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 15, 15, '“ሰውነቴ ገናና ንጉሥ እግዚአብሔርን ታመሰግነዋለች።'),
  ('c15ddcca-eb63-52ed-a012-9b94921cded5', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 16, 16, 'ኢየሩሳሌም ሰንፔር በሚባል ዕንቍ ትሠራለችና፥ ግድግዳዋ በመረግድና በከበረ ዕንቍ፥ አዳራሽዋና በሮችዋ በጠራ ወርቅ ይሠራሉና።'),
  ('92eb671e-78ba-5cbc-a75c-3a9d752f8ea3', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 17, 17, 'የኢየሩሳሌም አደባባይም በቢሬሌ፥ በአትራኮስ ዕንቍና በሶፎር ዕንቍ ይሠራልና።'),
  ('7ab7c50c-f4f1-50cf-a55f-1ff7920a027c', 'd0271450-15f0-5f1f-a561-391601119e27', '75ebc153-3418-509b-a6e5-3a617643fa05', 18, 18, 'በጎዳናዋ ሁሉ ሃሌ ሉያ ይላሉ፤ እያመሰገኑም እንዲህ ይላሉ፥ “እግዚአብሔር ለዘለዓለም እስከ ዘለዓለም ይመስገን።”'),
  ('ebaddf5f-1e37-53c4-a7f2-e6e9f680fccf', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 1, 1, 'ከዚህ በኋላ ጦቢት ከመጸለይ ዝም አለ፤'),
  ('b1585664-5ab5-5221-aff7-45b1145ac559', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 2, 2, 'ዐይኑም በጠፋ ጊዜ አምሳ ስምንት ዓመት ሆኖት ነበር። ከስምንት ዓመት በኋላም አየ፤ ምጽዋትም መጸወተ፤ ጌታ እግዚአብሔርን መፍራትንም ጨመረ፤ በእርሱም አመነ።'),
  ('d79fa1ba-d6ea-5462-a3fd-96cfa9b01fb6', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 3, 3, 'ፈጽሞ አረጀ፤ ልጁንና የልጁንም ልጆች ጠራቸው፤ እንዲህም አላቸው፥ “አርጅቻለሁና፥ ለሞትም ደርሻለሁና ልጆችህን አምጣቸው።”'),
  ('e02b2267-73ef-5689-ac37-44c41b10b406', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 4, 4, 'ልጄ፥ ወደ ሜዶን ሂድ፤ ትጠፋ ዘንድ እንዳላት ነቢዩ ዮናስ በነነዌ የተናገረውን ነገር ሁሉ አውቃለሁና፤ በሜዶን ግን እስከ ዘመኑ ድረስ ሰላም ይሆናል። ወንድሞቻችንም ከተባረከች ምድር ሁሉ ወደየሀገሩ ይበተኑ ዘንድ አላቸው፤ ኢየሩሳሌምም ምድረ በዳ ትሆናለች፤ በእርስዋም ያለ የእግዚአብሔር ቤት ይቃጠላል፤ እስከ ዘመኑም ድረስ ምድረ በዳ ይሆናል።'),
  ('31876f04-76dc-5a16-a574-ae527160e57a', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 5, 5, 'ዳግመኛም እግዝአብሔር ይቅር ብሎ ወደ ሀገራቸው ይመልሳቸዋል፤ ማደሪያው ቤተ መቅደስንም ይሠራሉ፤ የዘመኑ ቍጥር እስከሚፈጸም ነው እንጂ እንደ ቀድሞው አይደለም፤ ከዚህም በኋላ ከተማረኩበት ይመለሳሉ፤ ኢየሩሳሌምንም በክብር ይሠሯታል፤ በእርሷም የእግዚአብሔርን ቤት እስከ ልጅ ልጅ ዘመን ድረስ በዕብነ በረድ ይሠራሉ።'),
  ('4fc9ee76-c355-5d42-a8e4-ac149b149b84', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 6, 6, 'አሕዛብም ሁሉ በእውነት ወደ እርሱ ይመለሳሉ፤ እግዚአብሔርንም ይፈሩታል፤ ጣዖቶቻቸውንም ይጥላሉ።'),
  ('fec2a450-5b47-541d-a498-64871a043d18', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 7, 7, 'አሕዛብ ሁሉ እግዚአብሔርን ያመሰግኑታል። ሕዝቡም በእርሱ ያምናሉ፤ እግዚአብሔርም ወገኖቹን ከፍ ከፍ ያደርጋቸዋል። በእውነትና በቅንነት እግዚአብሔርን የሚፈሩ ሰዎች ሁሉ ደስ ይላቸዋል፤ ለወንድሞቻቸውም ቸርነትን ያደርጋሉ።'),
  ('5fe1c457-ab2c-5992-ae98-f152ad11c3f5', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 8, 8, '“ልጄ ሆይ! አሁንም ከነነዌ ውጣ፤ ነቢዩ ዮናስ የተናገረው ነገር በግድ ይደረጋልና።'),
  ('cfd8e315-c051-53d2-a2af-a4ef18e64a4e', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 9, 9, 'አንተ ግን ትእዛዙንና ሕጉን ጠብቅ፤ ይቅር ባይም ሁን፤ በጎ ይደረግልህ ዘንድ እውነትን ውደድ።'),
  ('03d87b5b-fe64-529c-acd2-87177bc42df0', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '18e8851f-02ba-5a63-aa0f-8d5df09f65a1', 10, 10, 'አክብረህ ቅበረኝ፤ እናትህንም ከእኔ ጋር ቅበራት። ልጄ፥ በነነዌ አትቈይ። ሐማ በዘመድህ በአኪአክሮስ ያደረገውን፥ ከብርሃን ወደ ጨለማ እንዳገባው፥ ፍዳውንም እንደ ተቀበለ፥ አኪአክሮስም እንደ ዳነ እይ። እርሱ ግን ፍዳውን ተቀበለ፤ እርሱ ወደ ጨለማ ወረደ። ምናሴ ምጽዋትን አደረገ፤ እውነትንም አደረገ፤ ከመከሩበት ከሞት መቅሠፍትም ዳነ። ሐማ ግን በዚያች ወጥመድ ወደቀና ሞተ።'),
  ('594fc88c-595c-550f-a7ec-4838335ecfbf', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '4af23235-c952-5124-a47c-3a0376eff3e1', 1, 11, '“አሁንም ልጄ፥ ምጽዋት የምታደርገውን እይ፤ ከሞት ታድናለች፤ ታጸድቃለችም።” ጦቢትም ይህን ተናግሮ ሞተ፤ ባልጋው ላይ ሳለም ነፍሱ ከሥጋው ተለየች። መቶ አምሳ ስምንት ዐመትም ሆኖት ነበር። በክብርም ቀበሩት፤'),
  ('6fa55a79-3a6f-5afa-a4f9-6c60c6c60b7b', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '4af23235-c952-5124-a47c-3a0376eff3e1', 2, 12, 'እናቱ ሐናም በሞተች ጊዜ ካባቱ ጋራ ቀበራት። ጦብያም ከሚስቱና ከልጆቹ ጋር አማቱ ራጉኤል ወዳለበት ወደ ባጥና ሄደ።'),
  ('0d28c110-42e2-57b9-af10-4f4b7a25babf', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '4af23235-c952-5124-a47c-3a0376eff3e1', 3, 13, 'ራጉኤልና ሚስቱ አድናም አርጅተው ሞቱ። አማቶቹንም አክብሮ ቀበራቸው። ገንዘባቸውንም ሁሉ ወረሰ። የአባቱን የጦቢትን ገንዘብም ወረሰ።'),
  ('5ac19d1e-609c-59bc-a5f6-9faa3d260f42', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '4af23235-c952-5124-a47c-3a0376eff3e1', 4, 14, 'ጦብያም በመቶ ሃያ ሰባት ዓመቱ ሞተ፤ የሜዶን ክፍል በምትሆን በባጥናም ተቀበረ።'),
  ('5034aee5-4031-559f-a6ff-34769db941c9', 'bec1453f-a5be-5fcb-aeb1-909a10342a6c', '4af23235-c952-5124-a47c-3a0376eff3e1', 5, 15, 'አባቱም እንደ ነገረው ሳይሞት የነነዌን ጥፋት ሰማ። ናቡከደነፆርና አሕሻዊሮስም የነነዌን ጥፋት ሰምተው ደስ አላቸው።'),
  ('39a4ad23-0452-504d-a53e-bb6d35f663c4', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 1, 1, 'በታላቅዋ ከተማ በነነዌ ለአሦር በነገሠ በናቡከደነፆር በዐሥራ ሁለተኛው ዓመት፥ ሜዶንንና ባጥናን ይገዛ የነበረው ንጉሥ አርፋክስድ፥'),
  ('1b4abd97-2d5b-56d5-a875-b78dae05b42c', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 2, 2, 'የባጥናን ዙሪያ በለዘበ ድንጋይ ሠራ፤ በከተማዋ ወርድ በኩል የመሠረትዋ ስፋት ሠላሳ ክንድ ነው፤ በከተማዋ ፊት ለፊት ያለው ስፋት ስድሳ ክንድ ርዝመት ነው። የግንቡን ቁመት ሰባ ክንድ አድርጎ ሠራ፤ ማዕዘኑም አምሳ ክንድ ነው።'),
  ('8a70f1eb-bacc-5dc3-addf-38d39f23d24d', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 3, 3, 'በየበሩ መቶ መቶ ክንድ እያለፈ የጕበኛ ቤቱን አቆመ፤ መሠረቱም ከማዕዘን እስከ ማዕዘን ድረስ ስድሳ ክንድ ነው።'),
  ('e4977da8-db5a-5d84-aaa5-7ad666f78840', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 4, 4, 'ጽኑዓኑ፥ ኀያላኑና የጥበቃ ሠራዊቱ የሚገቡባቸው የሚከፈቱ የበሮችዋን ደጃፍ ቁመታቸውን ሰባ ክንድ፥ ስፋታቸውን አርባ ክንድ አድርጎ ሠራ።'),
  ('688a7dc5-9e98-5ea4-a858-f0dc1fcb192f', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 5, 5, 'በዚያም ወራት ናቡከደነፆር ንጉሡ አርፋስክድን በሰፊ ሜዳ ተዋጋው፤ ያም ሜዳ በራግው አውራጃ ያለ ነው።'),
  ('4db003cc-e3cd-5e17-a380-0c82acdc6632', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 6, 6, 'በአምባ የሚኖሩ ሰዎችም ሁሉ ወጥተው ተቀበሉት፤ በኤፍራጥስና በጤግሮስ፥ በሒደስጶንም፥ በኤሊሜዎን ንጉሥ በአርዮክ ግዛት አውራጃ ያሉ ሁሉ የካሉድን ልጆች ይዋጓቸው ዘንድ እጅግ ብዙ የሆኑ አሕዛብም ተሰበሰቡ።'),
  ('1b33e009-ab7b-51cc-a2d8-5f246aaef08b', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 7, 7, 'የፋርስ ንጉሥ ናቡከደነፆርም በፋርስ አውራጃ ለሚኖሩ ሁሉ፥ በቂልቅያ፥ በደማስቆና በሊባኖስ ምዕራብ ወደሚኖሩ ሁሉ በወንዝ ዳርም ወደሚኖሩ ሰዎች ሁሉ ላከ።'),
  ('69374db4-6ed5-5302-a6c1-2e1aa40aec6d', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 8, 8, 'በቀርሜሎስና በገለዓድ፥ በገሊላና ሰፊ በሆነ በአስዴራን ምድረ በዳ ለሚኖሩ አሕዛብ።'),
  ('4ec8207f-2c2a-57a2-a8a7-8bf9743488e7', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 9, 9, 'በሰማርያና በአውራጃዋ ለሚኖሩ ሰዎች ሁሉ፥ በዮርዳኖስ ማዶ እስከ ኢየሩሳሌምና እስከ ቢላጢኒ፥ እስከ ኪሎስና እስከ ቃዴስ እስከ ግብፅ ወንዝ፥ ጣፍናስና ራሚስ እስከ ጌሴም ምድር ሁሉ።'),
  ('780734af-9521-52e4-a87e-0dde55da697e', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 10, 10, 'በጣኔዎስና በሜኒፌዎስ በላይ እስኪደርስ በግብፅ ለሚኖሩ ሁሉ እስከ ኢትዮጵያ ድንበር ድረስ ሁሉ ላከ።'),
  ('690c5ddf-98ee-51c1-a700-9852231a993d', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 11, 11, 'በምድር የሚኖሩ ሁሉ የፋርስ ንጉሥ የናቡከደነፆርን ትእዛዝ እንቢ አሉ፤ ከእርሱም ጋር ወደ ጦር አልሄዱም። አልፈሩትምና በፊታቸው እንደ አንድ ሰው ሆኗልና። መልእክተኞቹም ባዶአቸውን በውርደት ከፊታቸው ተመለሱ።'),
  ('a239ae99-e3b6-5b97-a9b1-9c87d4d2ecfd', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', '5de546db-f294-5cf7-afba-667412ff1207', 12, 12, 'ናቡከደነፆርም በዚያች ምድር ላይ ፈጽሞ ተቈጣ፤ የቂልቅያንና የደማስቂኒስን፥ የሶርያንም አውራጃ ሁሉ ይበቀልና በሞዓብ ምድር የሚኖሩትን ሁሉ፥ የአሞንንም ልጆች ይሁዳንም ሁሉ በግብፅ የሚኖሩትንም ከሁለቱ ባሕሮች ድረስ ተበቅሎ በሰይፍ ያጠፋቸው ዘንድ በዙፋኑና በመንግሥቱ ማለ።'),
  ('f6eda3ee-a9cb-55d8-a405-7aac437eaec7', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', 'fc326a67-4c86-5447-a675-3545cb35e2be', 1, 13, 'ከሠራዊቱ ሁሉ ጋር ንጉሡ አርፋክስድን በነገሠ በዐሥራ ሰባተኛው ዓመት ተዋጋው፤ ድል ነሥቶም የአርፋክስድን ሠራዊቱን ሁሉ፥ ፈረሶቹንና ሰረገላዎቹን ሁሉ ወሰደ።'),
  ('b8cde974-7cc1-5eb2-aa65-e2cd4f516c9d', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', 'fc326a67-4c86-5447-a675-3545cb35e2be', 2, 14, 'ሀገሮቹንም ሁሉ ያዘ፤ እስከ ባጥናም ድረስ ሄዶ አምባቸውን ያዘ፤ ሀገሩንም ሁሉ በረበረ፤ አጠፋትም።'),
  ('a12d6641-583c-5274-a8fb-04ed58eacbca', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', 'fc326a67-4c86-5447-a675-3545cb35e2be', 3, 15, 'አርፋክስድንም በራግው አውራጃ ይዞ በጦር ወጋው፤ ፈጽሞም አጠፋው።'),
  ('e9cbd809-33ea-5c88-a88a-2ec00ad1c094', '660ce9d0-e87e-5d03-aff4-ddbf740aff04', 'fc326a67-4c86-5447-a675-3545cb35e2be', 4, 16, 'እርሱም ተመለሰ፤ ከእርሱ ጋር ያሉ እጅግ አርበኞች የሆኑ ብዙ ሰዎችም ሁሉ ተመለሱ፤ በዚያም ሲያስብና ሲመክር መቶ ሃያ ቀን ተቀመጠ።'),
  ('51f35714-e808-5fe5-a526-6e63402e2f1b', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 1, 1, 'በዐሥራ ስምንተኛው ዓመት በጨረቃ አቈጣጠር በመጀመሪያው ወር በሰባተኛው ቀን እንደ ተናገረው ሀገሩን ሁሉ ይበቀል ዘንድ በአሦር ንጉሥ በናቡከደነፆር ቤተ መንግሥት ምክር ተመከረ።'),
  ('91a6bbd5-2dea-5ba9-a8ac-2a30ebdf7d97', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 2, 2, 'ሹሞቹንና አለቆቹን ሁሉ ጠርቶ ከእነርሱ ጋር የምክሩን ምሥጢር ተነጋገረ፤ በሀገሩ ሁሉ ክፉ ነገርን ተናገረ።'),
  ('11ea6256-faf1-566c-a539-0c8f55c2067a', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 3, 3, 'በአንደበቱ የተናገረውን ትእዛዝ ያልተቀበሉትን ሰዎች ሁሉ ያጠፋቸው ዘንድ ምክር ጨረሱ።'),
  ('94f05c43-f2d7-56e3-a900-76b22983721b', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 4, 4, 'ከዚህም በኋላ ምክሩን በጨረሱ ጊዜ የአሦር ንጉሥ ናቡከደነፆር ከእርሱ በታች ያለ ቢትወደዱ ሆሎፎርኒስን ጠርቶ እንዲህ አለው፦'),
  ('dca6f3ce-6f6e-5711-a0e1-666aa9cd2cfa', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 5, 5, '“የአገሩ ሁሉ ጌታ ገናናው ንጉሥ እንዲህ ይላል፦ መቶ ሃያ ሺህ በኀይላቸው የታመኑ እግረኞች ሰዎችን መቶ ሃያ ሺህ ፈረሰኞችንም ከፈረሶቻቸው ጋራ ካንተ ጋራ ይዘህ እነሆ በፊቴ ትወጣለህ።'),
  ('27433a2b-2cb1-53f4-a649-a914fcd340c7', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 6, 6, 'በአንደበቴ ለተናገርሁት ነገር መታዘዝን እንቢ ብለዋልና በምዕራብ በኩል ወዳለች ሀገር ትወጣለህ።'),
  ('1f59fa5a-9a78-5435-a7ad-fea54df1578c', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 7, 7, 'በእነርሱ ተቈጥቼ እወጣለሁና፥ ምድርንም በሠራዊቴ እግር እሸፍናታለሁና፥ ገንዘባቸውንም እዘርፋቸዋለሁ፥ እበረብራቸዋለሁምና ውኃውንና ሀገሩን ያዘጋጁልኝ ዘንድ ለእነርሱ አዋጅ ትነግራለህ።'),
  ('cc0b88ec-28cd-5d1e-afa0-eac260425392', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 8, 8, 'ቍስለኞቻቸውም በሸለቆውና በፈሳሹ ይመላሉ፤ ወንዙም ሬሳቸውን ተመልቶ ይፈስሳል፤'),
  ('42fe2174-41de-53f1-a69e-bacca59b1954', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 9, 9, 'ምርኳቸውንም እስከ ምድር ዳርቻ ድረስ እበትነዋለሁ።'),
  ('9730d64f-33f0-51e8-acac-2529d40da4ef', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 10, 10, 'አንተ ግን ቀድመህ አውራጃዎቻቸውን ሁሉ ያዝልኝ፤ ራሳቸውን ወዳንተ ቢመልሱ በእነርሱ እስከምፈርድበት ቀን ለእኔ ትጠብቃቸዋለህ።'),
  ('713c7b95-59ea-5bcd-a09b-a6caed822308', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 11, 11, 'ዐመፀኞችን ታጠፋቸው ዘንድ፤ በሄድህበትም ሁሉ ትዘርፋቸው ዘንድ ዐይንህ አትራራላቸው።'),
  ('ab2e7b86-f3e0-53d9-ae1d-6825ebb00bdd', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 12, 12, 'እኔ ሕያው ነኝና እንደ ተናገርሁም ይኽን በእጄ አደርግ ዘንድ መንግሥቴ ጽኑዕ ነውና።'),
  ('092faac8-726e-5a14-a9ab-a109e1cbfefc', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '800008f3-f07a-508a-a296-ecc8128d2939', 13, 13, 'እንዳዘዝሁህ አድርግ እንጂ አንተም ከእኔ ከጌታህ ቃል አንዲት ስንኳ የምትተወው አይኑር፤ ይህንም ፈጥነህ አድርግ።”'),
  ('71473f71-85ea-51aa-aed3-a1ab00417044', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 1, 14, 'ሆሎፎርኒስም ከጌታው ፊት ወጥቶ ኀያላኑን፥ አዛዦችንና የአሦር ሠራዊት አለቆችን ሁሉ ጠራቸው።'),
  ('b65d693b-71be-524c-a444-e138f85426e6', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 2, 15, 'ጌታውም እንዳዘዘው መቶ ሃያ ሺህ የተመረጡ እግረኞች አርበኞችንና ዐሥራ ሁለት ሺህ ፈረሰኞች ቀስተኞችን ቈጠረ።'),
  ('7a219758-5da3-528c-a2c7-9680c817e261', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 3, 16, 'ፈጽመው ይዋጉ ዘንድ አዘዛቸው።'),
  ('3ad049de-2455-5856-a30f-ac88b203b592', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 4, 17, 'ስንቃቸውንም የሚጭኑባቸው እጅግ ብዙ የሆኑ ግመሎችንና አህዮችን፥ በቅሎዎችንም፥ ምግብም ሊሆኗቸው ቍጥር የሌላቸው በሬዎችንና በጎችን፥ ፍየሎችንም ወሰደ።'),
  ('ff4bd0ae-42e8-52ea-a15e-108e97704529', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 5, 18, 'ለብዙ ሰዎችና ለሠራዊቱ ሁሉ ከንጉሡ ቤት እጅግ ብዙ የሆነ ብርና ወርቅን ስንቅ አድርጎ ሰጣቸው።'),
  ('85fcefc5-2050-5f59-a301-b6972e54fb42', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 6, 19, 'እርሱም ከሠራዊቱ ሁሉ ጋር ወጣ፤ በፈረሶችና በሠረገላዎች፥ በተመረጡ አርበኞችም በምዕራብ አንጻር ያለ ምድርን ሁሉ ይሸፍን ዘንድ ከንጉሡ አስቀድሞ ዘመተ።'),
  ('8b010e29-2df8-588f-a1c0-fa2d45421876', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 7, 20, 'ከእነርሱም ጋር አንድ የሆኑ፥ ብዛታቸውም እንደ አንበጣና እንደ ባሕር አሸዋ የሆኑ ብዙ ሰዎች ከእነርሱ ጋር ወጡ። ከብዛታቸውም የተነሣ ቍጥር የላቸውም።'),
  ('0081aec1-094e-5102-a928-49a3d45b6f4e', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 8, 21, 'ከነነዌም ወጥተው በበቄጤሊት ሜዳ አንጻር የሦስት ቀን ጎዳና ሄዱ፤ ከላይኛው ቂልቅያ በስተግራ በኩል ባለው ተራራ አጠገብ በበቄጤሊት አንጻር ሰፈሩ።'),
  ('3c82e471-2362-5a47-af23-f290a03c7c3a', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 9, 22, 'ከዚያም ሆሎፎርኒስ ሠራዊቱን ሁሉ፥ ፈረሰኞችንና እግረኞችንም፥ ሠረገላዎችንም ይዞ ወደ ተራራማው ሀገር ሄደ።'),
  ('eeed12d9-c552-53ff-ad99-cd67597e9b1f', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 10, 23, 'ፌድንና ሎድንም ወጋቸው፤ የሬስስን ልጆችን ሁሉ፥ በኤሌዎን ግራ አንጻር ባለ ሜዳ የሚኖሩ የእስማኤልንም ልጆች ማረካቸው።'),
  ('5c18f856-e008-5a34-ac69-8c6d5d247c14', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 11, 24, 'ኤፍራጥስንም ተሻግሮ ወደ መስጴጦምያ ሄደ፤ ወደ ባሕርም እስኪደርስ ድረስ በአርባኒ ወንዞች ላይ ያሉ ታላላቅ ከተሞችን ሁሉ አፈረሰ።'),
  ('75286919-6628-5291-a8a9-db37e1e44c9a', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 12, 25, 'የቂልቅያንም አውራጃ ያዘ፤ ጠላቱንም ሁሉ አጠፋ፤ በምዕራብም አንጻር በዐዜብ በኩል እስከ ያፌት አውራጃ ድረስ ሄደ።'),
  ('feed3fdb-0969-5fa6-a864-22a1e1f7234b', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 13, 26, 'የምድያምንም ልጆች ሁሉ ከበባቸው፤ ከብታቸውንም ዘረፈ፤ ቤታቸውንም አቃጠለ።'),
  ('ac1822f0-aa7a-50bb-a74f-435d293b6454', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 14, 27, 'በስንዴ አዝመራ ጊዜም በደማስቆ ወዳለ ሜዳ ወርዶ አዝመራቸውን ሁሉ አቃጠለ፤ የላሞቻቸውንና የበጎቻቸውንም መንጋዎች ይዘርፏቸው ዘንድ አዘዘ፤ አምባቸውንም አፈረሰ፤ ልጆቻቸውንም ማረከ፥ ጎልማሶቻቸውንም ሁሉ በጦር ገደለ።'),
  ('f46c58e5-ce61-525d-a759-329f5e5016cb', '27ceeaaa-ad58-51ce-af88-1404422c10bd', '98b3c724-a7ca-5bb1-a0e2-b3013aa90fb4', 15, 28, 'ከእነርሱም የተነሣ መፍራትና ድንጋጤ በባሕሩ ዳርቻ በጢሮስና በሲዶና በሚኖሩ፥ በአቂናና በሴይርም፥ በያምኒያም በሚኖሩ ሰዎች ላይ ወደቀ። በአስቀሎናና በአዛጦንም የሚኖሩ ሰዎች ከርሱ መምጣት የተነሣ ፈጽመው ፈሩ።'),
  ('efb76f3b-84e6-594f-ac6a-9017b47df15b', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 1, 1, 'እንዲህም ብለው የሰላም መልእክተኞችን ወደ እርሱ ላኩ።'),
  ('d132d98c-6eb1-5c55-aefe-6918adf2b467', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 2, 2, '“እነሆ፥ እኛ የገናናው ንጉሥ የናቡከደነፆር ባሮች በፊትህ እንኖራለን። በፊትህም እንደ ወደድህ አድርገን።'),
  ('abff1b2e-79b5-59b8-aaac-15d467cfa4d9', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 3, 3, 'እነሆ፥ ከተሞቻችንና አንባዎቻችንም ሁሉ፥ እርሻችንም ሁሉ፥ መንጋዎቻችንም፥ የመሰማሪያችን ቦታዎች ሁሉ፥ በጎቻችንም በፊትህ ያንተ ናቸው፤ እንደ ወደድህም አድርግ።'),
  ('34f899e4-2da0-5a32-a0f0-9f14e94582ed', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 4, 4, 'እነሆ ታላላቆች ከተሞቻችን በእነርሱ የሚኖሩ ሰዎች ባሮችህ ናቸው፤ መጥተህም እንደ ወደድህ አድርግ።”'),
  ('1b21346f-9a4f-5dc5-a204-632c596b0af2', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 5, 5, 'እነዚያም ሰዎች ወደ ሆሎፎርኒስ ደርሰው ይህን ነገር ነገሩት።'),
  ('90b005e9-a1fb-5cb2-a45d-d89b8fd69487', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 6, 6, 'እርሱም ወደ መንደራቸው ወረደ፤ ሠራዊቱም ከእርሱ ጋር ወረዱ ከፍ ከፍ ያሉ አንባዎችንም አስጠበቀ፥ ከእነርሱም የሚረዱትን የተመረጡ ሰዎችን ወሰደ።'),
  ('c8ca9037-067e-514d-ad61-09110dfa3fa1', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 7, 7, 'ወገኖቻቸው ሁሉና እነርሱም አክሊል ደፍተው እየዘፈኑ፥ በገና እየደረደሩና ከበሮ እየመቱ ተቀበሉት።'),
  ('1e983118-90e2-5cb0-a7a9-f8bfc1684e00', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 8, 8, 'እርሱ ግን አውራጃቸውን ሁሉ አጠፋ፤ ጣዖቶቻቸውንም ሰበረ፤ አሕዛብም ሁሉ ናቡከደነፆርን ብቻ እንዲያመልኩት፥ ቋንቋዎችና ነገዶች ሁሉ አምላክ እንዲሉት እርሱ የሰውን ሁሉ ጣዖት ያጠፋ ዘንድ ታዝዞ ነበር።'),
  ('4c0d3d2f-9bcb-5535-a86e-89e752527778', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 9, 9, 'በትልቁ በይሁዳ ተራራ አንፃር የገባኢያ ዕጣ ወደሚሆን ወደ ኤስድራሎንም መጣ።'),
  ('5aae5973-b7f5-5967-a50b-20914e7e87ee', '8b69b50e-ab8b-557d-a34b-c206654d995a', '8522afe9-d9c6-5b8c-ac44-faa665298f22', 10, 10, 'በሴቅቶን ከተማና በጌባን ሜዳ መካከልም ሰፈረ፤ ለሠራዊቱም ስንቅ ያዘጋጅ ዘንድ በዚያ አንድ ወር ተቀመጠ።'),
  ('5c177d10-d400-51ef-ab3d-347380177ce6', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'e3abe04b-0eed-5be7-abf2-d76751be06f7', 1, 1, 'በይሁዳ የሚኖሩ የእስራኤል ልጆች የአሦር ንጉሥ የናቡከደነፆር ቢትወደድ ሆሎፎርኒስ በአሕዛብ ያደረገውን ሁሉ፥ አውራጃዎቻቸውን ሁሉ እንዳጠፋ፥ እነርሱንም እንዳጠፋቸው ሰሙ።'),
  ('fc390ba4-0660-5b7e-a4d8-4779ed610dae', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'e3abe04b-0eed-5be7-abf2-d76751be06f7', 2, 2, 'ከመቅረቡም የተነሣ ስለ ኢየሩሳሌምና ስለ አምላካቸው ስለ እግዚአብሔር ቤተ መቅደስ ፈጽመው ፈሩ።'),
  ('65b80eab-36b0-57c7-adb9-3d2df47edaf6', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'e3abe04b-0eed-5be7-abf2-d76751be06f7', 3, 3, 'ከይሁዳ የተመረጡ ወገኖችም ሁሉ በቅርቡ ከምርኮ ከተመለሱ በኋላ ተሰብስበው ነበርና ምሥዋዑንና ንዋየ ቅድሳቱን፥ ቤተ መቅደሱንም ከረከሰ በኋላ አነጹት።'),
  ('5d4dc7b9-009e-5e63-ab6c-812715fb3f4b', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'e3abe04b-0eed-5be7-abf2-d76751be06f7', 4, 4, 'ስለዚህም ወደ ሰማርያ አውራጃዎችና ወደ ቆና፥ ወደ ቤቶሮንና ወደ ቤልሜን፥ ወደ ኢያሪኮና ወደ ኮባ፥ ወደ ኤሦራና ወደ ሳሌም ሸለቆ ሁሉ ላኩ።'),
  ('c5c5ef31-e0d1-58d2-a327-508b907327ac', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'e3abe04b-0eed-5be7-abf2-d76751be06f7', 5, 5, 'ከፍ ያሉ የተራራዎቻቸውንም ጫፎች ያዙ። በሚኖሩባቸው መንደሮችም መሸጉ። አዝመራቸውም ቀደም ብሎ ተሰብስቦ ነበርና ለጦርነት ስንቅን አዘጋጁ።'),
  ('c3f19939-7ba1-5415-a717-3f102e672003', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'e3abe04b-0eed-5be7-abf2-d76751be06f7', 6, 6, 'በዚያም ወራት በኢየሩሳሌም የሚኖር የካህናቱ አለቃ ኢዮአቄም በዶታይም አጠገብ ባለች ምድረ በዳ፥ በኤስድራሎም አንጻር ባለች በቤጦሜስቴምና በቤጤልዋ ለሚኖሩ ሰዎች ጻፈ።'),
  ('d36de5ef-b8bb-581a-a16e-5094d72f7fe6', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'e3abe04b-0eed-5be7-abf2-d76751be06f7', 7, 7, 'በዚያም በይሁዳ ላይ መግቢያ ስለአለና መግቢያውም ለሁለት ሰዎች መተላለፊያ ብቻ ነው እንጂ ጠባብ ስለ ሆነ የሚወጡትን ለመከላከል የአንባዎቹን መግቢያ አጽንታችሁ ጠብቁ ብሎ ጻፈ።'),
  ('c02c68f1-7527-5cfd-ae37-71afbb53ea99', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'f40de6ea-6fd9-56f5-aa37-f8eb178320bf', 1, 8, 'የእስራኤልም ልጆች ታላቁ ካህን ኢዮአቄምና በኢየሩሳሌም የሚኖሩ የእስራኤል ወገኖች አለቆች ሁሉ እንዳዘዙአቸው አደረጉ።'),
  ('25b06b3b-b04c-5a1a-a95f-3f9e6b75654b', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'f40de6ea-6fd9-56f5-aa37-f8eb178320bf', 2, 9, 'የእስራኤልም ልጆች ከፍ ባለ ቃል ወደ እግዚአብሔር ጮኹ፤ ሰውነታቸውንም በጽኑ ኀዘን አሳዘኑ።'),
  ('31611157-56d5-55f2-a412-d2ce495ab273', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'f40de6ea-6fd9-56f5-aa37-f8eb178320bf', 3, 10, 'እነርሱም ሚስቶቻቸውና ልጆቻቸው፥ ከብቶቻቸውም፥ ምንደኛውና ስደተኛው ሁሉ፥ በዋጋም የተገዛው ሁሉ ማቅ ለብሰው አለቀሱ።'),
  ('7d1076ca-3f67-5bca-a8cd-2b4af67e7bd1', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'f40de6ea-6fd9-56f5-aa37-f8eb178320bf', 4, 11, 'የእስራኤልም ወገኖች ሁሉ ሚስቶቻቸውና በኢየሩሳሌም የሚኖሩ ልጆቻቸውም በቤተ መቅደስ ደጃፍ ወደቁ፤ በራሳቸውም ትቢያ ነሰነሱ፤ በእግዚአብሔርም ፊት ማቃቸውን አነጠፉ፤ መሠዊያውንም ማቅ አለበሱ።'),
  ('7e0751d5-14ed-5312-aa34-11627a3b5b51', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'f40de6ea-6fd9-56f5-aa37-f8eb178320bf', 5, 12, 'ልጆቻቸውን እንዳይነጠቁ፥ ሚስቶቻቸውን እንዳይማረኩ፥ የርስታቸው ከተሞችም እንዳይጠፉ፥ መቅደሳቸውንም እንዳያረክሱ፥ ለአሕዛብም መዘበቻ እንዳያደርጉት ወደ እስራኤል አምላክ በአንድነት ፈጽመው ጮኹ።'),
  ('81568235-665c-536e-a121-e9eb59a717da', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'f40de6ea-6fd9-56f5-aa37-f8eb178320bf', 6, 13, 'እግዚአብሔርም መከራቸውን አይቶ ልመናቸውን ሰማ፤ ሕዝቡም በኢየሩሳሌምና በይሁዳ ሁሉን በሚችል በእግዚአብሔር መቅደስ ፊት ብዙ ቀን ጾሙ።'),
  ('cd910be8-bdc3-5ccf-a5fe-a735d5d40f6e', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'f40de6ea-6fd9-56f5-aa37-f8eb178320bf', 7, 14, 'በእግዚአብሔር ፊት የሚቆሙ ታላቁ ካህን ኢዮአቄምና ካህናቱ፥ የእግዚአብሔርንም ሥራ የሚሠሩ ሰዎች በወገባቸው ማቅ ታጠቁ፤ የዘወትሩን መሥዋዕት፥ የስእለቱንና ሕዝቡ በፈቃድ የሚያቀርቡትን መሥዋዕት አገቡ።'),
  ('3f7a2b7a-e30a-54c2-a424-a10472cb3746', 'fe9e0676-98bd-546b-a199-b71fa3f05aaa', 'f40de6ea-6fd9-56f5-aa37-f8eb178320bf', 8, 15, 'በራሳቸውም ዐመድ ነሰነሱ፤ በፍጹም ኀይላቸውም ወደ እግዚአብሔር ጮኹ፤ “የእስራኤልንም ወገን በምሕረት ተመልከት” አሉ።'),
  ('9156da41-e7ec-597c-ad24-305711601e2c', '91cc4a2b-0750-5480-a598-899abf407832', '0212c082-fc1a-55a8-a87d-bb8e2bce26a5', 1, 1, '“የእስራኤል ልጆች ለሰልፍ ተዘጋጁ፤ የኮረብታቸውንም በሮች ዘጉ። የአምባውንም ራሶች አጠሩ፤ መንገዱንም ጐፃጕፅ አደረጉ” ብለው ለአሦር ሠራዊት አለቃ ለሆሎፎርኒስ ነገሩት።'),
  ('338da077-4d58-545b-ab22-b18bf61f4e4a', '91cc4a2b-0750-5480-a598-899abf407832', '0212c082-fc1a-55a8-a87d-bb8e2bce26a5', 2, 2, 'እርሱም ፈጽሞ ተቈጣ፤ የሞአብን አለቆችና የአሞንን ሹሞች፥ በባሕር ዙሪያ ያሉ ገዢዎችንም ጠራቸው።'),
  ('fb9fddff-2b20-5c42-ac0a-039e2ece1ca8', '91cc4a2b-0750-5480-a598-899abf407832', '0212c082-fc1a-55a8-a87d-bb8e2bce26a5', 3, 3, 'እንዲህም አላቸው፥ “የከነዓን ልጆች ሆይ! ንገሩኝ፤ በተራሮች የሚኖሩ እነዚህ ወገኖች ምንድን ናቸው? በከተሞች የሚኖሩ፥ ሠራዊታቸውም ብዙ የሆኑ እኒያስ ወገኖች ምንድን ናቸው? ጽናታቸውስ ምን ያህል ነው? በእነርሱስ ላይ የነገሠ ንጉሥ ማን ነው? ወይስ ሹማቸው? ወይስ አለቃቸው ማን ነው?'),
  ('de5c9dd8-a7b8-53ec-ab82-e71d6ddfaff6', '91cc4a2b-0750-5480-a598-899abf407832', '0212c082-fc1a-55a8-a87d-bb8e2bce26a5', 4, 4, 'በምዕራብ ከሚኖሩ ሰዎች ሁሉ ጋር ይቀበሉኝ ዘንድ እንዴት አልመጡም?”'),
  ('e61ecbb3-b5c5-5f28-a67e-47e38b7cfe5f', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 1, 5, 'የአሞን ልጆች ሹም አክዮርም እንዲህ አለ፥ “ከእኔ ከባርያህ አንደበት ይህን ነገር ስማ፤ ከእኔ ከባሪያህ አንደበት ሐሰት ነገር አይወጣምና፥ በእነዚህ አንባዎች፥ በአቅራቢያህም ስለሚኖሩ ስለእነዚህ ወገኖች እውነት ነገርን እነግርሃለሁ።'),
  ('354860f9-40cf-511e-a456-5b792700a1fe', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 2, 6, 'እነዚህ ወገኖች ከከላውዴዎን መጡ።'),
  ('9aa931ed-5634-5146-a954-cd4d653755df', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 3, 7, 'በከላውዴዎን ሀገር የሚኖሩ የአባቶቻቸውን ጣዖቶች ያመልኩ ዘንድ አልወደዱምና አስቀድመው በመስጴጦምያ ይኖሩ ነበረ።'),
  ('62fcac16-c238-5402-a544-265a429ed42a', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 4, 8, 'የወገኖቻቸውንም መንገድ ትተዋልና ላወቁት ከጣዖቶቻቸው ፊት ላወጣቸው ለሰማይ አምላክ ለእግዚአብሔርም ሰግደዋልና ወደ መስጴጦምያ ሸሽተው በዚያ ብዙ ዘመን ኖሩ።'),
  ('b052fa01-4319-5be3-a794-768bbe0ad2bf', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 5, 9, 'ፈጣሪያቸውም ከተሰደዱበት ሀገር ይወጡና ወደ ከነዓን ይሄዱ ዘንድ አዘዛቸው፤ በዚያም ብዙ ዘመን ኖሩ፤ ብርንና ወርቅን፥ ብዙ ከብቶችንም ፈጽመው አበዙ።'),
  ('b08e7928-7076-53bf-a9bd-a9254025d020', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 6, 10, 'ረኃብ በከነዓን ሀገር ሁሉ ጸንትዋልና ወደ ግብፅ ወረዱ፤ በዚያም እየተመገቡ ኖሩ፤ በዚያም በዝተው ሞሉ፤ ለወገኖቻቸውም ቍጥር አልነበራቸውም።'),
  ('497b2e76-71bf-5425-a752-9ff7514dc3db', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 7, 11, 'የግብፅ ንጉሥም በጠላትነት ተነሣባቸው፤ ተተነኰለባቸውም፤ መከራም አጸናባቸው፤ ጡብ በማሠራትም ገዛቸው፤ ባሮችም አደረጋቸው።'),
  ('020f7a3c-c421-5950-aae5-cb199e6f7a8b', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 8, 12, 'ወደ አምላካቸውም ጮኹ፤ እርሱም መድኀኒት በሌለው መቅሠፍት የግብፅ ሀገርን ሁሉ አጠፋ፤ ግብፃውያንም ከፊታቸው አስወጡአቸው።'),
  ('49d6022a-1d09-5c6d-aa4c-bc17cb41c8a3', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 9, 13, 'እግዚአብሔርም በፊታቸው የኤርትራን ባሕር አደረቃት።'),
  ('14e076b6-d770-5153-a853-e3579ae60821', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 10, 14, 'ወደ ሲና ተራራና ቃዴስ በርኔ ወሰዳቸው፤ በምድረ በዳ የሚኖሩትንም ሁሉ አወጣቸው።'),
  ('05ea6c94-458e-5a6d-a489-8ede2b7769b2', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 11, 15, 'በአሞራውያን ሀገርም ኖሩ፤ የሐሴቦንንም ሰዎች ሁሉ በኀይሉ አጠፋ ዮርዳኖስንም ተሻግረው ተራራማውን ሀገር ሁሉ ወረሱ።'),
  ('18a94c1d-71b8-57e0-a7d4-b1eaea311a89', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 12, 16, 'ከናኔዎንን፥ ፌርዜዎንን፥ ኢያቡሴዎንን፥ ሴኬምን፥ ጌርጌሴዎንንም ሁሉ ከፊታቸው አስወጣቸው፤ በዚያም ብዙ ዘመን ኖሩ።'),
  ('6483fa4c-8f89-5817-ac7d-11e5c6e70445', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 13, 17, '“በፈጣሪያቸውም ፊት ባልበደሉ ጊዜ መልካም ነገር ሁሉ ሆነላቸው፤ በደልን የሚጠላ እግዚአብሔር ከእነርሱ ጋር ነበረና።'),
  ('af2f0384-05d9-5ac4-a849-30fef8dbe71d', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 14, 18, 'ያዘዛቸውን ሥርዐት በተዉ ጊዜ ግን ፈጽሞ በብዙ ጦር አጠፋቸው፤ ወደ ባዕድ ሀገርም ተማረኩ፤ የፈጣሪያቸው ማደሪያ ቤተ መቅደስም ፈረሰ፤ ምድረ በዳም ሆነ፤ ከተሞቻቸውንም ጠላቶቻቸው ያዙባቸው።'),
  ('eefa8ab8-63f4-5313-a113-da8af8981ac5', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 15, 19, 'ዛሬ ግን ወደ ፈጣሪያቸው ተመለሱ፤ ከተበተኑበትም ሀገር ከዚያ ተሰበሰቡ፤ ቤተ መቅደስ ባለበት በኢየሩሳሌም ኖሩ፤ ምድረ በዳም ነውና በተራራው ኖሩ።'),
  ('431f7571-5456-5ca8-a2ac-4b5e8065c5c3', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 16, 20, 'አሁንም አቤቱ ጌታዬ እነዚህ ወገኖች በደል እንዳለባቸው፥ ፈጣሪያቸውንም በድለው እንደ ሆነ ይህ መሰናክላቸው ነውና አንድ ጊዜ እናረጋግጥ፤ ከዚያ በኋላ ወጥተን እንዋጋቸዋለን።'),
  ('271ba446-8158-5ba6-a264-9146fb9b9a83', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 17, 21, 'በእነዚህ ወገኖች በደል ከሌለባቸው ግን ጌታዬ እለፋቸው፤ እነሆ ጌታቸው ያጸናቸው ይሆናል፤ ወይም አምላካቸው ይቆምላቸው ይሆናል፤ እኛም በሀገሩ ሁሉ ኀፍረት እንሆናለን።”'),
  ('1153216e-112c-5222-a6b4-80efdcb44f7b', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 18, 22, 'ከዚህ በኋላ አክዮር ይህን ነገር ተናግሮ በጨረሰ ጊዜ በሰፈሩ ዙሪያ የቆሙ ወገኖች ሁሉ አንጐራጐሩ፤ የሆሎፎርኒስ ሹሞች፥ በባሕር ዙሪያና በሞዓብ የሚኖሩ ሰዎችም ሁሉ “አክዮርን እንግደለው” አሉ።'),
  ('ba9d6054-4a53-591c-a36c-08c7de4e5c5a', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 19, 23, '“ከጽኑ አርበኛ ጋር ይዋጉ ዘንድ ብርታትና ኀይል የሌላቸውን ወገኖች የእስራኤልን ልጆች የምንፈራቸው አይደለም።'),
  ('c5a2b33a-3960-5f6c-ab41-f2a6b0e0aff6', '91cc4a2b-0750-5480-a598-899abf407832', '5d4756e8-d51c-593c-a706-19a691c285c1', 20, 24, 'ስለዚህ ግን ጌታችን ሆሎፎርኒስ ሆይ፥ እንዝመት፤ እነርሱም ለጭፍራዎችህ ሁሉ ምግብ ይሆናሉ” አሉ።'),
  ('6522efaa-b463-59cf-a51a-594ff19f2c7c', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 1, 1, 'ከዚህ በኋላ በሸንጎው ዙሪያ ያሉ እነዚያ ሰዎች ዝም ባሉ ጊዜ የአሦር ሠራዊት አለቃ ሆሎፎርኒስ አክዮርን በፍልስጥኤም ወገኖችና በሞዓብ ልጆች ሁሉ ፊት እንዲህ አለው፦'),
  ('a58b0944-b7ce-5e0f-a53a-9064e65995d6', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 2, 2, '“አንተ የኤፍሬም ምንደኛ አክዮር! ዛሬ ትንቢት ትናገርልን ዘንድ እግዚአብሔር ያጸናቸዋልና የእስራኤልን ልጆች አትውጓቸው ትለን ዘንድ አንተ ማን ነህ? ያለ ናቡከደነፆርስ እግዚአብሔር ማን ነው?'),
  ('aab2fb9e-f1e9-5ffc-af38-dcddd7c988f2', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 3, 3, 'እርሱ ኀያላኑን ልኮ ከገጸ ምድር ፈጽሞ ያጠፋቸዋል፤ አምላካቸውም አያድናቸውም፤ እኛም የናቡከደነፆር ባሮች እንደ አንድ ሰው እናጠፋቸዋለን፤ በእነርሱ እንረግጣቸዋለንና የፈረሶቻችንንም ኀይል ሊቋቋሙ አይችሉም።'),
  ('9ab1b683-1228-5f3e-a386-1e1a3be6d24a', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 4, 4, 'ተራሮቻቸውም በደማቸው ይሰክራሉ፤ የልጆቻቸውም ሬሳ ይበዛል፤ የዓለሙ ሁሉ ጌታ ንጉሡ ናቡከደነፆር አጠፋቸዋለሁ ብሏልና ቃሉ ሐሰት እንዳይሆን ከዚህ ዓለም ፈጽመው ይጠፋሉ እንጂ በፊታችን በእግራቸው አይቆሙም።'),
  ('fb867827-6265-5b2a-a4f2-5ebaed9a62a6', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 5, 5, '“ዛሬ በኀጢአትህ ይህን የተናገርህ የአሞን ምንደኛ አክዮር፥ አንተ ግን ከግብፅ ሀገር የወጡ እስራኤልን ተበቅዬ እስካጠፋቸው ድረስ ከዚህ ቀን ጀምሮ እንግዲህ ወዲህ ፊቴን አታየውም።'),
  ('e60c2404-9752-5729-ac8f-d86a3e5581d2', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 6, 6, 'የዚያን ጊዜ የጭፍራዎችና የወገኖች ጦር በጎንህ ይገባል፤ ከሬሳዎቻቸውም ጋራ ትወድቃለህ።'),
  ('d07e878e-1ebc-55a7-a412-d4d64c501bf1', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 7, 7, 'በተመለስሁም ጊዜ ባሮች ወደ አንባቸው ይወስዱሃል፤ ባቀበቱም ካሉ ከተሞቻቸው ባንዲት ከተማ ያኖሩሃል።'),
  ('d951dd5d-f63b-5983-ac15-9fdc12a960e5', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 8, 8, 'እስካጠፋቸውም ድረስ አይገድሉህም።'),
  ('5d8e3cca-01fb-5bf2-a46b-ee80f6d34c81', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 9, 9, 'እንደማንችላቸው በልብህ ትታመናለህና ፊትህ አይውደቅ፤ እኔ ተናግሬአለሁና፤ ከቃሌም የሚወድቅ የለምና።”'),
  ('ef12dd2a-c469-5316-a8a9-626bc3265f87', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 10, 10, 'ሆሎፎርኒስም በፊቱ በድንኳኑ ውስጥ የሚቆሙ አሽከሮቹን አክዮርን ይዘው ወደ ቤጤልዋ ይወስዱት ዘንድ፥ ለእስራኤልም ልጆች እርሱን ይሰጧቸው ዘንድ አዘዛቸው።'),
  ('41467a88-53fa-56d2-a6a3-7cb415b8617e', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 11, 11, 'አሽከሮቹም ይዘው ከሰፈሩ ውጭ ወደ ምድረ በዳ ወሰዱት፤ ከምድረ በዳውም መካከል ወደ ተራራማው ሀገር ሄዱ፤ ከዚህም በኋላ በቤጤልዋ በታች ወዳሉ ምንጮች ደረሱ።'),
  ('3be2ae5c-d8e3-57c7-ab03-c75c6fde1331', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 12, 12, 'የዚያችም ሀገር ሰዎች ባዩአቸው ጊዜ መሣሪያቸውን ይዘው ከከተማ ወደ ተራራው ራስ ሄዱ። ወንጭፍ የያዙ ሰዎችም ሁሉ መግቢያውን ጠበቁ፤ በላያቸውም መርግ ጣሉ።'),
  ('564084f0-bc5a-54d2-af4b-4f3b2fbcd19c', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 13, 13, 'የአክዮርንም እግር ብረት ፈቱት፤ በተራራውም በታች አሰሩት፤ በዚያም በተራራው በታች ጣሉት፤ ትተውትም ወደ ጌታቸው ተመለሱ።'),
  ('5ebeedc5-ccb0-5c45-ae06-74a4330da78a', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 14, 14, 'የእስራኤልም ልጆች ከአንባቸው ወርደው ወደ እርሱ ሄዱ፤ ፈትተውም ወደ ቤጤልዋ ወሰዱት።'),
  ('98b4a26d-2e5e-5cd6-a6be-3a830d3ef220', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 15, 15, 'በዚያም ወራት የከተሞቻቸው አለቆች በነበሩት ከነገደ ስምዖን በሚካ ልጅ ኦዝያስና በጎቶንያ ልጅ በክብሪስ፥ በመልክያል ልጅ በከርሚስም ዘንድ አስቀመጡት።'),
  ('d6fc3920-26c7-566b-a98d-87caff7e0c85', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 16, 16, 'በከተሞቻቸውም ያሉ አለቆችን ሁሉ ጠሩ፤ ሴቶቻቸውና ጐልማሶቻቸውም ሁሉ ሮጠው ወደ ሸንጓቸው ሄዱ፤ አክዮርንም በሁሉ መካከል አቆሙት፤ ኦዝያስም የተደረገውን ሁሉ ጠየቀው።'),
  ('a4de9236-3a35-595d-a761-121cbebc88b7', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 17, 17, 'እንደ ዶለቱና በአሦር ሠራዊት አለቆች መካከል ነገራቸውን ሁሉ እንደ ተናገሩ፥ ሆሎፎርኒስም በእስራኤል ወገኖች ላይ በትዕቢት እንደ ተናገረ መልሶ የሆሎፎርኒስን ነገር ሁሉ ነገራቸው።'),
  ('a0e23a08-dc2b-546a-a510-e1fb5ed4a827', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 18, 18, 'ሕዝቡም ሁሉ በግንባራቸው ወድቀው ለእግዚአብሔር ሰገዱ፤ እንዲህም እያሉ ጸለዩ፦'),
  ('7b5972b0-da91-5054-a0c1-b4da46911000', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 19, 19, '“አቤቱ የሰማይ አምላክ ሆይ፥ ትዕቢታቸውን ተመልከት፤ የወገኖቻችንንም መከራ አይተህ ይቅር በል፤ በዚችም ቀን ወደ መቅደስህ ተመልከት።”'),
  ('b86ab276-8b05-54c7-a433-e8ddc6991e57', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 20, 20, 'አክዮርንም ደስ አሰኙት፤ ፈጽመውም አከበሩት።'),
  ('9320a1de-ccda-5bb5-a9c2-c42f6b2f81ab', '1464a3c0-4d12-5d0a-ab35-f7d4072db0a2', '585f75c7-1394-58ff-a5d4-e2b9b3e5b258', 21, 21, 'ኦዝያስም ከተሰበሰቡበት ወስዶ ወደ ቤቱ አገባው፤ ለሽማግሌዎችም በዓልን አደረጉ፤ ይረዳቸውም ዘንድ የእስራኤልን አምላክ በዚያች ሌሊት ሁሉ ለመኑት።'),
  ('9a7cddd8-e080-51f8-a85e-8509974d76ca', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 1, 1, 'በማግሥቱም ሆሎፎርኒስ ወደ ቤጤልዋ ይጓዙ ዘንድ፥ ቀድመውም የአንባዎቹን መግቢያ ይይዙና የእስራኤልን ልጆች ይዋጓቸው ዘንድ ከእርሱ ጋራ የተሰለፉ ጭፍሮቹንና ወገኖቹን ሁሉ አዘዛቸው።'),
  ('4b2e99f4-19bf-5168-a185-53cdce7c6cd7', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 2, 2, 'በዚያም ቀን ጽኑዓን አርበኞች የሆኑ ኀይለኞች ሰዎች ሁሉ ወረዱ፤ እነዚያም ጓዝ ከሚጠብቁ ካልከበቡ ከብዙ አርበኞች ሰዎች በቀር መቶ ሰባ ሺህ እግረኞችና ዐሥራ ሁለት ሺህ ፈረሰኞች ነበሩ።'),
  ('b2930d98-b508-5d98-a031-fca406d47d2a', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 3, 3, 'በቤጤልዋ አጠገብ፥ በአውሎን በውኃው ምንጭ አጠገብ ሰፈሩ፤ የሰፈራቸውም አቆልቋዩ እስከ ዶታይምና ቤጤልዋ ድረስ፥ ወርዱም በአሴዴራሎም አንጻር ከቤጤልዋ እስከ ቅያሞስ ደረሰ።'),
  ('166a6225-d23f-5a1a-a897-0f1ee3c24e89', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 4, 4, 'የእስራኤልም ልጆች ብዛታቸውን በአዩ ጊዜ እጅግ ደነገጡ፤ እርስ በርሳቸውም፥ “እነዚህ ሰዎች ዛሬ ምድርን ሁሉ ይሸፍኗታል፤ ተራራም ቢሆን፥ ኮረብታም ቢሆን፥ ቈላም ቢሆን ብዛታቸውን የሚችል የለም” ተባባሉ።'),
  ('9a303240-9838-5f31-a1a3-2093bb6f078a', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 5, 5, 'ሁሉም መሣሪያቸውን ያዙ፤ ባንባቸውም እሳት አነደዱ፤ በዚያችም ሌሊት ሁሉ ሲጠብቁ አደሩ።'),
  ('ebd3c8cb-1d61-530a-aa00-762253fab43e', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 6, 6, 'በሁለተኛውም ቀን ሆሎፎርኒስ በቤጤልዋ ባሉ በእስራኤል ልጆች ፊት ፈረሶቹን ጫነ።'),
  ('ec89384d-eece-5703-a2a9-7caebffb9c35', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 7, 7, 'የከተሞቻቸውን መግቢያ ያዩ ዘንድ፥ የውኃቸውንም ምንጭ ይከቡ ዘንድ፥ ወደዚያም አርበኞች ሰዎች ቀድመው ይደርሱና ይከቡ ዘንድ ጕበኞችን ላከ።'),
  ('8d0e55ff-03bf-52c2-aac3-ce3e9d750455', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 8, 8, 'እርሱም ከሠራዊቱ ጋር ፈጥኖ ሄደ፤ አርበኞች የሆኑ የኤሳው ልጆች አለቆችም ሁሉ የሞዓብ ወገኖች ሹሞች ሁሉና የባሕር ዙሪያ ገዢዎች ወደ እርሱ መጡ።'),
  ('f0c29857-1384-5c70-a352-827607927eb3', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 9, 9, 'እንዲህም አሉት፥ “አቤቱ በሠራዊትህ ላይ ጥፋት እንዳይሆን ቃላችንን ስማ።'),
  ('c887750b-8116-5ba9-aecb-18b214f0d0b8', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 10, 10, 'እነዚህ የእስራኤል ልጆች ወገኖች በሚኖሩባቸው አንባዎቻቸውና ኮረብታዎቻቸው ነው እንጂ በጦራቸው የሚተማመኑ አይደሉም፤ ለአንባዎቻቸው መውጫ የላቸውምና፤'),
  ('47bec83f-c4ad-58fe-ad6f-8697bf261288', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 11, 11, 'አቤቱ አሁንም በሰልፍ ሥርዐት አቷጋቸው፤ ከሠራዊትህ አንድ ሰው ስንኳ የሚሞት አይኑር።'),
  ('7f41a10d-1fd3-58f4-a1b8-f4c3428cfc00', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 12, 12, 'ነገር ግን አንተ ከሠራዊትህ ጋር በሰፈር ጠብቃቸው፤ አሽከሮችህና የሠራዊትህ አርበኞች ሁሉ ከተራራው በታች የሚፈልቅ የውኃቸውን ምንጮች ሁሉ አጽንተው ይጠብቁ።'),
  ('5489f3d2-992e-562d-a9ba-c84825911e68', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 13, 13, 'በቤጤልዋ የሚኖሩ ሰዎች ሁሉ ከዚህ ውኃ ስለሚቀዱ ውኃ ጥም ይገድላቸዋል፤ ሀገራቸውንም ለአንተ ያሰገዛሉ፤ ሠራዊቶቻችንና እኛም ላንባቸው ቅርብ ወደ ሆነ ቦታ ወደ ኮረብታቸውም ራስ እንወጣለን ካንባቸው አንድ ሰው ስንኳ የሚወጣ እንዳይኖር በዚያ ሰፍረን እንጠብቃቸዋለን።'),
  ('e856f831-6482-5020-a28b-f981dd9f8048', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 14, 14, 'እነርሱ፥ ሚስቶቻቸውና ልጆቻቸውም በረኃብ ይጠፋሉ፤ ሳይዋጓቸውም ባገራቸው ጎዳና ይወድቃሉ።'),
  ('c1e5dcb0-4ecf-51c0-a3ac-2a8836f921c7', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 15, 15, 'ከድተዋልና፥ በሰላምም አልተቀበሉህምና ጽኑ በቀልን ትበቀላቸዋለህ።”'),
  ('83564a7f-5538-580b-a66f-7880cf3767c7', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 16, 16, 'በሆሎፎርኒስ ፊትና በሠራዊቱ ሁሉ ፊት ቃላቸው ደስ አሰኘ፤ እንደ ተናገሩም ያደርጉ ዘንድ አዘዘ።'),
  ('78e40a3f-67d8-5d9b-a272-a39011ff4eb4', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 17, 17, 'የአሞን ልጆች ሠራዊትም ተጓዙ፤ አምስት ሺህ የሚሆኑ የአሦር ሠራዊትም ከእነርሱ ጋር ነበሩ፤ በአውሎኒም ሰፈሩ፤ የእስራኤልንም ልጆች ምንጮችና ውኃቸውን አስቀድመው ያዙ።'),
  ('d6593806-f00d-54d4-aaa1-74c75f1e42c3', '786c026b-2dd7-571a-a30a-980c020dd220', '9de50d31-d137-5f27-aa1a-5639d1a3a59f', 18, 18, 'የኤሳውና የአሞን ልጆችም ወጥተው በዶታይም አንጻር ባሉ ተራሮች ሰፈሩ፤ ከእነርሱም በምኩር ወንዝ ባለ በኩሲ አጠገብ ባለ በኤቄሬቢን አንጻር ወደ ደቡብና ወደ ምሥራቅ ሰዎችን ላኩ። የቀሩት የአሦር ሠራዊቶች ግን በምድረ በዳ ሰፈሩ፤ ሀገሩንም ሁሉ አለበሱት፤ ከዚህም በኋላ ጓዛቸውን ከእነርሱ የሚበዛ የሌለ ሠራዊታቸውንና ብዙ ገንዘባቸውን አጓዙ።'),
  ('a3b7c519-47fa-5a5b-a322-b05565bf817d', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 1, 19, 'ጠላቶቻቸው ስለ ከበቧቸው፥ ከመካከላቸውም መውጫ ስለሌላቸው ሰውነታቸው ተጨንቃለችና የእስራኤል ልጆች ወደ አምላካቸው ወደ እግዚአብሔር ጮኹ።'),
  ('22816fe5-6802-5134-abe5-fd560c3e4e8f', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 2, 20, 'አሦራውያንም ከሠራዊቶቻቸው ሁሉ ጋር አርበኞቻቸውም በፈረሶችና በሰረገላ የተቀመጡ ሰዎችም ከበዋቸው ሠላሳ አራት ቀን ተቀመጡ፤ በቤጤልዋ የሚኖሩ ሰዎችም በዕቃቸው ያለ ውኃቸው ሁሉ አለቀ።'),
  ('557eba29-575d-5ca7-ad08-3a93287c906f', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 3, 21, 'የሚጠጡት ላንድ ቀን የሚያረካቸው ውኃ አልነበራቸውም፤ በመስፈሪያ እየመጠኑ ወደ መጠጣትም ተመለሱ።'),
  ('2e036ca7-d256-51fb-a94d-926e6cbb9b89', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 4, 22, 'ልጆቻቸውና ሚስቶቻቸው፥ ጐልማሶቻቸውም ተጨነቁ፤ በውኃ ጥም አለቁ፤ በከተማውም አደባባይና በበሩ ጎዳና ወደቁ፤ ከዚህም በኋላ ምንም ኀይል አልነበራቸውም።'),
  ('8081da8b-11f4-531c-acb2-2424e34dd09f', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 5, 23, 'ሕዝቡ ሁሉ፥ ጐልማሶችና የከተማው አለቆችም፥ ልጆችና ሴቶችም ወደ ዖዝያን ተሰበሰቡ፤ ቃላቸውንም አሰምተው ጮኹ። በአለቆቻቸውም ፊት እንዲህ አሉ፦'),
  ('8b7f7d93-6b88-50f9-af23-cde0a2174b17', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 6, 24, '“በእኛ ላይ ታላቅ ጉዳትን ታደርሱብን ዘንድ ከአሦር ሰዎች አሽከሮች ጋራ በሰላም በጎ ነገር ባልተናገራችሁ በእናንተና በእኛ መካከል እግዚአብሔር ይፍረድ።'),
  ('96fde0d7-a50a-515f-a601-039e326d53e9', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 7, 25, 'አሁንም የሚረዳን አጣን፤ በፊታቸውም በውኃ ጥምና በጽኑ ጥፋት እንጠፋ ዘንድ እግዚአብሔር በእጃቸው ጣለን።'),
  ('f7e77238-b924-51a3-ad66-c726133f2ac6', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 8, 26, 'አሁንም ተገዙላቸው፤ ይዘርፉም ዘንድ ከተሞቻችሁን ሁሉ ለሆሎፎርኒስ ወገኖችና ሠራዊት አሳልፋችሁ ስጧቸው።'),
  ('0b376e51-3ed7-5764-a144-9aa4ebce0d6e', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 9, 27, 'ሰውነታችን እንድትድን፥ የልጆቻችንንም ሞት በዐይኖቻችን እንዳናይ በውኃ ጥም ከምንሞት ቢዘርፉንና ብንገዛላቸው ይሻለናልና፥ የሚስቶቻችንና የልጆቻችን ሰውነትም አልቃለችና።'),
  ('a5a0d904-9167-556c-a59f-7392c2d471cc', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 10, 28, 'እነሆ፥ ዛሬ በዚች ቀን ይህን ነገር እንዳታደርጉ ሰማይንና ምድርን እንዳባቶቻችን ኀጢአትና እንደ ኀጢአታችን የሚፈርድብን ያባቶቻችን አምላክ እግዚአብሔርን እናዳኝባችኋለን።”'),
  ('75ed867d-ab3b-5744-a18c-682c36a0c2fa', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 11, 29, 'በማኅበሩም መካከል ጽኑ ልቅሶ ሆነ፤ ሁሉም በአንድነት አለቀሱ፤ ቃላቸውንም አሰምተው ወደ እግዚአብሔር ጮኹ።'),
  ('29e9073f-a833-5f95-a906-84e7cb92c152', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 12, 30, 'ዖዝያንም አላቸው፥ “ወንድሞቻችን ሆይ! ሁልጊዜ በመከራው የሚጥለን አይደለምና ፈጣሪያችን እግዚአብሔር ቸርነቱን እስኪመልስልን ድረስ እመኑ፤ ዳግመኛም አምስት ቀን ታገሡ።'),
  ('e866214a-f8a5-51af-ac27-5c87eba33bc3', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 13, 31, 'እነዚህ አምስት ቀኖች ካለፉ በኋላ ረድኤቱ ካልመጣልን እንደ ተናገራችሁት እናደርጋለን።”'),
  ('e78f32de-2ec4-5035-a204-d9cd29136792', '786c026b-2dd7-571a-a30a-980c020dd220', '56f9ed6a-2507-5d82-a458-0695b1f3304a', 14, 32, 'ሕዝቡንም ወደየሰፈራቸው በተናቸው፤ እነርሱም ወደ ከተማቸው ግንብና አንባ ሄዱ፤ ሚስቶቻቸውንና ልጆቻቸውንም ወደ ቤታቸው ላኩ፤ በከተማም ፈጽመው የተጨነቁ ነበሩ።'),
  ('78411cad-51db-5399-aed3-ed0ff2b1e673', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '6702148b-319a-511b-a599-2eeb2de93461', 1, 1, 'በዚያም ወራት የእስራኤል ልጅ የሰለስዳይ ልጅ፥ የሰላምያል ልጅ፥ የናትናኤል ልጅ፥ የኤልያብ ልጅ፥ የኤልያስ ልጅ፥ የሐቂቆ ልጅ፥ የራወይል ልጅ፥ የጋዴዮን ልጅ፥ የአናንዮ ልጅ፥ የሕልቅያ ልጅ፥ የኦዝያል ልጅ፥ የዮሴፍ ልጅ፥ የሆክስ ልጅ፥ የሜራሪ ልጅ ዮዲት ሰማች።'),
  ('3f6cbff3-b692-511a-acee-058c7c5211e2', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '6702148b-319a-511b-a599-2eeb2de93461', 2, 2, 'ባልዋም ከነገድዋና ከሀገርዋ የሆነ ምናሴ ነበር፤ የገብስ አዝመራ በደረሰበት ወራትም ሞተ።'),
  ('4b6049f5-4ace-5b35-a91d-197843f5b0f4', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '6702148b-319a-511b-a599-2eeb2de93461', 3, 3, 'ነዶ ከሚያስሩ ሰዎች ጋራ በእርሻ ውሏልና ራሱን ምች መታው፤ ታምሞ ተኛ፤ በሀገሩ በቤጤልዋም ሞተ፤ እንደ አባቶቹም በሀገሩ በዶታይምና በበላሞን ባለ ቦታ ቀበሩት።'),
  ('9734efd4-a4fc-5daa-a15f-1664057c75c5', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '6702148b-319a-511b-a599-2eeb2de93461', 4, 4, 'ዮዲትም መበለት ሆና ሦስት ዓመት ከአራት ወር በቤትዋ ተቀመጠች።'),
  ('4565426e-886f-50b1-ac49-77842c12c138', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '6702148b-319a-511b-a599-2eeb2de93461', 5, 5, 'በቤትዋም ሰገነት ላይ የብሕትውና ክፍል አዘጋጀች፤ በወገቧም ማቅ ታጠቀች፤ የመበለትነት ልብሷንም ለበሰች።'),
  ('c98ab569-6376-58bc-ab6f-823b54070088', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '6702148b-319a-511b-a599-2eeb2de93461', 6, 6, 'በመበለትነትም በኖረችበት ወራት ሁሉ ትጾም ነበር። በሰንበት ዋዜማና በሰንበት፥ በመባቻ ዋዜማና በመባቻ፥ በበዓላትና በእስራኤል የደስታ ቀኖች ካልሆነ በቀር አትበላም ነበር።'),
  ('fc86f6b8-6cb3-581d-a88b-8d619a064c90', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '6702148b-319a-511b-a599-2eeb2de93461', 7, 7, 'መልከ መልካምና እጅግ ደመ ግቡ ነበረች፤ ባሏ ምናሴም ብሩንና ወርቁን፥ ሴቶችና ወንዶች አሽከሮችን፥ ከብቶቹንም፥ እርሻውንም ትቶላት ነበር፥ በእነርሱም ላይ ትኖር ነበር።'),
  ('a1e925f1-acb9-5a33-a8af-d771a1f65049', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '6702148b-319a-511b-a599-2eeb2de93461', 8, 8, 'ፈጽማ እግዚአብሔርን ትፈራ ነበርና በእርሷ ክፉ ቃልን የሚናገር አልነበረም።'),
  ('6cf31579-67e3-5199-a819-dec1bbcd26a6', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 1, 9, 'ውኃው ስላለቀ ሰውነታቸው ተጨንቃለችና ሕዝቡ በአለቃቸው ላይ የተናገሩትን ክፉ ነገር ሰማች፤ ዮዲትም ዖዝያን ለሕዝቡ የነገራቸውን ቃል ሁሉ፥ ከአምስት ቀን በኋላም ሀገራቸውን ለአሦር ሰዎች እንዲሰጡ እንደ ማለላቸው ሰማች።'),
  ('90c5d073-44ff-53cd-a89e-ffe3356f0a98', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 2, 10, 'ገንዘቧን ሁሉ የምትጠብቅ ሞግዚትዋንም ልካ ዖዝያንን፥ ከብሪኒንና ከርሜኒን፥ የከተማዋንም ሽማግሌዎች ጠራቻቸው።'),
  ('f00dc860-6158-5666-aa8b-4519b9b4453b', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 3, 11, 'እነርሱም ወደ እርስዋ መጡ፤ እርስዋም “ዛሬ በሕዝቡ ፊት የተናገራችሁት በጎ ነገር አይደለምና በቤጤልዋ የሚኖሩ ሰዎች ሹሞች ሆይ! ስሙኝ እግዚአብሔር በእነዚህ በአምስቱ ቀኖች ባይረዳችሁ ሀገራችሁን ለጠላቶቻችሁ አሳልፋችሁ ትሰጡ ዘንድ በእግዚአብሔርና በእናንተ መካከል የተማማላችሁትን መሐላ በዚህ አጸናችሁ።'),
  ('1db887f6-3bb6-544f-addb-6f9002c960b9', 'f65bb0ce-e487-5880-a0ad-91db70cbfd6e', '5b5b690e-1ef9-562f-a09b-771ce24f6d4c', 4, 12, 'አሁንም በዚች ቀን እግዚአብሔርን የምትፈታተኑት፥ በእግዚአብሔርና በሰው መካከል የተነሣችሁ እናንተ፥ ምንድን ናችሁ?')
